window.__D("text/maamarei-admur-haemtzai/c007",{"p":[[1900640344,"כידוע, ולזה אומרים שמע ישראל דוקא כידוע שזה[ו] למסור נפשו באחד בפסוק ראשון, ואח\"כ הציווי ואהבת בבחי' התפעלות הנפש שצריך לצווי ביגיעת הנפש ונקרא פולחנא דרחימותא כמבואר וידוע לכל. אך תוכן זה"],[1900640352,"[הענין] הוא ענין הכלל הנ\"ל דהיינו שיהיה עיקר ההתפעלות התפעלות אלוה דוקא ובזה עצמו יש ב' מדריגות הדביקות והאהבה כנ\"ל. והענין הוא כידוע"],[1900640360,"שיש בנה\"א ה' מדרגות נר\"ן ח\"י, והיותר נעלה הוא בחי' יחידה, והוא בחי' התקשרות ודביקות העצמי שדבוק וקשור בתמידות כמ\"ש בי' אחידא בי'"],[1900640367,"להיטא כו'. וישנו [גם] בכ\"א מישראל בכ\"ח לפושי\"ד, והוא אשר צריך לפרש ולבאר שיחה זאת היטב, בהיות שנראה בעליל בכל איש גם פחות הערך בנפש שפילה ונמוכה בהשגה ומדות כו'. כאשר ישמע איזה דבר בענין ההתבוננות באלקות כמו ביאור דסובב וממלא וכה\"ג תתפעל נפשו ביותר (בל\"א ער דער הערט זייער), וחוש זה אינו אלא מצד שרש נפשו דהיינו בחי' אלהות שבנפשו, והוא בחי' יחידה שבו שהוא למעלה מכח החכ' שבנפשו, והוא ענין ובחי' התקשרות עצמיי' שלו הנק' דביקות שתדבק ותמשך הנפש מצד בחי' עצמי' אלקית שבעצם נפשו הנמשכת ונדבקת ממילא כאשר יומשך הניצוץ אחר השלהבת וכה\"ג וזהו הנק' התפעלות אלוה ממש."],[1900640372,"<b>אך</b> לכאורה יפול בזה טעות מן הקצה כו', כי ודאי נמצא ממש בחי' דביקו' בדוגמא זאת בקל מאד לכל אבל היא הפכית לגמרי שאינה בגדר התפעלו' אלוה כלל וכלל, והוא מה שנראה בעליל שהתפעלו' רוב ההמון הוא בהתפעלות חיצונית בדמיון שוא בנפשם ולבבם בתפלתם הבאה בבחי' צעקה חיצונית בלב בשר בלתי אור וחיות פנימי כלל ולא לה' כלל, כי אין במוחו אז שום התפעלות והתבוננות אלוה כלל רק בדרך כלל כו', וגם זה לא שיש בזה ענין השמיעה הנ\"ל והמשכת הנפש בפנימית שלה כלל, כי גם בהתבוננות זאת דרך כלל אין לו בה בחי' השמיעה (בל\"א דער הערט כו') כלל, והגם שקורין העולם גם לזה בשם דביקות או התלהבות, אבל הוא דביקות שוא לגמרי ממש היפוך מדביקות אמיתי הנק' התפעלות אלוה הנ\"ל, והוא בדוגמא ממש באותו אופן של דביקות האמיתית אבל אין זה הדביקות בה' כלל, וכל דביקות שאינו"],[1900640376,"לה' אינו כלום וכמ\"ש ואתם הדבקים בה' דוקא חיים חי יקרא, והדיבוק חיצוני הנ\"ל שלא לה' כמת ממש יחשב, כי אין נפשו חי ממקור חוצבה באלהות כלל וכלל כו', וזהו הנק' עובד א\"ע (בל\"א דער הערט זיך [מער ניט] כו') ולא עובד ה' כלל, וגם לא נקר' עובדי ה' בגופם, כי עובדי ה' בגופם עכ\"פ עובד ה' נק', והוא התפעלות של אהבה לה' דוקא באהבה הטבעית הגופנית [ג\"כ] שגם נה\"ט הבהמית יאהב כו' כפשוטו של מקרא ואהבת בכל לבבך וארז\"ל בשני יצריך כו', הגם שאין זה בחי' התקשרות עצמית דנה\"א הנ\"ל אבל עובד ה' בגופו נק', כי הרי מתפעל לבו ובשרו הגשמי מאל חיי החיים דוקא כמ\"ש לבי ובשרי ירננו אל אל חי, ובשרי היינו הלב בשר ממש בהתפעלות לב בשר בתענוג גשמי יתענג על ה' בלבו הגשמי (ויש בזה מעלה ומדרגה היותר נעלה שמגיע לבחי' האהבה בתענוגים שבבחי' עצמיות דיחידה הנ\"ל כמש[י] \"ת בסמוך). ולעומת זה ממש הוא ענין התפעלות לב בשר החיצוני ברתיחת והתלהבות [אש] זרה הבאה מרתיחת הדמים בלבד, אשר לא באש ה' כלל וכלל כ\"א"],[1900640380,"התגלות לבו ובשרו בחמימות רשפי אש להחם א\"ע במה שירגיש בחי' התפעלות והיא מוטעת מאד מאד (בל\"א זייער גינא[רט בייא זיך כו') עד שיבא לבחי' [דמיון] הבלי שוא ושקרים כוזבים מאד, כידוע זה גם במילי דעלמא (ובדרך הלצה זה שאמרו לא תתפללו על דמכם שרמז שלא יהיה מתפלל בדם בלבד אלא בנפש בדם כו'), ועז\"נ לא יחפוץ כסיל בתבונה כ\"א בהתגלות לבו בלבד, וכידוע לכל ואריכות הדברים בזה אך למותר, כי מובן לכל מי שטעם טעם אמיתי [בנפשו] בדא\"ח פעם ושתים שתשנא נפשו מאד דרך שקר ומוטעה כזה, [ו] לא תסבלנו כלל מצד בחי' הגסות וההתפשטות חיצונית המסתעף אח\"כ מדביקות זרה הזאת לומר אני ואפסי עוד מצד הרגשת עצמו ביותר, עד שיבא לכלל הגיאות והתנשאות כאחד הגיאים הגשמי' בעניני עה\"ז ממש כו', גם יפול הנופל מזה בתאוות עצמ[ו] כו' [ויכול] למשוך באש זרה לגמרי כידוע בכמה מיני נפילות שנפלו [רבים] כו', והיותר מקושר ודבוק בבחי' התפעלות אלהות הנ\"ל יותר ישנא אש זרה זאת המנגדת ממש, וענין זה דק מאד מאד ונמצא בו רבוי חלוקים שונות בדקות המדרגות וגם רוב מביני מדע לא יבחינו בזה תכלית ההבחנה בכל פרטי חילוקי' רק בכללו' ההבחנה בין ההרגשת לב בשר כו' הנ\"ל ובין התפעלות אלהי' ממש דהיינו מ\"ש לבי ובשרי ירננו כו', והוא מה שהתבוננות האלהות ירגיש הלב הגשמי ויתפעל גם הוא כנ\"ל, דאע\"פ שבא במורגש ביותר ודומה ממש להרגשת התפעלות חיצוני' דלב בשר בהתפעלות עצמותו שלא בהתפעלות אלהות כלל וכלל הנ\"ל. והנה ההבחנה בזה איך שהם ב' הפכים ממש מן הקצה כו' זהו המובן לכל יודע טוב טעם ודעת בד\"ח, אבל ברבוי פרטים הנמצאים בזה זה[ו] הנעלם מרוב מביני מדע גם בגדולים שבהם עד שישימו חושך לאור ואור לחושך ממש כידוע לי ברור שיש רבים שמטעים א\"ע שמדמים בנפשם בהתפעלות לב בשר בהרגשה האלהית, והוא באמת הרגשה גופני' בלבד, רק קצת תערובות מאור האלהי בהעלם גדול נמצא בזה מבלתי נודע להם כלל, והוא הנקר' רשימו מן ההתבוננות כידוע.\n<b>ואפרש</b> נא שיחתי כי לא לדרשא קאתינא כ\"א להוציא לאור תכלית הענין בגלוי האלה[ו] ת האמיתי' בנפשינו וכו'. והקדמה בזה צריך להביא"],[1900640384,"דוגמא לענין זה ממה שנמצא אצלי בכתובים מהני מילי מעליותא מבחי' פנימית ומתיקות תורת אאמו\"ר ז\"ל נ\"ע על ענין מאמר הזוהר הקדוש (פ' פקודי דף רל\"ג ע\"א) והנה איש מראהו כמראה הנחושת ופתיל פשתים וקנה המדה בידו כו' דמשחת' קדמאה בגוונין קדישין חושבן דיליה סליק ל\"ב (שהוא אורך היריעה ך\"ח ורוחב ד') ומשחתא תנינא דלבר דאיהו לחפיא על דא סליק לחושבן ד\"ל (כי יריעות עזים אורך שלשים כו') עד דא גרע וסליק ודא סליק וגרע כו', ויראו העתקת הביאור על זה הנמצא בכתובים אצלי, ומתוכן יובן כל עיקר ענין זה ממש בכל פרטי חילוקיו. בהיות מובן תמצית הענין שעיקר ההפרש בין סט' דקדושה לסט' דנוג\"ה. שבקדושה בחי' הכלי שהוא בחי' הישות של האור הוא בבחי' הבטול בתכלית, ובחי' הכלי דנוג\"ה יש מורגש בתוספות מרובה על העיקר ותוספות זה גרעון כו'. וביאור [ענין] זה יובן מענין חסד לאומים חטאת, כי מפני שהאור החסד הטוב בבחי' נפרד ע\"כ הכלי שלו שהוא בחי' יש[ות] שלו הוא מתפשט ביותר ממדת האור והוא גירעון עד שנקרא חטאת. וכדוגמא זו אמרו צדיקים אומרים מעט ועושים הרבה, פי' אומרים הוא בחי' הכלי המגלה אומר מעט הוא בחי' בטול כו' ועושי' הרבה,"],[1900640387,"וברשעים הוא להיפוך אומרים הרבה בבחי' גסות והתפשטות היש דכלי ועושים מעט מפני בחי' גרעון האור כו' כנ\"ל, וכה\"ג ממש אנו רואים בכל ענין [ו] בחי' הגוזמא רבה הנראית בהתפעלות חיצונית המוטעת בלב בשר החיצוני הנ\"ל, שזהו בא מבחי' התפשטות יש דנוגה, והוא גרעון הפנימית בתכלית עד שיהופך מטוב לרע ח\"ו כו' ולהיפוך בסט' דקדושה בניצוץ האלהי גם בחי' הישות בהרגשת לב בשר הנ\"ל הוא בא בתכלית בחי' הבטול בהעדר הרגשת עצמו לגמרי כו', ומה שיוגרע יותר ולא ירגיש ה\"ז בא מצד תוס' האור וחיות פנימית ביותר כו', וכנראה בעליל כללות ההפרש הזה לכל טועמי טוב טעם ודעת בדא\"ח והוא שרש ענין ההבחנה כלל[י] ת הנ\"ל. ולידע מזה כל הסימנים בפרטי פרטיות חלוקות המדרגות מבלי הטעות א\"ע כלל. יש להבין תחלה בשרש ענין העדר הרגשת עצמותו לגמרי בהתפעלות אלהות המורגש בלב בשר הנ\"ל. דלכאורה א\"א להאמין במורגש כזה שיהיה בתכלית העדר המורגש שזה ב' הפכים בנושא א' כו'. ויש להקדים לזה בענין הניגון מה ענינו,"],[1900640390,"וכידוע בענין המאמר דר\"מ היה מנגן בצלותא בכל מיני ניגון כו', להיותו כולל ס\"ר נשמות ישראל, וכל נשמה בעלותה בשרש מקור חוצבה הוא ע\"י השיר דוקא והוא בחי' התפעלות העצמית הנ\"ל באהבה בתענוגים כפי אופן שרשה למעלה בעונג העליון, והכולל הכל הוא רע\"מ ע\"כ היה מנגן בכל מיני ניגון כמ\"ש במ\"א. ותחלה יש להבין מהות התפעלו' הניגון שהוא בחי'"],[1900640393,"התפעלות פתאומי' דוקא בלתי בחירה ורצון שכלי כלל, והוא התפעלות מורגשת ובלתי מורגשת בעצמו מצד שאינה באה מצד עצמו לכוין לעשות התפעלות כ\"א ממילא ומאליו בלתי נודע לו. ומפני שזהו כאלו אינו מרגיש ונודע לו כלל באותה שעה ממש זהו הנק' העדר הרגשת עצמו בזה כלל, אבל מ\"מ התפעלות מורגשת הוא. ויובן זה ע\"ד דוגמא ממה שאנו רואים בהתפעלות פתאומית שאדם מתפעל [בשמחה] רבה בהגיע לו איזה בשורה טובה וכה\"ג, שבודאי מורגשת התפעלות זאת בלבו עד שיעשה תנועות חזקות מאליו וממילא והוא הסיפוק בידיו כידוע, והוא בלתי בחירה ורצון כלל וכלל רק ממילא ומאליו מספק, והוא האות על היות שאיננו מרגיש בעצמו כלל אם מתפעל הגם שמורגש' בלבו אבל כאלו אינו יודע מזה כלל, והוא להיות שההתפעלו' הוא אמיתי' רק מצד עצם הדבר הטוב שנפשו קשור [בו] שאז לא"],[1900640395,"ירגיש כלל אם הוא מתפעל, כי אין הכוונה להתפעל רק שההתפעלות מאליו נעשית עד שיוכל להיות שאינו יודע כלל מאותה התפעלות, וכמו שנראה להיפוך בהתפעלות הכעס ג\"כ שאינו יודע ומרגיש בהתפעלות כו', משא\"כ להיפוך בהתפעלות הנעשית על ידי הכוונה בתחלה כמו שמייגע א\"ע בהתבוננות רבות עד שמתפעל שעיקר חפצו רק בהתפעלות זאת ומצפה ומייחל מתי תהיה [וא\"ל יצטער] ובבואה ישמח בה, אם הוא במורגש בחמימות התלהבות בכי טוב כרצונו ואם לאו יצטער כו'. והנה בזה יש רוב מאנ\"ש שנבוכים בזה מאד זה או' בכה כו' זה אוסר לגמרי וזה מתיר ויש ממוצעים, וצריך לפרש ולבאר היטיב שיחת זה הענין, כי זה הוא קוטב ויסוד הכללי לקבלת דא\"ח בתפלה כו':"],[1900640397,"<b>ב</b> והנה לפי הנראה יש בזה ה' מדריגות זו למעלה מזו, וכל אחד על מקומו יבוא ולא יטעה הטועה כו'. הא' הגרוע שבכולם והוא שכל עיקר חפצו אינו רק להיות מתפעל בלבד ויהיה לו מזה חיות, שזהו בערך המדרגה הפחותה שבכולם עד שקרוב לערך ענין התפעלות לב בשר החיצוני הנ\"ל בהרגשת עצמו לבד, שאינו התפעלות אלוה כלל, כי אינו רוצה ומכוין לבחי' אלקו' כלל ואין כוונתו ומגמתו שיהי' אלהות שוכן בנפשו, או שתהיה נפשו קשורה באלהות כו', רק שיהיה לו חיות דבר מה להיות בבחי' יש וכו'. אך"],[1900640399,"אעפ\"כ איזה תערובות טוב יש בזה בהעלם והוא מבחי' אהבה המסותרת דהיינו שנעלמת בלבוש זר שלו שהוא רוצה, רק עכ\"ז בהעלם עיקר רצונו שיהיה לו התפעלות לה' דוקא ובלתי לה' לא היה רוצה כלל בכל זה, הגם שבגילוי אין הענין כן, כי לא יעלה על לבו תוכן הענין שהוא להיות בחי' [גילוי] אלהות בנפשו ולא מצד הנאות עצמו רק מצד חפצו באלהות, שע\"ז אמר קרבת אלהים לי טוב וכידוע."],[1900640401,"<b>וזה</b> המדרגה הב' שלמע' מזה, שהוא ענין השמיעה מרחוק הנ\"ל ששומע ומתבונן באלהו' דוקא ומבין היטב עד שנתאמת ונתקבל אצלו במוחו עכ\"פ שהוא דבר אמת לאמיתו (בל\"א עס לייגט זיך אין מוח זייער גוט כו'), אבל הענין רחוק ממנו ושואל איזה תועלת בנפשו יבוא מזה, והיינו מצד"],[1900640403,"שגוף ענין ההתבוננות באלהות יקר בעיניו מאד ונתקבל אצלו בבחי' הודאה ותגדל ותרומם ענין אלהות בתכלית הרוממות במוחו ו[גם ב] לבו, אבל רוצה וחפץ שיהיה ענין אלהי הזה נקבע בנפשו ולבבו בבחי' גילוי ומורגש ולא בהעלם ומרחוק (בל\"א עס איז דער ענין ווייט [זייער] פון אים עס גיהערט ניט צו אים און ניט שייך כלל צו אים וכה\"ג) וכידוע. וזהו מדרגה יותר טובה שקרוב לבוא לבחי' התפעלות אלוה עכ\"פ, שהרי עכ\"פ התבוננות אלהו' תגדל בנפשו וחפץ בה מאד ועיקר מגמתו ורצונו להתקרב אליה. אך שמייגע א\"ע ואינו פועל התפעלות אלהו' ממנה כלל בלב ומוח ואין זה לעצמו רק לאלהות"],[1900640405,"בלבד כי אך קרבת אלהים יחפוץ שיהיה קבוע בנפשו דוקא, וזהו עיקר התחלת המבקשים ודורשים אלהים באמת ובתמים בכוונה רצויה לאלהו' דוקא.\n<b>והמדרגה</b> הג' למעלה מזו הוא הנקר' מחשבה טובה שמצטרפת למעשה דהיינו באהוי\"ר שנוגע למעשה בלבד, וביאור הענין להיות כי"],[1900640406,"המדריגה הב' הנ\"ל הנה גם שכוונתו רצוי' לאלהות דוקא, היינו רק שרוצה שיהיה קרוב ולא רחוק מאלהות, ורצון זה בא מצד יוקר ענין גדולת ה' במוחו, אבל לא שנתפעל במוחו מאומה עדיין כי עדיין רחוק הענין ממנו לגמרי, רק שרוצה שיתקרב אליו ולא נתקרב עדיין. וזהו רק בחי' הודאה במוח בלבד ולכך לא יקרא בשם מחשבה טובה רק בשם מחשבה סתם. ויובן זה ע\"ד דוגמא במילי דעלמא שאנו רואים שיש ב' מיני מח', הא' מח' שחושב האדם בענין איזה דבר טוב ומשובח שגדול בעיניו מאד כמו באוצר הון יקר שהוא ברשות אחר, או בהפלגת גדולה וכבוד של מלך ושר וכה\"ג, שנק' מחשבה קרה שאין זה נוגע ושייך אליו כלל וכלל, כי אין הדבר בא אליו לא הממון ולא הגדולה רק שחושב בו מצד יוקרו וחשיבותו בעיניו ורוצה מאד שיבוא אליו ענין טוב ומשובח כזה כו'. והמחשבה הב' היא מחשבה שחושב בענין טוב הנוגע לעצמו, כמו שמרויח במו\"מ טוב או בכבוד וגדולה או השגת הון יקר שמשיג לעצמו, שמח' כזאת באה אליו בבחי' התפעלות והמשכות הנפש קצת שנק' הזזה ממקומו כנודע בחוש שכאשר יבוא לאדם איזה בשורה מעסק טוב הנוגע ביותר, שיטריד כל כח מחשבתו ונדבק היטב במחשבה זו בהתפעלות הנק' דביקות המח' (בל\"א צו גיקלע(ט זייער שטא[רק דיא מחשבה א[ז עס א[רט און רירט אים זייער כו'), והוא הנקר' שמיעה שבמחשבה (ער הא]ט גוט דער הערט אין דער מחשבה כו'), וסימן לזה הוא הטרדה והזזה ממקומו קצת (בל\"א פא[ר טרא]גין און פא[ר נומען כו'). וכך יובן בהתבוננות אלהות במחשבה כזאת שנדבק היטב בה"],[1900640407,"כענין הנוגע לעצמו הנ\"ל, והוא הנק' מח' טובה שמצטרפת למעשה עכ\"פ דהיינו הסתעפות תולדה שנולד ממנו הוא אהבה ויראה שנוגע למעשה עכ\"פ, כי במחשבה קרה הנ\"ל הגם שרוצה להתקרב ולהתפעל אך עדיין לא נתפעל גם בבחי' שמיעה שבמחשבה אלא מרחוק לבד יודה בהודאה כנ\"ל, ותולדה שנולד ממנו אינו רק בחי' וענין הבושה שמתבייש דהיינו שנופל בלבו בושה על עצמו איך שהוא רחוק ואיכות שפלותו, וגם ענין כללות שפלות עוה\"ז החומרי, אחר שנתקבל אצלו ההתבוננות אלהו' עד שיאנח וכה\"ג (בל\"א א[רא]( פא[ל בייא זיך זייער שטא[רק און דיא וועלט ווערט זייער א[רא]( גיפא[לין כו'). ולא נולד מזה רק בחי' ההסכם להיות סור מרע כו', כלומר מאחר שכן מהראוי והיושר מאד מאד להיות סור מרע ועשה טוב כו'. והוא מדריגה היותר קטנה אבל יכול לבוא לג\"ע התחתון מפני שיש בזה בחי' אלהו' עכ\"פ מצד התבוננות האלהו', רק שלא נקרא אהבה ויראה ממש בהתפעלות (משא\"כ מדרגה הגרוע מכולם הנ\"ל שאין בו בחי' אלהו' כלל רק שרוצה בהתפעלות ולא באלהות כלל כנ\"ל רק בהעלם גדול כו'). אבל מחשבה טובה הנ\"ל על זה אמר גם כן שמע ישראל כו' ואחר כך ואהבת שאין העיקר רק התפעלות השמיעה הנ\"ל במחשבה זו ונולד מזה אהבה, אך לא נתפעל בלבו עדיין מאומה רק במחשבה, ואהבה זו אינה רק לענין מעשה ולא לבחי' הפנימית כלל כמו בהתפעלות הלב כלל, אבל למעשה דהיינו להיות בבחי' סור מרע כו' למעלה הוא מבחי' ההסכם הנ\"ל שנולד ממחשבה קרה הנ\"ל, ולא באה האהבה לו רק מצד היושר בלבד שאינה בבחי' התפעלות במח' אך באה בבחי' התפעלות במחשבה, כמו לחפוץ בתשוקה גמורה במח' עכ\"פ להיות גילוי אלהות במעשה טוב ולהתרחק ביותר מההיפוך המנגד לאלהות. וכ\"ז נקרא דחילו ורחימו, הגם שנוגע למעשה בלבד אבל יש"],[1900640408,"בהם אור וחיות גדול במחשבה, כמו ע\"ד משל במחשבה הנוגע מאד לעצמו במילי דעלמא שיש בה אהבה במח' בהתפעלות המחשבה עכ\"פ ויראה מהיפוכו כמו מן ההיזק ואבדון כו' כנ\"ל וד\"ל.\n<b>והמדרגה</b> הד' שלמעלה מזו, הוא אשר מחמת ההתבוננות אלהו' שמתפעל במח' בכי טוב כנ\"ל. מיד מתפעל בלבו בבחי' התפעלות מורגשת באור וחיות גדול ופנימי' יותר מהתפעלות המחשבה הנ\"ל (ואין זה בחי'"],[1900640409,"התפעלות אלהו' ממש שמרגיש גם הלב הנ\"ל שהוא בנשמה האלהית שמתפשט גם בגוף שלמעלה הרבה גם ממדרגה החמישית שיתבאר), וע\"ז נאמר ואהבת בכל לבבך דוקא, והוא עיקר המצוה בעבודה שבלב לייגע א\"ע במחשבה כ\"כ עד שיתפעל הלב דוקא ונקר' פולחנא דרחימותא פולחנא ממש"],[1900640410,"ביגיעה רבה, כי במילי דעלמא מיד שעולה במחשבה דבר טוב ומתפעל במוח מיד נוגע התפעלות זו בלב שמתפעל הלב מיד ברשפי אש התשוקה או ההיפוך במרירות מדבר רע השנאוי במחשבה כו'. אבל בעבודת ה' לא בקל יומשך התפעלות בלב מהתפעלות המח', מטעם שבחי' אלהו' שבבחי' התבוננו' הזאת לא נמשך בגילוי בלב כ\"א בבבחי' מקיף במוח כו'. ויש בזה רבוי מדריגות שונות מאד באופן התפעלות הלב ויש שמתפעל בלב יותר מבמוח ויש שמתפעל בחדוה יותר כו', ועכ\"פ זהו הנקרא דו\"ר ממש אך שבדרך כלל נקרא דו\"ר טבעי' (אך הנה כ\"ז אינה נק' התפעלות אלהות שמצד הנשמה בלבד כמו שיבואר), וע\"ז נאמר קרבת אלהים לי טוב לי ממש וג\"כ נקרא אלהי בקרבי כו'. והיינו ג\"כ ענין לאהבה את ה' בלב דוקא כי הוא חייך מצד הנשמה כנ\"ל. והנה בחי' אהבה ויראה שנולד בהתגלות הלב כו' הוא בבחי'"],[1900640411,"פנימית אור וחיות גדול למעשה דסו\"מ כו,' היינו לעשות מ\"ע באה' וחשק גדול שיש פנימית אור וחיות במעשה זו ולהיפוך יתמרמר בהתפעלות [רוגז] על המנגד שהוא להתרחק מכל רע ולשמור א\"ע ממנו בהתפעלות, כמו שאדם עוסק במו\"מ בהתפעלות לבו ממש שכל דבר המועיל לעסק זה יעשה אותו בחשק וזריזות מצד האה' להרוויח ממון ויתרחק וישמור א\"ע מדבר המזיק לעסק זה ג\"כ בבחי' התפעלות הלב, וע\"ז הוסד שרש רמ\"ח מ\"ע שהוא נמשך מן האהבה דוקא כי האהבה שרש רמ\"ח מ\"ע, והיראה שרש שס\"ה ל\"ת בחי' חו\"ג שבלב, וז\"ש לאהבה ולעבדו כידוע, וה\"ז למעלה מהתפעלות אהוי\"ר שבמחשבה טובה הנ\"ל וד\"ל."],[1900640412,"<b>והמדרגה</b> הה' שלמע' גם מזו ה[וא] ענין ובחי' הכוונה שבלב שלמע' גם מהתפעלות הלב. וביאור הדבר להיות [ידוע] כי גם שמתפעל בלבו התפעלות גמורה בתשוקה וחדוה או מרירות כו' מחמת התבוננות, הנה בזו הרגע שמתפעל בלב מתקצר כל המשך אריכות הענין האלהי שמחמתו נתפעל ולא נשאר ממנו רק מה שנוגע אל ההתפעלות בלב בלבד, דהיינו העולה מתמצית המכוון הקיצור מכל ענין התבוננותו בממלא וסובב וכה\"ג שהוא העיקר ושרש הכוונה הנ\"ל דכולא קמיה כלא חשיב כו' וכה\"ג, ומה שמחמת זה הקיצור מתפעל הלב ביותר הנה בחי' קטנות יחשב לגבי עצם הכוונה שבלב באריכות הענין האלהי שמכוון במוחו ולבו שם באורך ורוחב שלמע' עדיין מלהביא לכלל התפעלות בלב, עד\"מ במילי דעלמא כאשר האדם מכוון בנקודת לבו בכל עומק דעתו בהפלגת איזה עסק טוב שכל נפשו נמשך אחריו אשר עדיין לא יוכל להביא בלבו הדבר בבחי' התפעלות כי נטרד מוחו ולבו כולו, רק בעצם איכות טוב הדבר ההוא כו' והוא הנקרא בחי' מוחין דגדלות שבחב\"ד"],[1900640413,"כו'. וגם ששם יש גם כן אהבה ויראה בהעלם אבל נק' דו\"ר שכליים בלבד שהוא למעלה מדו\"ר טבעיים שבלב הנ\"ל (וההפרש שבין דו\"ר טבעיים הנ\"ל ובין דו\"ר שכליים הנ\"ל, שבחי' טבעיים נבדלים מעצם ההתבוננות (ובל\"א נק' דער בכן דער פון א[ז עס איז א[זו בכן כו'), ודו\"ר שכליים אינו נבדל מעצם ההתבוננות כלל, אלא ממילא ומאליו באה בהכרח בלי בחירה ורצון כלל, ובלב ג\"כ באים דו\"ר זה ממילא כמו שמחה שמספק בידים כו' כנ\"ל, וסימן לזה הוא תמידות ההתפעלו' בכוונה זאת ולא תפסוק כלל כמו דו\"ר טבעיים שנופלים וחוזרים ומעוררים, וע\"כ לא יפול לשון יגיעה בדו\"ר שכליים כ\"כ [כו' ו] כמ\"ש במ\"א ע\"פ אלהים אל דמי לך כו' למען יזמרך כבוד כו' נהו\"ת קארי תדיר כו' וד\"ל. ולמעלה מזה ג\"כ הוא בחי' רצון הפשוט שלמעלה מעלה מבחי' ההתבוננות לגמרי רק רצון עצמי ופשוט שמחמתו נולד ונסתעף השכל כו' כידוע וד\"ל."],[1900640414,"<b>ונמצא</b> מובן ומבואר מכל הנ\"ל בחלק וסוג זה הכללי שהוא ההתפעלות במוח ולב הנעשה ונולד ע\"י הכנה דוקא בתחלה שהוא ההתבוננות עד המדרגה החמישית שהוא הכוונה עצמה שבחו\"ב המאיר בלב גם כן כנ\"ל. והנה מדריגה הא' הנ\"ל מה שאינו חפץ רק בהתפעלות בלתי התבוננות באלהו' כלל, זה קרוב לאש זרה הנ\"ל שאינ[ה] באש ה' ולא נחשב מכלל ה' מדריגות, כי ה' מדריגות הן לנגד נר\"נ ח\"י כידוע, ובחי' נפש בחי' עשיה היא בחי' ההסכם למעשה לבד שבאה מבחי' ההודאה ובחי' מחשבה סתם הנ\"ל שנק' בחי' נפש לבד, ובחי' רוח שיש בו חיות גדול יותר הוא בחי' התפעלות המחשבה טובה הנ\"ל כמ\"ש ותוכן רוחות כו' שהוא בחי' השמיעה טובה שבמח' הנ\"ל וכמ\"ש אכן רוח הוא באנוש כו'. אך בחי' נשמה הוא בחי' הארת המוחין דחו\"ב בלב כשמתפעל הלב באור וחיות פנימי יותר כנ\"ל, ועל זה נאמר ונשמת שדי תבינם בינה ליבא דוקא כו' וזהו ותוכן לבות כו', ובחי' חי' שהוא בחו\"ב עצמם כמו שהם בלי התפשטות עדיין בהתפעלות הלב מחמתם כנ\"ל שנקרא כוונה כו', ובחי' יחידה היא מדריגה הה' באמת שהוא בחי' הרצון העצמי הפשוט הנ\"ל שלמעלה מן הטעם ושכל לגמרי כי אין טעם לרצון כלל כידוע וד\"ל:"],[1900640415,"<b>ג</b> אך הנה כל בחינת ה' מדריגות הנ\"ל הכל הוא בנפש השכלית שנקר' נפש הטבעית החיונית, שגם היא תסכים ותודה בהודאה והתפעלות במוח והתפעלות בלב עד גם בחי' כוונה ורצון פשוט כו'. וכל זה נק' עובד ה' בגופו ולא [נק'] עובד ה' בנשמתו, כי בחי' הנשמה מצד עצמה הרי היא כח אלהי ממש, וכל ה' מדריגות נר\"נ ח\"י שבה הכל הוא בבחי' התפעלות אלהות ממש ולא התפעלות גופניות כלל, רק שמלובשת במוח ולב הגשמי ויבואו הארותיה והתפשטותיה גם במוח ולב גשמי ג\"כ בבחי' ה' מדריגות, והיותר תחתונה הוא מה שירגיש הלב התפעלות אלהות של הנשמה הנ\"ל. ותחלה יש"],[1900640416,"להבין היטב הדק בענין התפעלות אלהו' שמצד הנשמה, שזהו עיקר המכוון ויסוד אמיתי בבחי' גילוי אלהות באמת שזהו תכלית המכוון בדברי אלהים חיים בהתבוננות, והוא בחי' הדביקות הנ\"ל שנקרא חיים עצמיים וכמ\"ש ואתם הדבקים בה' כו' חיים כו' וכן כי הוא חייך כו' דרך כלל כנ\"ל בענין חלוקה הכללי' בין התפעלות אלהי' ממש להתפעלות חיי בשר כו'.\n<b>והנה</b> צריך לפרש ולבאר שיחה נאה זו [בהיות] שאנו רואים דבר הפלא ופלא בענין שמיעת אוזן בשכל אנושי בדברי אלהים חיים שיתפעל"],[1900640417,"השכל מאד, ואי אפשר לומר מצד שהשכל הזה עמוק יותר משאר שכל זולתו שהרי יש כמה שכליים עמוקים רחבים יותר. וגם הנה אנו רואים בחוש שיש שכל איש [ש] מתפעל ביותר בשמיעתו ויש שאינו מתפעל כלל וכלל, וכמו שמבואר למעלה בענין שמיעה מרחוק שאין הענין שייך אליו כלל וכלל רק שמתקבל אצלו לדבר אמת וכנ\"ל (בל\"א ער דער הערט נישט). ולכאורה יש לתלות הסיבה בכשרון הלב בעבודת ה' שזה יותר עובד בכשרון כו', ואינו כן, שיוכל להיות בלבו ירא אלהים ותמים בעבודתו ובזה אין לו חוש השמיעה כלל וכלל וכידוע בנסיון גמור, וא\"כ א\"א לומר רק שזה בא מכח הנשמה עצמה שיש בה כח אלהי' והתפעלותה התפעלות אלהי' יקרא דהיינו מצד אלהות בלבד, ע\"כ בשמיעתו בבחי' אלהו' תתפעל הנפש האלהי' התפעלות אלהו' מצד מקור חוצבה בלבד. ובזה יש חילוקי מדריגות, יש שהם מבחי' נפש בלבד ע\"כ לא יתפעל כ\"כ ומבחי' רוח יתפעל יותר כו'."],[1900640418,"<b>אמנם</b> תחלה יש להבין בעיקר ענין ההפרש בין התפעלות אלהי' שמצד הנשמה להתפעלות נפש השכלי' הטבעית במוח ולב כנ\"ל דלכאורה מה ההפרש יש בזהיח. והנה תוכן הענין בקיצור הוא כך, דהתפעלות הנשמה באלהות הגם שמתפעל ע\"י השגה וכה\"ג הכל הוא בחי' אלהו' ממש גם מצד ההשגה עצמה, שהרי היא השגה אלהי' ממש, ואין להשגת שכל נפש הטבעית הנ\"ל ערוך אליו כלל, כי הגם שבהשגת [שכל] הנה\"ט כאשר מתפעלת ג\"כ אין העיקר רק מצד אלהות שבהשג' זו, שהרי לא יתפעל מהשגת שכל אחר שאינו ענין אלהי כנ\"ל. אבל השגה זו מבחי' לבוש דנוג\"ה המסתיר על עצם האור האלהי, כי כל עיקר מחצב הנפש הזאת הטבעית בעשר כחות רצון ושכל ומדות ומחשבה ודבור כו' הכל הוא מבחי' לבוש דנוג\"ה המעורב טוב ורע כו', כמאמר רז\"ל הידוע דג' שותפים באדם אב ואם ממשיכים נפש הטבעית מדות ושכל אנושי כו' והקב\"ה נותן בו נשמה האלהית כמ\"ש ואתה נפחת בי כו',"],[1900640419,"וכמ\"ש בע\"ח דהנשמה מצד עצמה אין צריך תקון כי היא מעולם התקון שהוא עולם האצילות (וגם בחי' נפש דעשיה מאיר בה מחיצוניות הכלים דז\"א דאצי' כידוע דל' כלים דז\"א נעשים נר\"נ בבי\"ע כו', וא\"כ גם בעם הארץ שאין לו רק נפש דעשיה יש בה הארה מבחי' אצי' רק שנק' אצי' שבעשיה כו'), ולא ירדה"],[1900640420,"רק לברר לבושי נוג\"ה שאב ואם ממשיכים, שע\"ז כל יסוד העבודה בעוה\"ז בתורה ומצות באהבה ויראה דהיינו הכל בהתפעלות נפש הטבעית, כנ\"ל בפרטי חילוקי ה' מדריגות נר\"נ ח\"י שבה כו', אבל הנשמה מצד עצמה במקור חוצבה בבחי' אצילות שבבי\"ע אין צריך תיקון. ולהבין זה דלכאורה גם הנשמה תתפעל ברצון ושכל ומדות, ומהו עיקר ההפרש בין התפעלות הנשמה בהשגתה באלהות ובין התפעלות נפש הטבעית בהשגתה באלהות, דודאי בשניהם אינה אלא מצד בחינת אלהות שבהשגה וכן במדות כו'.\n<b>והנה</b> הדוגמא להבין מהות התפעלות הנפש האלהות בהשגתה בהיותה מלובשת בהשגת הנפש הטבעית, הרי יובן קצת ממה שמצינו שהנשמות נהנין מזיו השכינה בג\"ע (גם שהנשמות שם ג\"כ בלבוש דנוג\"ה"],[1900640421,"אבל לאחר הבירור והוא הנקרא לבושי דכיא והוא מנוג\"ה דחשמ\"ל דבריאה או דיצירה כו') וכלולים עשר כחותיה רצון [ותענוג] ושכל ומדות כו' דודאי אור ההשגה שתשיג הנפש האלקית והעונג שמתענגת מזיו האלקי עצמו שבג\"ע היא באה מצד גילוי בחי' אור האלהי שבנשמה זו כמו שהיא בלי העלם וצמצום כלל. ע\"כ בודאי הרי זה בחי' אלהות ממש רק שמאיר ע\"י השגה אלהית, והשגה זו האלהית מושללת מכל בחי' יש בתכלית אלא היא בבחי' האין האלהי. ועכ\"ז תקרא השגה ע\"ד ההשגה שתשיג הנשמה כאן בהיותה מלובשת בהשגה גשמית דנפש הטבעית באלהות, וגם העונג עונג אלהי מושלל מכל בחי' יש אלא עונג רוחני אלהי ממש. וא\"כ גם בחי' התפעלות בהשגה אלהית הזאת יקרא התפעלות אלהי' בבחי' אלהות ממש וכן התפעלות העונג התפעלות בעונג האלהי הוא (וכידוע הדמיון בזה בהפרש שבין עונג שבגשם"],[1900640422,"כממון ומאכל, לעונג שבכבוד שהוא רוחני יותר אשר ע\"כ יפקיר אדם כל תענוגיו הגשמיי' לגביה. ועד\"ז גם עונג שבכבוד, גשמי יחשב לעונג האלהי שבהשגה אלהי' בנשמה שבגוף. ועד\"ז גם עונג זה, גשמי יחשב לגבי עונג הנשמה בג\"ע, וכך הוא הדמיון בהשגת אלהות כו'), ועד\"ז יש עשר כחות"],[1900640423,"בנשמה שנהנית מזיו אלהי בג\"ע רצון אלהי ושכל אלהי ומדות אלהי כו' הכל בבחי' האין דאלהות ומפני שנמצא[ו] מאין האלהי כניצוץ מן השלהבת והוא חלק אלוה ממש ע\"כ נהנית מזיו כו' (וכמ\"ש [במ\"א] ביה אחידא כו' בבחי' יחידה שבה כו'). וע\"ד דוגמא זו יובן גם בירידת הנשמה האלהית דבריאה או"],[1900640424,"רוח דיצירה כו' בלבוש דנפש הטבעית בגוף גשמי שעדיין לא נפסק ממנה כח ומקור חוצבה הנק' צלם וכן מזלא כידוע בענין אך בצלם כו'. ומי שיש לו רוח דיצירה מאיר בבחי' רוח זה שבגוף משרשו בבחי' רוח דיצירה כמו שהיא בג\"ע דיצירה כו' וכה\"ג בנשמה דבריאה או נפש דעשיה. ולפי\"ז הרי מובן עכ\"פ שיש בנפש האלהית המלובש בנפש הטבעית ג\"כ מעין ואותה דוגמא בהתפעלות אלהי' ברצון ושכל ומדות שבה שהוא ג\"כ בחי' אלהות ממש, מאחר שנקרא חלק אלוה כו' גם שירדה מטה מטה ביותר. והענין הוא שאין האור האלהי שבה מוסתר ונעלם כ\"כ כמו שמוסתר ונעלם בנפש דנוגה, כי בחי' נוג\"ה בעצם היא בחי' לבוש נפרד כמו בחי' הארת אור המאיר דרך המסך וכה\"ג שגם שהוא [מאיר] אור גם כן אבל אינו אור העצמי כ\"א אור נקנה מאחר שקיבל מאור העצם על ידי המסך. וכך הוא למעלה בחי' לבוש החשמ\"ל דנוג\"ה"],[1900640425,"כידוע, משא\"כ הנשמ' האלהית בשרשה מקבל' מאור האלהי העצמי בלי העלם ולבוש (ומה שיש לכל נשמה לבוש מנוג\"ה בג\"ע היינו רק בכדי שלא תתבטל במציאות כו'). וגם בהיותה מתלבש' בלבוש דנפש הטבעית אין לה הסתר והעלם מחמת זה כלל, ולזאת אין בה שינוי באופן מהות התפעלות כחות שלה שכולם הם התפעלות אלהי' ממש שאין להתפעלו' כחות נה\"ט ערך לזה כלל וכלל כמשי\"ת, מפני שנבדלת בעצם מנה\"ט רק נתפסת בה בדרך תפיסה והלבשה בלבד כידוע."],[1900640426,"<b>ומעתה</b> יש להבין ההפרש שבין התפעלות נפש האלהי' בהשגה זו עצמה שתשיג נפש הטבעית כו'. בהיות מבואר למעלה בהשג' שכל הנה\"ט בענין אלהי ששומע מאיזה אדם עדיין לא נתפעל מאומה בשמיעתו כו' ואח\"כ ע\"י היגיעה מתפעל מהקיצור כו', הרי מאחר ש[כבר] חלף ועבר רגע אחד ושתים שלא נתפעל מגופה של ההשגה עצמה מזה מורה על היות שבחי'"],[1900640427,"אלהות שבהשגה זו מוסתר בה מאד ע\"כ אין לו רק מה ששומע השכל מצד עצמו לבד ואין זה שייך אליו מפני ריחוק אור האלהי שבהשגה זו ממנו עד שע\"י יגיעה דוקא יאיר אפס קצהו והוא הקיצור והתמצית ממנו ש[מ] תפעל בהודאה כנ\"ל (וגם זה בריחוק אור העצם מאחר שבאה ההתפעלות בלשון בכן כנ\"ל). וגם כאשר מתפעל מגופה של ההשגה עצמה במחשב' הנקרא מחשבה טובה כנ\"ל (עד בחי' הכוונה עצמה שנקרא דו\"ר שכליים בנפש הטבעית כנ\"ל שהוא התפעלות מן העצם (ולא בלשון בכן שכבר עברה ההשגה בלא התפעלות כנ\"ל). אלא מיד שישיג השגה מצד עצמה מתפעל ואין ההתפעלות נפרדת כלל מן עצם המושג כו') שזה מורה על היות שאין אלהות מוסתר כ\"כ בהשגה זו. מ\"מ הכל הוא בבחי' אלהות המוסתר בלבוש דנוג\"ה ובפרט בהשגה דבינה שבנפש זו דנוג\"ה כו', אשר אין לזה ערך כלל לבחי' אור האלהי העצמי שמאיר בבינה והשגה דנה\"א המלובש בהשגה זו עצמה שנפש הטבעית משגת שיש בה מעין אותו אור האלהי העצמי שבהשגה דבינה דנפש האלהית כשנהנית מזיו האלהי העצמי שבג\"ע כנ\"ל בלי מסך והעלם כלל."],[1900640428,"<b>ולזאת</b> גם ההתפעלות שבהשגה זו דנפש האלהית תקרא בשם התפעלות אלהו' ממש ולא כמו התפעלות של דבר נפרד זולת אלהות כהתפעלות דנפש הטבעית בהשגתה. וזהו עיקר ההפרש ביניהם באותה השגה עצמה שנה\"ט משגת.\n<b>ותחלה</b> יש להקדים במה שאנו רואים דבר הפלא ופלא בשינוי אופן התפעלות [ב] נפש אלהי' בהשגה דנפש הטבעית בענין אלהי אחת ששומעים ב' בנ\"א, זה יש לו חוש השמיעה בהתפעלות בעצם המושג (בל\"א נק' דער הערט כו') מצד הסבר ההשגה עצמה דהיינו מפני רוב הסבר דברים המוטעמים בטוב טעם ושכל אנושי עד שנתפס ומתקבל היטב ועיקר התפעלותו מן ההסבר לבד. וזה מתפעל מיד מבחי' האלהות שבהשגה זו ובזה יש לו חוש גדול יותר שבו נכלל כל ריבוי ההסבר עד אשר יכוון מעצמו כמעט כל רוב ההסבר כי מתפעל מיד מתמציתו [האלקית] וממילא נעשה אצלו רוב הסבר לאין שיעור לאורך ורוחב ועומק גדול. (ויש בזה מדרגה היותר פחותה והוא"],[1900640429,"שאינו מתפעל רק מבחי' הרוחניות של ההשגה, והוא רק דמיון שוא מכח המדמה שבבינה שבנפשו שלמטה הרבה מן ההשגה שמזה באה סיבת כח הכוזב המדומה מחמת בלבול כלי המוח או מהתגברות רתיחות הדמים עד שמטעה א\"ע ביותר ושם אור לחושך וחושך לאור ומהפך ומבלבל ומערב שקר ואמת יחד. והוא הטעות הנמצא ביותר באנשי שלומינו שמדמים זה להתפעלות אלהי' שבהסבר ההשגה שלמעלה מגוף ההשגה כנ\"ל שרחוק הערך ביניהם מן הקצה אל הקצה כאור וחושך ממש כו' וד\"ל). והאות לזה הוא אשר בכל פרטי"],[1900640430,"ההסבר יבחין בהבחנה יתירה בהתמצית והיותר פנימי בעומק המושג כו' העולה מתוך כל פרטי ההסבר [ב] משל וכה\"ג, שמזה דוקא יבוא לבחי' אורך ורוחב ועומק ולהבין דבר מתוך דבר בהתרחבות עצומה בכפלי כפליים מן דברי ההסבר ששמע או ראה כתוב. משא\"כ מי שאין לו רק מה שנתפס אצלו בהשגה שכליי' במה ששמע וראה לא ישאר אצלו רק דברים כהוויתן, וגם הן כגולמי חומר בלא צורה והולך ומתקצר ורחוקה ממנו זמן מה עד שיתקצר לגמרי ולא ישאר רק בחי' הכלל בלא תמצית אדרבה בבחי' החיצונית בלבד"],[1900640431,"כו'. וגם אם יזכור הכלל ע\"י חזרתו ורגילתו בה כל הימים עכ\"ז אין בזה חיות אור אלהי להאיר בהשגה זו בנפשו ממש רק כמו הזוכר דברים של מילי דעלמא אחר שלא הרגיש בנפשו מהארת בחי' האור האלהי שבהשגה זו (וגם עוד יש בזה טעות באנ\"ש שיש שמתפעלים מיד בבחי' התמצית שבהשגת ההסבר ונדמה להם שהוא מבחי' אלהות שבהשגה, ע\"כ לא יוכל לסבול ההסבר [כלל] ואינו חפץ בו כלל. ובזה יפלו רבים בטעות המדומה שבאמת אין זה מהשגת האלהי' כלל אלא מצד בחי' טבעיית שמוטבע בנפשות ישראל האלהית שיתפעלו מאלהות בלי טעם ודעת כלל והוא בחי' קטנות דנפש המדריגה האחרונה שבנר\"ן ח\"י דנה\"א שיתבאר (ובל\"א פרומקייט טבעיית). אבל חוש הרגשת אלהות שבהשגה הנ\"ל הוא חוש החסידות של אותה ההשגה שהוא בחי'"],[1900640432,"ההיולי שבה (בל\"א אשענצייע) כמו המשקה שעושים מהתפשטות חלקים רבים (אשענצייע) למזוג בה רוב משקים כידוע ונקרא חומר הפשוט וגם חומר ההיולי כידוע וד\"ל):\n<b>ומעתה</b> יובן מעין דוגמת ריחוק ערך התפעלות ההסבר לגבי התפעלות אלהות שבהסבר הנ\"ל, יותר הוא ריחוק הערך כל עיקר התפעלות אלהות שבהשגה שבנפש הטבעית לגבי התפעלות אלהות שבהשגה שבנה\"א. אך שהתפעלות השגה דנפש הטבעית כמו לבוש בלבד להתפעלות השגה דנה\"א המסתירה ומעלימה, וכן הרצון והתענוג דנפש הטבעית לבוש לרצון ותענוג דנפש האלהית (והדמיון לזה ההפרש שבין העונג והשגה הגשמיי' לגבי"],[1900640433,"עונג והשגה רוחני שבג\"ע כנ\"ל). ונמצא הגם שבודאי מצד עצם הערך הרי גם בחי' היותר אחרונה שבנפש האלהית שהוא כמו בחי' הקטנות ביותר והתפעלות העצמיות בנה\"א בבחי' עשיה למשוך אחרי אלהות בלי טעם כמו ביציאת מצרים דכתיב לכתך אחרי במדבר כו' כתינוק שהולך אחר אביו כו'. אך זהו מצד בחי' עצמיות [נש\"י] כידוע גדולה הרבה גם מהיותר עליון שבנפש הטבעית שהוא הרצון הפשוט שלמעלה מן הטעם הנקרא כוונה כנ\"ל. ומ\"מ מלובשים יו\"ד כחות דנפש האלהית ביו\"ד כחות דנפש הטבעית תענוג בתענוג רצון ברצון שכל בשכל מדות במדות כו' כידוע. ולפי\"ז הרי בהשגה זו עצמה שבנפש הטבעית שהיא בינה [ש] בה מלובש בינה שבנפש האלהית, וא\"כ גם"],[1900640434,"בהתפעלות אלהות שבבינה והשגה דנפש הטבעית מלובש בה התפעלות אלהות שבבינה והשגה דנפש האלהית עד שרשה בהשגה ובינה שבה בהיותה נהנית מזיו בג\"ע, כנ\"ל בענין אך בצלם יתהלך איש דקאי על הנשמה שמלובשת בגוף כידוע. וההפרש ביניהם מבואר למעלה שהוא כמו ההפרש בין אור העצם לאור המסך וכמו התפעלות בחי' ההיולי המסתתר ונעלם בהתפעלות ההסבר כנ\"ל וד\"ל.\n<b>אך</b> עדיין יש להבין מהו מהות ההתפעלות אלהו' בהשגת הנשמה המובדל בערך מהתפעלות ההשגה דנפש הטבעית כו' וכנ\"ל. ותחלה יש להקדים"],[1900640435,"בכלל כל עיקר מהות ההתפעלות דנשמה אחר שהיא חלק אלוה ממש, הרי בהכרח ממש שהתפעלותה נבדל לגמרי ממהות התפעלות נפש הטבעית דהיינו רק בדבר הזה שהתפעלותה הוא בחי' התפעלות עצמית אלהות ולא התפעלות נבדלת כמו כל עצמותי כו', מפני שאלהות אצלה בבחי' עצמית וטבעית כי משם לוקח עיקר מהותה (בל\"א געטליכע התפעלות ניט מענשליכע התפעלות דהיינו דיא נשמה ווערט מתפעל ניט דער גוף גם הנק' דער הערט פי' דיא נשמה דער הערט ובכלל נקרא נשמה דער הערינעש וכה\"ג), וכמו התפעלות המלאכים הנקראים בני [ה] אלהים שבודאי התפעלותם רק התפעלות אלהי בלבד (געטליכע"],[1900640436,"התפעלות), וכמו שהנפש הטבעית תתפעל מענינים גופנים בבחי' עצמית וטבעית כי משם לוקחה כך ממש התפעלות נפש האלהית מעניני אלהו' בכל פרטיהם בבחי' עצמית וטבעית. וההכרח לומר כך שהרי ודאי לא יחייב השכל כלל שיהיה התפעלות דנפש האלהית מעניני תאוות גופנים. כמו ממאכלים וכה\"ג להיות מושללת לגמרי מתאוות גשמיות (וכמו כן רחוק מנפש הטבעית הגופנית להתפעל מעניני אלהות רק ע\"י יגיעה רבה. מ\"מ תתפעל כנ\"ל מצד שיש לבחי' נוגה גם כן שרש יניקה מכח אלהי שמהוה את הכל רק שבא שם בבחי' הסתר ביותר כנ\"ל). א\"כ וודאי שכל מהות התפעלות הנפש האלהית"],[1900640437,"מושלל מכל הגשמת אופן התפעלות דנפש הטבעית רק שמתלבשת ונתפסת בה בדרך לבוש בלבד כנ\"ל. ומה שאנו רואים מהות התפעלות בנפש האלהית בשעה שתתפעל נפש הטבעית בעניני האלהות אם במחשבה והודאה והסכם או אהבה ויראה וכוונה ורצון ותענוג כנ\"ל. הנה זהו עיקר כלל ההפרש דבנפש הטבעית הוא הכל בבחי' התפעלות נבדלת מעצם אלהות, והתפעלות נפש האלהית הוא התפעלות עצמיות מצד עצם אלהות שמושרש ומוטבע בה כמו"],[1900640438,"טבעיות ממש, ולהיותה כלולה גם כן מנר\"ן ח\"י ותתלבש בנר\"ן ח\"י שבנה\"ט דהיינו בכלל הוא ברצון ושכל ומדות וג' לבושי' דמחשבה דבור ומעשה כו'. ע\"כ ודאי שגם שהוא בחי' התפעלות אלהי העצמי עם כל זה יש בה חלוקי מדריגות קטנות וגדלות, ע\"ד שאנו רואים התחלקות המדריגות בנפש הטבעית כשתחפוץ בקרבת אלהים כנ\"ל. ואמנם דרך כלל כל בחי' התפעלות אלהי' שמצד בחי' הנשמה האלהי' נקרא עובדי ה' בנשמתם ולא עובדי ה' בגופם"],[1900640439,"שעכ\"ז נאמר ואתם הדבקים [בב' חיים] כו' דבקים ממילא בבחי' עצמיות וטבעיות וכמ\"ש למעלה בחלוקה הכללית בין התפעלות אלהי להתפעלו' חיי בשר כו'. וגם בנפש דעשיה יש גם בחי' יחידה דנפש האלהית שבו שהוא בחי' התקשרות עצמיות ע\"ד שאמר רשב\"י בחד קטירא אתקטרנא כו' והוא מדריגה היותר נעלה רק שיש בה חילוקי מדריגות הרבה שמתלבשת לפי אופן לבוש דנפש הטבעית כו':"],[1900640440,"<b>ד</b> והנה מבואר למעלה בנפש הטבעית ה' מדריגות כללים מלבד אשר אין בזה מבחי' אלהות כלל שהוא מי שאינו חפץ רק להתפעל בלתי גילוי כוונה לה' רק בהעלם כו'. והנה בדוגמא זו יש גם כן בנפש האלהית כשהיא בתכלית הקטנות שבה בבחי' [ה] העלם ביותר. ותחלה יש לבאר מהו בחי' הקטנות דנפש, בהיות שזה כלל גדול דכל מעשה הטוב במ\"ע וסור מרע בשס\"ה ל\"ת דכל אחד מישראל מגדול ועד קטן, הגם שבודאי תלוי בבחירה לבחור בטוב ולמאוס ברע בכל אחד מישראל לפי ערך מעלתו ומדרגתו באהבה ויראה בתמידות עבודתו (הנקרא פרומקייט או להיפוך קלות ופריקות עול כו'), הנה זהו בחלק וסוג העבודה במצות אהבה ויראה ביגיעה רבה ובעול העבודה בתורה ומצות כו'. אבל יש כמו טבע ממש בכל אחד מישראל גם בסור מרע"],[1900640441,"ועשה טוב שלו בפועל ממש דוקא מצד שרש נשמתו האלהית שהוא בבחי' עצמית וטבעית ולא מצד בחירתו ועבודתו כלל, עד שבזה ישתוו העובד והירא עם הקל ופורק עול כמו שלא לחלל שבת ושלא לעבוד ע\"ג וכל עבירות החמורות בעריות וש\"ד וכה\"ג. וכן כמה מצות עשה כמצה בפסח וכסוכה ותפלין וציצית וכה\"ג שכמו טבעית גם אצל עם הארץ ופחות הערך בלא טעם ודעת ולא מצד מצות אנשים מלומדה כלל, כ\"א רק מצד בחי' יהודית העצמית דוקא (בל\"א זיין עצמית יהודישקייט כו'), וכמו הנשים וע\"ה שיזהרו בנפשם בתכלית הזהירות מכל אשר אסור וטמא גם באיסורים קלים מדבריהם. והגם שיש כמה וכמה שמקילים בעצמם בבחי' קלות ממש לעבור על דבר האסור ולא לחוס למצו' מעשי' כל כך. הנה זה בא מצד נפש הטבעית בבחי' הרע שבה שגובר על טבעית הנפש האלהית בזה, אבל טבעי' ועצמיות דנפש האלהית היפוך זה ממש כי מעצמה וטבעה תחפוץ מאד בטוב האלהות במצות עשה ולמאוס ברע. וכאשר הענין רק בחלק המעשה לבד הוא בבחי' המדריגה התחתונה שבה בחי' נפש רק בחי' מעשה (וכמו בחי' ענין ההסכם דנפש הטבעית שבאה מן המחשבה הקרה הנ\"ל רק שהוא דרך נבדל ולא בבחי'"],[1900640442,"עצמית וטבעיות כמו בנה\"א כו'), ולולי בחי' עצמית וטבעית דכל ניצוץ מישראל בסור מרע ועשה טוב הנה מצד עבודתם ויראתם הנק' (פרומקייט כו') כבר הי' כלה כו', רק שע\"י העבודה והיראה שבכ\"א לפום שיעוריה דיליה מתחזק כח העצמי הזה דנה\"א בכל פרטי דקדוקים בסור מרע ועשה טוב ושיהיה דבר חזק ומתקיים בלי ישתנה להקל ולעבור או להטעות ולהתיר לעצמו כו'. ובזה יש הפרש גדול בין כ\"א לחבירו עד שיש צדיק גמור ורשע גמור בענין המעשה (וברשע גמור נסתלק גם כל כח האחרון במעשה בנפשו האלהית מפני תוקף הרע הגמור דנפשו הטבעית וכמ\"ש נר רשעים ידעך לגמרי עד גם בחי' המעשה כו'. אך עכ\"ז גם פושעי ישראל מלאים מצות כרימון. וע\"כ כל ישראל יש להם חלק לעוה\"ב וד\"ל).\n<b>והנה</b> בודאי שבחי' המעשה והעסק בסור מרע ועשה טוב מצד עצמיות דנפש האלהית באה ע\"י המחשבה בתחלה, והוא הרצון במח' לאלהות לעשות רצונו במעשה עכ\"פ ולא לעבור על רצונו בפו\"מ כו', ומח' זו היא בלי פנימיות אור וחיות כלל רק בקרירות ע\"ד הנ\"ל בנפש הטבעית במחשבה קרה"],[1900640443,"בהתבוננות האלהות [ש] יתגדל ותרומם מרחוק אצלו ואינו שייך אליו כלל, רק שחפץ בו ביותר מפני שנתאמת ונתקבל אצלו שהוא אמת לאמיתו ע\"כ רוצה שיקבע בנפשו כו' ונולד מזה בחי' ההסכם במעשה עכ\"פ כו'. כך הוא סיבת תולדות הסכם המעשה דסור מרע ועשה טוב בנפש האלהית מצד העצמית מן ההחלט במחשבה שהוא בחי' האמונה, הגם שהוא בבחי' ריחוק גדול, שהרי אין הענין הזה מה שהוחלט שצריך לקיים רצון ה' בבחי' פנימית חיות מקרוב כלל, כי בחי' אלהות שבזה הוא בא בבחי' ההסתר מאד, כמו ששם שמים שגור בפי הכל נשים וע\"ה ומזכירים שם ה' בכל רגע ורגע, שהשי\"ת מבורך והוא המושיע ועוזר (בל\"א גילובט כו' כידוע). [ו] בלא פנימית [כלל] שהרי יכול לעשות דבר מה המנגד באותו שעה ממש כמו גנבא אפום מחתרת' רחמנא קריא שיעזור [לו] כו', ואם מאמין שה' עוזר למה יגנ[ו] ב לעבור על רצונו. אך ב' דברים"],[1900640444,"מפורדים הם אצלו, שזהו וודאי אמונה קבועה בנפש האלקי' שבו בבחי' טבעיי' ועצמיי' שה' הוא העוזר לכל כי הוא ברא [את] הכל והוא אחדות פשוט כו'. והגניבה באה מצד תאוות נפש הטבעי' כו'. ולזה וודאי יוכל להיות שמבקש באמת עזר ה' עליו על הצלחת הגניבה כו'. ומזה ראיה עכ\"פ שהאמונה אעפ\"י שהיא בהסתר אלקו' מאד אבל היא טבעי' כידוע מלשון אומן כו'. והוא ירושה מהאבות כמו טבע בבנים כו'. והוא בחי' הסכם טבעי ועצמי דנפש האלקי' שמזה נולדה המעשה הפרטי' דסור מרע ועשה טוב מפני שמאמין באחד מאד, וכמו טבע אצלו שלא לעבור הרצון כו' (וראי' מקידוש השם שמאיר כח אמונה זו בבחי' הפנימי' עד שימסור נפשו בפ\"מ). והגם שיוכל להיות תערובות טוב ורע במעשה הטוב כו'. כמו צדקה להתייהר בלבד או לגרמי'. הרי אמרו האומר סלע זו לצדקה בשביל שיחיה בני הרי זה צדיק גמור, כי מצד נפש האלקי'"],[1900640445,"חפץ בצדקה בבחי' טבעי' ומה שאומר רק בשביל שיחיה בני זהו מנפש הטבעי' המלביש ומסתיר כו'. וכן להתייהר וכה\"ג (משא\"כ עובדי כוכבים דלגרמייהו [ב] לבד עבדין מצד שרש נפשם מבחי' גקה\"ט מלבד חסידי אומות הקדמונים וכה\"ג). והנה למטה מבחי' המעשה דסור מרע וע\"ט העצמיי' דנפש האלקי' שמאיר בזה בחי' אלקות בגילוי באמונה פשוטה עכ\"פ בהחלט המחשבה ורצון כנ\"ל. הנה הוא כדוגמא שמצינו בערב רב שלא הי' כוונתם רצויה בעצמי' מצד נפשם רק ממה שראו הנסים כו'. ע\"כ מיד בראותם שמובדלים מישראל עשו העגל כו'. וכך יש הרבה גם בישראל שעיקר המעשה רק לעצמם בלבד לקנות שם בלבד וכמ\"ש בר\"מ על פסוק אנשי שם, אך שמטעים את עצמם ביותר"],[1900640446,"להיות צדיקים גמורים בעיניהם והעיקר אצלם רק לומר למען שמי דוקא יכבד ה' כו'. והם הנק' אחיכם שונאיכם מנדיכם כו' כידוע. ויש כיתות שנקר' צבועי' [ו] חנפים [ו] שקרנים כו' שאין בזה שום כוונה רצוייה מעצמיות דנפש האלקי' בגילוי, רק עכ\"ז בבחי' העלם גדול יש בזה מבחי' אלקות דנפש האלקי'. וראי' כאשר יבוא עליו בטושים גדולים ויסורים וצער דסליק נהורא דנשמתא ויבכה כו' (וכמו שיתבאר בסמוך בענין בעלי תשובה ביוהכ\"פ כו'). משא\"כ בעובדי כוכבים. וראי' מביטוש דמשה שאמר להם פנו וסעו לכם כו' שחזרו בהם ואמרו חטאנו. וכן ממה שגט המעושה בישראל כשר וכן כופין וממשכנין על הצדקה וכה\"ג וכמ\"ש במ\"א (וכמו המצות סוכה דלעתיד שיבחנו בנקודה זו ישראל"],[1900640447,"ועובדי כוכבים, והוא דעובדי כוכבים יבעטו וישראל לא יבעטו, כי הנה\"א עיקר רצונו רק לעשות רצון האלקי מצד עצמו כנ\"ל וכשמצטער פטור ולא מבעט כלל שהרי אין זה רצון האלקי, משא\"כ עובדי כוכבים שאין כוונתם רק רצון עצמם כו'. למען שמי דוקא יכבד [ה'] כו' וד\"ל). ופרטי חילוקים יש בזה הרבה מאד אך לא ניתן לכתוב כי ממילא מובן כו'. וכל אחד יודע היטיב בנפשו ואין צריך לדבר מזה כלל."],[1900640448,"<b>והמדריגה</b> הב' שלמעלה מזו הוא יותר בבחי' הפנימי' שלמעלה מבחי' מעשה הטוב במצות בפו\"מ בלבד בחי' נפש הנ\"ל. והוא בבחי' הרוח שלמעלה מבחי' נפש ע\"ד הנ\"ל בבחי' מדריגה הב' דנפש הטבעי' בבחי' התפעלות מחשבה טובה (בל\"א דער הערט טיף גא[נץ גוט כו' כנ\"ל). והענין יובן ע\"ד דוגמא ממה שמצינו ביציאת מצרים שיצאו כל העם טף ונשים ע\"י אמונה פשוטה שבנפשם והאמינו בה' גם שלא שמעו אל משה בתחילה מקוצר רוח"],[1900640449,"כו', אבל לאחר השב רוחם האמינו ברוח אלקי העצמי שנטוע ומושרש בנפשם מצד נשמתם האלקי כנ\"ל באור חיות פנימי כו'. והלכו כולם ממצרים שזהו בהתפעלות גמורה במחשבה ורצון פנימי (בל\"א דער הערט שטא[רק זייער כו') שנק' הזזה ממקומו, כנ\"ל בבחי' מחשבה טובה כמו עד\"מ בענין הנוגע לעצמו ביותר כו' כנ\"ל. והנולד מזה גם שאינו נוגע אלא למעשה בלבד דהיינו לצאת ממצרים לבד אבל היא באה בבחי' התפעלות אור וחיות פנימי' הרבה יותר ממחשבה הקרה הנ\"ל הנעלמה במעשה דסור מרע ועשה טוב בלי חיות כלל כו' וד\"ל. וע\"ז נאמר זכרתי לך חסד נעוריך כלומר אהבת נעוריך לכתך אחרי ממצרים גם שהי' בבחי' הקטנות לצאת רק מאפילה דטומאת מצרים לאור גדול כו'. אבל לכתך אחרי אעפ\"י שהוא בלי טעם ודעת הרי זה בא בבחי' עצמיי' וטבעיי', כמו התינוק שהולך אחר אביו בהתפעלות חזקה לא יועילו כל להפרידו מאביו כו'. וזהו רק מצד רוח האלקי' שבכנסת ישראל שנמשכים והולכים אחר מקור חוצבם האלקי כמו טבעיות ממש כו'."],[1900640450,"<b>ועוד</b> יובן כדוגמא זו באופן אחר והוא מקיבוץ הניצוצות דקדושה שנפלו ע\"י שבירת הכלים בין עובדי כוכבים כמה מאות ואלפים שנה שחוזרים וניעורים ממש, והן הגרים שמתגיירים שהוא כמו דבר הפלא ופלא [אשר איש משוקע בכל מיני רע בתולדתו ותולדות אבותיו עד כמה דורות] , יהי' לו תשוקה נפלאה להתגייר ואין זה רק רוח אלקי נוססה בו בלתי יודע בעצמו מה זה, וכמו הגרים בזמן אברהם כענר אשכול וממרא [וכה\"ג בכל דור] כו'. והגם כי קשה כספחת כי עלייתם מנוג\"ה [דש\"ר הההוא ו] תערובות קשה יש בהם וע\"כ קשים כספחת, לבד ניצוצות גבוהים מאד כמו גרי הצדק כשמעיה ואבטליון ואונקלוס וכה\"ג וד\"ל).\n<b>ועוד</b> יובן מבע\"ת שאנו רואים בחוש שגם איש המשוקע בכל תאות רעות ובעבירות חמורים מאד כו'. מ\"מ יתעורר רוחו וישוב בתשובה, ויש מי"],[1900640451,"שישובו מעומק הלב עד כלות נפשם בבכי', כמו ראב\"ד שיצאה נשמתו בבכיה ונתקנא בו רבי ואמר יש קונה עולמו בשעה אחת. וגם אותם שאינם שבים מעומקא דליבא כ\"כ עד שתצא נשמתם אבל בוכים במר נפשם מאד, ובפרט בעשי\"ת וביותר ביוכ\"פ כידוע שגם היותר קלים וגם האפיקורסים שעוברים על כל התורה מתעוררים ביוהכ\"פ, עד שבוכים ממש, וידוע שאין זה מצד הבחירה כלל כי הרי כל השנה הולך אחר שרירות לבו רק רע כל היום כו'. רק ביוהכ\"פ מפני שה' נגלה על כל בחי' ניצוץ האלקי למבקשו כמ\"ש דרשו ה' בהמצאו כו'. וממילא נמשך הניצוץ ומתעורר בבכיה מעצמו בבחי' טבעי' ועצמי' שזהו רק מצד בחי' עצמיות וטבעיות דנפש האלקי' רק שהי' תחלה בהעלם מפני הסתר עוונותיהם ובתשובה מתגלים ע\"כ בוכה (הגם שמבואר במ\"א שזהו מבחי' יחידה שבנפשו, אבל הוא רוח המעורר גם לענין המעשה להיות סור מרע ועשה טוב ואומר תעבנו בווידוי כו') ומתחרט ושב מן המעשה הרע אל הטוב. והרי זה כמבואר למעלה ש[מן] המחשבה [ה] טובה מצטרפת למעשה באהבה ויראה שבמוח בבחי' התפעלות עכ\"פ (והרשעים והאפיקורסים והקלים שאינם שבים כלל היינו רק מפני שבחי' יחידה שבהם האיר רק לפי שעה שהוא זמן הגילוי ביוהכ\"פ ואינו מאיר בכחות שלה כלל כמ\"ש נר רשעים ידעך לגמרי. ואשר איננו קל ורשע כ\"כ יותר יאיר בנפשו האלקי לענין המעשה וגם בפנימיות יותר. וכך הוא מדי יום ביומו שבת קול מכרזת ואומרת"],[1900640452,"שובו בנים שובבים כו' כידוע). והיותר נעלה במדרגה זהו המאיר בבחי' המעשה [בבחי'] המנגד, הוא ממה שאנו רואים בענין מס\"נ על קדה\"ש בפ\"מ דוקא שע\"ז הי' ר\"ע מצטער ואמר מתי יבוא לידי ואקיימנו בפו\"מ דוקא, שזהו האור הפנימי ביותר בנה\"א מבחי' פנימי' כ\"ח מ\"ה שבנפשו שהוא בחי' יחידה המאיר למטה בבחי' המעשה שלא להמיר דתו בפו\"מ דוקא, דהגם שאם לא יתבעהו להמיר בפ\"מ יוכל לעבור על כמה עבירות בפ\"מ כו'. אך ליפרד לגמרי מאחד בזה מעורר כח היותר פנימי ועצמי לבוא לידי מס\"נ בפ\"מ, ודבר זה לא יוכל להיות מצד היגיעה ועבודה כלל כ\"א רק מצד בחי' עצמות ההתקשרות דנה\"א במקור חוצבה שלא תוכל להפרד בשום אופן, ובשעת קדה\"ש מאיר בגילוי מן הההעלם, ואם הי' מאיר כח זה בגילוי תמיד לא הי' חוטא לעולם אפי' על איסור קל כו'. כמ\"ש למען תהי' יראת ה' על פניכם לבלתי תחטאו וכה\"ג כידוע. והרי מכל אלה יש להבין כללות ענין ההתפעלות עצמיות דנה\"א בבחי' הפנימי' שהוא בחי' רוח שלמעלה מבחי' נפש שאינו רק במעשה עצמו כנ\"ל וד\"ל.\n<b>והמדריגה</b> הג' שלמעלה מזו היא בחי' התפעלות עצמי שבבחי' נשמה כמ\"ש כל הנשמה תהלל כו'. וכן אם ישים אליו לבו רוחו ונשמתו אליו יאסוף וכה\"ג. והענין הוא ע\"ד הנ\"ל בהתפעלות נפרדת דנפש"],[1900640453,"הטבעי' בהתפעלות דמח' טובה כשבאה בלב בשר בהתפעלות מורגשת ברשפי אש התשוקה כו'. ובנה\"א היינו בבחי' התפעלות עצמיות בלב בשר מן ההשגה האלקית ממש שבנה\"א המלובשת בהשגה דנה\"ט, וע\"ד מ\"ש לבי ובשרי ירננו אל אל חי שלב הבשר ממש ירנן אל אל כו'. שזהו כמו בחי' התפעלות הניגון שמאיר בלב בשר שהוא בא מעצמו וממילא בלתי בחירה ויגיעה כלל וכלל רק מצד עצמיות התפעלות דנה\"א, כנ\"ל בענין המאמר דר\"מ הי' מנגן בצלותא בכל מיני ניגון כו', שהוא בחי' התפעלות הנשמה ע\"י השיר או קול תנועה עצמיות מכמה אופנים שונים מורכבים מחדוה ומרירות ומיצוע וכה\"ג לפי אופן הכוונה האלקי' שבהשגתה האלקו' דוקא, ואמנם באה במורגש בלב שהלב מרגיש ביותר, שהרי הניגון והתנועה יוצא מהבל הלב ממש בהתפעלות אבל בלתי ידוע אליו כלל וכלל. וכמ\"ש לבי ובשרי [ממש] ירננו [אבל] אל אל חי דוקא שהוא בבחי' התפעלות עצמיות באלקות והיינו עיקר ההפרש בין התפעלות מורגשת שבלב מצד נה\"ט שהוא יודע בעצמו ומרגיש שמתפעל. וע\"כ וודאי בהכרח שבחי' אלקות רחוק ומוסתר בזה, כי יש מי שמתפעל ונתפס ליש גדול בעצמו כו'. עד שיעשה עיקר מן ההתפעלות ולא מן האלהות כלל, כנ\"ל בהתפעלות לב בשר אשר לא לה' כלל רק להנאת עצמו התגלות"],[1900640454,"לבו כו'. משא\"כ התפעלות העצמיות דנה\"א הגם שבאה במורגש בלב אין זה התפעלות מורגשת כלל, מאחר שאינה מורגשת בעצמו [כלל] עד שאינו יודע ממנה באותה שעה כלל ואינה מרגישה בעצמה, עד\"מ בן המתפעל בלבו בתשוקה אל אביו מצד היותו התפעלות עצמיות וטבעי' לא ירגיש בעצמו בהתפעלות ובלתי נודעת לו במורגש כ\"כ, וכן התפעלות האב אל הבן. וכך הוא כל התפעלות עצמיות כמו התפעלות עצמיות דנה\"ט בתאווה גשמיות אשר נראה בחוש שבלתי נודע לו כלל למתפעל בלבו לאיזה דבר הנחמד בבחי' עצמיות וטבעיות אע\"פ שההתפעלות מורגשת מאד בלבו לא נקרא מורגש בעצמו אדרבה העדר הרגשה בעצמי' בהתפעלות זו. וזהו הכלל גדול דכל שההתפעלות העצמות עמוקה יותר כמו באהבה ורצון ותענוג היותר פנימי', יותר לא ירגיש בה כמשי\"ת בעזר\"ה במדרגה הד'. אך מדרגה זו ישנה ברוב אנשים שעדיין לא הוטמאה הנפש האלקי' ולא נתלכלכה בטומאת הגוף בתאוה זרה דלב בשר החיצוני' כ\"כ. [ו] כמ\"ש נקי כפים ובר לבב כו'. ולהיות שהכוונה שבמוח מאיר בלב. ע\"ז אמר בכל לבי דוקא דרשתיך. וכן כלה שארי ולבבי כו' צור לבבי כו'. וכה\"ג לבי ובשרי ירננו כו'. והוא התחלת אמיתת הענין דגילוי אלקו' בלב כל או\"א מישראל וע\"ז נאמר על כי אין אלוה בקרבי כו' בקרבי"],[1900640455,"דוקא. וע\"ז אמר ג\"כ כל הנשמה תהלל כו'. בחי' נשמה בחי' מוחין דחו\"ב שמתפעל בלב, כנ\"ל במדריגה הג' דנה\"ט בהתפעלות נפרדת שבה מתלבש התפעלות עצמי' זו וד\"ל.\n<b>והמדרגה</b> הד' הוא בחי' נקודת הכוונה שבמוח שלמעלה מהתפעלות המורגש בלב עדיין. ע\"ד הנ\"ל במדרגה הד' בנה\"ט כאשר נטרד כל עומק מוחו ולבו בעצם הפלגת הדבר הטוב כו'. שכל נפשו נמשך אחריו עד שלא בא עדיין להתפעל[ות] בלב כו'. ונק' דו\"ר שכליים שהשכל עצמו הוא ההתפעלות ולא [ה] התפעלות מקיצור השכל כו' (הנק' בכן כו'). והנה הגם שהתפעלות עצמיות שבלב הנ\"ל. מאחר שבלתי מודעת לו כ\"כ כנ\"ל. הרי בהכרח שבאה פתאום בלתי הכנה מתחלה לעשות אותה וכמו דוגמת התפעלות"],[1900640456,"פתאומית דשמחה שמספק ביד כו'. כך הנה הרינה הזאת בלב בשר בא ממילא ומעצמו כדרך כל התפעלות עצמי', וזהו עיקר הסימן אלי'. וגם עוד פנימי' יש בה כשנמשכת דוקא אחר הכוונה התמצית שבמוח שהוא בחי' עומק תמצית המכוון בהשגה (שזהו בחי' יסוד אבא ביסוד ז\"א שנק' כוונה שבלב שבאה מכח כוונה דאור אבא שבמוחו. ונק' אהבה בתענוגים, והוא בעונג הנעלם שבעומק המושג כו'), עכ\"ז אין לה ערך לגבי בחינת התפעלות עצמי' שבכוונה הפנימי' שבמוח, כאשר גוף נקודת המושכל הוא עצמו המתפעל שנקרא כוונה (וכמ\"ש במ\"א שזהו קולו של משה שלמעלה משיר הלוים שהוא לפי ההשגה באריכות שבא הניגון מסודר לפי המשך ההסבר של ההתבוננות באופנים שונים מסודרים בתנועות הניגון, משא\"כ קול תנועות הניגון שנעשה מגוף נקודת המושכל הפנימי ההיולי הוא רק המורה על תמצית המושכל והעונג הנעלם בו"],[1900640457,"שאז אינו בא בסדר והמשך רק תנועה אחת פתאומית ביותר ונק' קלא דלא משתמע כלומר בלתי מורגשת כלל ואינו נפסק לעולם. וע\"ז אמר למען יזמרך כבוד ולא ידום כו'. וזהו דר\"מ הי' מנגן כו'). וכוונה זו רק בעצם אור האלקי מצד עצמה ולא מצד השגתו והבנתו בו והוא למעלה מבחי' אורך ורוחב ההשגה דבינה רק אח\"כ מתפשט בהשגה, וכללותו נקרא בזוה\"ק שיר כפול דחו\"ב בבחי' עליות הנשמה שבמוח בהתענגה על ה' בעומק המושכל בכל פרטי השתלשלות כו'. וכוונה זו יש בה עונג עצמי ופשוט מעצמיות ופשטו'"],[1900640458,"הנה\"א, והוא שרש ענין תפלה דשבת דכתיב אז תתענג על הוי' כו' שלמעלה מתפלה דחול, שתפלה העיקרית היא לברר ולזכך לנה\"ט הנקרא עבודה ובירור, ואמנם אין זה רק בהגיע הארת הנה\"א בלב הגשמי ששם עיקר רוח [ו] נפש הטבעי' בלב בשר בחלל השמאלי כו'. אבל בעודנה במוח ששם משכן הנשמה עצמה שם הוא בחי' עבודת הנשמה עצמה בעלותה למקור חוצבה בשיר ועונג פשוט ועצמי שבחו\"ב שבה הנקרא שיר כפול. ועד\"ז גם בכל יום ויום מימות החול הרי גם בק\"ש מאיר הארת השבת כידוע. ולזאת מובדל התפעלות דאהבה"],[1900640459,"בק\"ש מהתפעלות דאהבה שבפסוקי דזמרה, דבפסד\"ז הרי הוא בא במורגש מן המוח אל הלב כהתפעלות המלאכים בקול רעש וכמ\"ש רוממות אל בגרונם דוקא שהגרון מחבר המוח אל הלב בהתפעלות מורגש כו'. ובק\"ש שאומרים שמע ישראל אל הנשמה שתמסור נפשה באחד עד ואהבת פועל יוצא להביא אהבה גם בנפש הטבעי' כמא' בב' יצריך כו'. אבל הוא בבחי' התפעלות עצמי' בנקודת הכוונה שבמוח והתפעלות הלב באהבה מורגשת נכלל בה ונקרא היכל האהבה, כידוע שהאהבה כמו היכל וכלי בבחי' ביטול לגבי עצמיות ההתפעלות שבנקודת הכוונה שנטרד בה כלו לאורך ורוחב כנ\"ל בנה\"ט כו'. ולהיות שזהו יותר פנימי ועצמי ע\"כ הוא בא בלתי מורגש יותר ובלתי מרגיש בעצמו יותר, כידוע בניסיון לכל מי שטעם טעם ועונג עצמי בעומק ההשגה האלקי' בתפלה, וזהו גילוי אלהות בבחי' פנימי' יותר, ודרך כלל הוא בבחי' חיה כ\"ח מ\"ה דחכמה שבנפש האלהי', ושם מאיר [מ] בחי' מזלא וצלם והוא בחי' מקיף דחי' שבה שורה בחי' נשמה יתירה בשבת שהוא בחי' מקיף דיחידה העליון מכולם שמתפשט עד ז\"א ואינו מאיר בגילוי כלל רק מרחוק בהעלם שזהו פנימי' מדריגה הה' דשיר פשוט שיתבאר בעזר\"ה וד\"ל.\n<b>והמדריגה</b> הה' הוא בחי' יחידה העצמית ממש ונקרא שיר פשוט דהיינו שבחי' [ה] עצמי' ממש עולה בשיר ע\"כ נקרא שיר פשוט ועצמי"],[1900640460,"בלתי מוכפל, כי שיר כפול הנ\"ל הוא עונג [ה] עצמי הבא דרך פרט כמו בפרט עומק ההשגה האלקי', כמו הנשמות נהנין מזיו בחי' זיווא עילאה דע\"י דמל' דאצי' בכל אחד לפי עומק נקודת השגתו כך נהנה בעונג האלקי העצמי ואין כל הנשמות שוות בזה כו'. אך שיר פשוט בא מבחי' עונג ההיולי המקור לכל מיני עונג בפרט שמזה בא תכלית ההתכללות כל העצמיות דוקא. וכמ\"ש רשב\"י בחד קטירא שהוא קשר אחד עצמי בעצמיות דבחי' יחידה בי' אחידא בי' להיטא ממש כמ\"ש בה' תתהלל נפשי וכן הללי נפשי את ה' ממש כו'. והוא הנקרא ג\"כ רצון אחד פשוט ועצמי הבלתי מורגש ובא לכלל התחלקות רצונות הפכיים כמו חו\"ג שבטעם כמוס לרצון שנקרא אהבה בתענוגים ב' מיני עונג [עונג] של חדוה והיפוכה וכה\"ג, אלא רק רצון אחד שכל הרצונות נכללים וטפלים בו. ע\"ד דוגמא מאדם הטרוד בהצלת [חיי] נפשו ממות ממש שכל"],[1900640461,"נקודת הרצון שבעצמיות נפשו, מתעורר בו, כי נוגע לעצמותו ממש ואז כל רצונותיו המתפשט[ים] בדבר נפרד מן העצמיות שלו ממש כמו אהבת הפרנסה ואהבת אשתו ובניו כלא חשיבי ממש, כי נכללים בעצמי' הרצון הזה שנוגע לכל עצמותו כו'. והוא הנקרא התפעלות כל העצמיות (בל\"א ער איז צו רירט גא]ר פון זיין נקודת העצמיות&amp;\n189;) דהיינו שנמשך כולו ולא נשאר בו כלום [ו] אז הוא בלתי מרגיש א\"ע כלל וכלל (בל\"א טיפע צו טרא]גינקייט פון גא]ר דעם נפש ביז ער קען אויס גין פון דיא כלי המוח והלב כו'). והוא אהבת בכל מאדך בלי גבול שלמעלה מנר\"ן, וגם למעלה מבחי' כח מ\"ה שבנפש שבא בהתלבשות בכוונה שבמוח, אבל זהו למעלה מן הטעם ודעת לגמרי מכל וכל, כי אין טעם כלל לרצון ועונג פשוט ההיולי הזה אפי' טעם כמוס שבמקור השכל ההיולי כו'. ולהיות שאין דבר זה מצוי כלל ברוב האנשים ע\"כ האריכות בו אך למותר. אבל מ\"מ יש ממנו בהעלם בכל ניצוץ מישראל בשבת בנשמתן שנקרא נשמה יתירה והוא בחי' מקיף דיחידה כנ\"ל. וגם בשעת קידוש השם מאיר כח זה בבחי' הסתלקות כו'. ובצדיקים גמורים ובעלי תשובה האמיתי' מאיר בגילוי,"],[1900640462,"בצדיקים מחמת גודל עוצם עריבות מתיקת העונג העצמי בבחי' יחידה. כמ\"ש ואתם הדבקים ממש. וכמא' בי' אחידא כו'. ובבעלי תשובה האמיתי' בא בבחי' הסתלקות וכלות הנפש מצד המנגד, כמו ראב\"ד שיצאה נשמתו ממש בבכיה וכה\"ג. ובכל אחד מישראל מאיר בהעלם, והוא מה שאנו רואים שכל אחד מישראל תדבק נפשו האלהי ותמשך מאליו וממילא בשמעו ענין אלהי וגם שאינו מבין כלל וכלל רק מצד בחי' יחידה שבו שמאיר בהעלם עכ\"פ והוא למעלה מן השכל ע\"כ גם ע\"ה ות\"ח שוין ממש בזה כידוע וד\"ל. (וכמו במתן תורה שפרחה נשמתן כולן בשוה. וכן מ\"ש כל אשר דיבר ה' נעשה כולן אמרו בשוה מטעם זה וד\"ל):"],[1900640463,"<b>ה</b> ואחר כל זה הדברים והאמת האלה בכללות כל החילוקים הנמצאות ומובנות לכל מי שהתחיל לטעום בטעם דא\"ח כל איש לפי שכלו ודעתו ולבו ולפי רגילתו בעבודה שבלב מנעוריו יכיר וימצא את מקומו ומדריגתו ויבחון בנפשו כל חלקי הטעיות שנפלו בהם, ואם יש את נפשו שלם ולבו נכון לה' באמת יפקח היטיב בעין שכלו תמיד על מהותו שלא יטעה א\"ע, כי לפי הנראה עיקר הקלקול בגירעון אור תורה ועבודה שבלב גם למבקשים וחפצים בקרבת אלהים הוא רק הטעות שמטעה כל אחד את עצמו מפני רפיון היגיעה לדרוש את ה' בכל לב לתכליתו, רק מרחוק ירצה להתקרב ולבו בל עמו. וע\"ז אמר לקנות חכמה ולב אין שהעיקר הוא נתינת הלב היטיב לתכלית אמיתית הענין של דא\"ח, שלזאת ישא את נפשו ולבו בכל ימי חיי הבלו, ולמה לריק ולשקר יעשה בנפשו לרחק ולא לקרב ח\"ו. (בל\"א מיא זא]ל זיך ניט נא[רין כו') כידוע ומפורסם לכל שעיקר הענין בתערובות טוב ורע הוא המטעה את עצמו כו'. אך הנה כ\"ז למבקשים ודורשים וחפצים בקרבת אלהים באמת אבל"],[1900640464,"אין זה נמצא ברוב אנ\"ש. וההכרח לבוא בתוכחת מגולה מאהבה מוסתרת וגלוי' לגלות ולהודיע לכל אחד את נגעו ומכאובו ואם במסתרים תבכה נפשו וצר לו באמת, אבל הגיאות והתקשרות באהבת עצמו תכסה על כל עד שאינו רואה חוב לעצמו כלל וכלל וכל דרכי איש זך וישר בעיניו כו' ולזה אין תקוה כו'. והנה באמת מלבד הטעות להטעות א\"ע מצד העדר הידיעה לבד אין סיבה זו עיקר האמת, אלא רק מסיבת רפיון לב בעסק ורצון בכלל לכל ד\"ח. כי הנה הרוב הטרודים במו\"מ בתכלית בכל נר\"ן ח\"י שבנה\"ט אם ישוב רוחם אליהם בעת מן העתים לפרקים או בשעת התפלה לא יוכל לשאת בנפשו עול היגיעה במוחו להעמיק דעתו בממלא וסובב גם דרך כלל וכ\"ש דרך פרט, עד שיהי' לו גם בחי' מחשבה טובה הנ\"ל רק בחי' מחשבה קרה מרחוק מאד שאין נוגע אליו הענין כלל וכלל כמו שידוע היטיב למודים על האמת ואינם רוצים להטעות עצמם ח\"ו. והנולד מזה שהוא ההסכם הוא בקרירות עצומה ולא מספיק רק לפי שעה דהיינו רק ללמוד כמעט רגע אחד אחר התפלה בתנ\"ך ובשעה ושתים"],[1900640465,"חולף ועובר גם ההסכם הזה והי' כלא הי' ויעסוק בבחי' יחידה שבנפש הטבעית במשא ומתן ושאר צרכי גופו כאלו הוא ענין הנוגע בבבת עינו ממש כמו בחי' כל עצמותי תאמרנה הנ\"ל בעבודת ה' כו', [ו] גם בשמעו או ראותו דא\"ח יראה וישמע מרחוק מאד ואם יתקבל בכי טוב יודה רק בהודאה כו' והתעיף עיניך בו ואיננו כו' וישכח לגמרי מכל וכל והיו כלא היו וכו' ואין זו אוזן שומעת כלל וכלל, אבל הרי נשאר בו באמת בחי' עצם טבע [יהדותו] בחי' נפש דנפש האלהי' בסור מרע ועשה טוב ומלובש בהסכם בבחי' רשימו עכ\"פ כו'. אך גם בזה יש רפיון גדול [ונמהרים] להקל ע\"ע מכמה סיבות המונעים מחומריות הגוף וטרדות המשא ומתן והמשכת עצמיות הנפש בעוה\"ז עד שהוא בבחי' דומם ונקרא טמטום המוח שאינו שומע גם מרחוק, ואין לו בזה שום חוש הבנה והתקבלות במוח כלל כידוע למודים על האמת עד שאין צריך לשאלה לאיזה תועלת כו' כי לא שמע כלל."],[1900640466,"<b>אך</b> מכל מקום גם בשני כיתות הללו נמצא דבר טוב ומשובח מצד אחר לגמרי [ו] הוא בראות[ו] שאינו שומע ומקבל להתפעל גם במוחו בהודאה ומכ\"ש בלבו, הנה יבוא לבחי' תשובה פשוטה לבחי' מרירות ושפלות בעצמי', על חומר גופו הגס וכה\"ג ויזכור חטאת נעוריו וכה\"ג ויצעק בצעקה פתאומית בלא התבוננות אלהות כלל, רק דרך כלל על דרך שאמר צעק לבם אל הוי' דוקא בתשובה מעומק הלב במרירות עצומה או בהכנעה גדולה. הנה זהו היוצא מכל החלוקות המבוארים למעלה, כי ה' יראה ללב השב בצעקה אם הוא באמת גם שהוא בלא התבוננות כלל להיותה באה מצד התעוררות הנפש האלהית כמו שכתוב למעלה שיוכל להיות בבעל תשובה מבחי' יחידה שבנפש האלהית עד שתצא נשמתו ועכ\"פ מבחי' רוח ונשמה שמעוררו בתשובה והוא הצעקה בתפלה כמו שנאמר ויצעקו אל הוי' בצר להם כו' וכן צעק לבם כו', והתפעלות זו מכלל התפעלות אלהות דנפש האלהית היא, רק שבאה מצד המנגד כו', ובהיות שהנפש האלהית בקירוב ודביקות תתפעל בצעקה פתאומית בלב בשר כמו לבי ובשרי ירננו אל אל חי כנ\"ל, ונמצא אחת היא רק שזה מצד המנגד כו' וד\"ל. ובזה יש רבים הטועים שמשפילים הצעקה כזאת, ובאמת טח עיניהם מראות שזה ממש המאמר הנזכר בליקוטי אמרים בכי' תקיע' בליבאי מסטרא"],[1900640467,"דא וחדוה מסטרא דא כו' שהחדוה הוא עונג האלהי שבמוח הבא במורגש אל הלב כו', והוא חלק הקירוב של נפש האלהית, ובאותה מדריגה עצמה תתמרמר הנפש האלהית ותבכה מצד ריחוקה מאחד כו'. והיינו בכי' מסטרא דא כו' ובכל רגע ורגע צריך להיות חדוה מסטרא דא כו'. ואמנם בב' כתות הנ\"ל אינו נמצא רק חלק הב' בענין בכיה מסטרא דא והוא התפעלות נה\"א מבחי' הפנימי' שבו אשר ה' דורש ומבקש זה מאד מאד כמ\"ש קרוב ה' לנשברי לב כו'. שהוא לב נשבר מפחיתותו וריחוקו מאלהים כידוע [לכל ה(א)האריכות] וד\"ל.\n<b>והכת</b> הג' מאותן האנשים שיש להם התפעלות במח' (הנקרא דער הערט טיף כו') כנ\"ל, והנולד מזה לחפוץ בתשוקה במוחו בהתגלות אלהות בוע\"ט כו'. גם שבלתי מורגש עדיין בהתפעלות הלב כמ\"ש למעלה. הנה בזה יש תוכחה רבה ועצומה מאשר נראה בעליל ברוב אנשים גם ברגילים ובקיאים וחפצים באמת [ב] דא\"ח כי יש להם חוש השמיעה הזאת הנקרא אוזן שומעת, ואיך נהפכה לס\"ג ממש מן הקצה כו'. כי בשמעו ונקלט היטיב פרטי עניני האלהי במחשבתו יתפעל ויאמר האח חמותי ראיתי אור כו' אבל בזה יוגמר"],[1900640468,"הענין גם כי חוזר עליו פעמים ושלש כו', הרי זה רק בבחי' בריקה וסקירה על המוח ולב וישאר הכל גנוז וטמון בהצנע מאד בהעלם [ב] נפשו עד כלותו ממש, כי מיד חוזר וניער בעסקי גופו ואינו משתמש בשקידה תמידית לקבוע בנפשו בכל מיני אורך ורוחב ועומק להחיות נפשו האומללה כי זה חיי נפשו ממש והוא מסלקו מנגדו אחר שכבר גמר וסבר, וגם נתפעל כבר יצא כל חובתו ונק' חסיד כו'. וממילא רשאי לו לעסוק בכי טוב בכל הצטרכותיו ומצורף לזה קדושתו בעיניו עד שמערב הכל ביחד להטעות א\"ע ביותר. ובהגיע עת התפלה ישאר הכל אצלו בבחי' העלם ומקיף, וגם כאשר מייגע א\"ע ויבוא לכלל התפעלות במחשבה אינו יודע מה טיבו ומה יולד טוב מזה כידוע נאמנה לכל הנבוכים בזה. וכל זה רק מחולי הנפש הטבעי' שמורגלת מאד בהגשמת גופני לכל הצורך, ואיך תוכל שאת לקבל הרגשה אמיתית בדא\"ח בשמיעה הנ\"ל. וגם מצד הקלות ומיעוט העסק והיגיעה רק דרך מעבר בעלמא לצאת י\"ח וכמו השומע שיר וניגון כו'. כי יש בחוש השמיעה הנ\"ל מדריגות רבות, יש שומע לעומק יותר ויש שומע ומתפעל אבל בקלות ובמהירות (בל\"א פון אויבין זייער) דהיינו שגם ההתפעלות במוח הוא מבחוץ ולא מבפנים כלל, כידוע כל זה למודים על האמת ואינם רוצים להטעות את עצמם ע\"כ יפול הנופל מזה לגמרי במיעוט זמן ובמיעוט סיבות המונעים ומנגדים, כמו הטרדות למו\"מ והנופל בתאוות עצמו להתגשם ביותר וכה\"ג עד שנפסק אצלו חוש השמיעה הזאת לגמרי מכל וכל כידוע ליודעים וד\"ל."],[1900640469,"<b>ואמנם</b> הנה אחר העיון היטיב הדק בסיבות המחלה הזאת המתפשטת ברוב אנשים, הנה הוא בא ממקום אחר והוא אשר אין להם לב נשבר (המכונה בל\"א צו ברא]כינקייט) האמיתית בעצם טבעם, כי מנעוריו לא קיבל תחלה ד\"ח ע\"פ סיבת התעוררות תשובה אמיתית מקרב ולב עמוק רק בדרך מעבר לפי שעה וכבר חלף ועבר גם בחי' הרשימו מזה לגמרי עד שהוא איש שלם לגמרי בעצמו (בל\"א גא[נץ זייער בייא זיך בלי שום צו ברא]כינקייט כו'), ע\"כ קבלת ד\"ח על השל[י] מות הזאת לא יוקלט בפנימית ועומק לבו ומוחו כלל רק דרך מעבר בעלמא כאדם ששומע ורואה ענין שחוץ ממנו אע\"פ שנהנה ומתפעל לפי שעה מיד יתעלם והי' כלא כו'. וכל שיש לו לב נשבר בעצם טבעו יותר מצד הנה\"א שהיא נקר' מרת נפש במאסר חומר הגוף, הגם שנראה כמו טבע אנושי' מצד התלבשותה בנה\"ט הנקרא מ\"ש טבעיות אין זה באמת מצד הנה\"ט כלל, כי אין בטבעה רק להיות במ\"ש מחסרון והעדר גופני ולא מחסרון אור אלהי כו' (ולזה אמרו גם במקבלי רזי תורה שאין זה אלא במי שלבו דואג תמיד בקרבו שהוא ענין המ\"ש הטבעיות והעצמיי' מעצמות דנה\"א, ובלעדה לא יאיר אור רזי תורה בנפשו ולא יתקיים כלל וכלל רק אדרבה יבוא לידי חושך והוא רק הגסות והפריקות עול כידוע בניסיון גמור). ודבר זה שמעתי בפירוש מפי אאמו\"ר ז\"ל ששמע בזה\"ל מהרב המגיד ז\"ל שלא יוכל"],[1900640470,"אדם לבוא לקבלת אמיתית רזין דאורייתא והשגת עמוקות האמיתית באא\"ס עד שיוקבע בנפשו ממש, בלתי אם יש בו המ\"ש הטבעי' והעצמי' שמושרשת בו מנעוריו דוקא, ודוקא בבחי' ההיולי שבה הכללי' (בל\"א אשענצייע) אם הוא לעומק האמיתית דוקא (דהיינו צו בראכינקייט האמיתית בטבע עד שמואס ממש בחייו בתמידית בכל שעה ושעה), אז ישכון בו ממקור כל החיים מקורא דכולא להחיות רוח נדכאים וכמ\"ש את מי אשכון את דכא ושפל רוח כו' [ב] כל אשר הוא עושה, אם בהתבוננות ברזין דאורייתא מוסרין בנפשו בגילוי אמיתית אם לבו דואג בקרבו (ולהיפוך אין מוסרין בנפשו כלל גם שיודע ומשיג הפשט וכו'). וגם בכל פרט ופרט מדרכי העבודה האלהי' ה' ירצה בו, ואז נהפך האנחה שלו והמ\"ש הטבעיות הנ\"ל לשמחה ועונג רק מצד אלהו' ששורה על נפשו ממש. אבל בלתי זה ובפרט להיפוך מי שטבעו ממרה הלבנה בהוללות טבעיות, הגם שהוא כלי מוכן לקבל כל רז כו' לא יתקיימו בנפשו ויהי' בחושך הילוכו כל הימים להטעות א\"ע בתכלית כי אין ה' אתו בשום אופן כו'. ע\"כ תוכן הדברים.\n<b>ומזה</b> י\"ל גם בבינונים לפ\"ע שזהו עיקר סיבת המחלה הנ\"ל בנפשם אם יפקחו נא בעין חמלה על נפשם ולא יאבדו א\"ע מצד אהבת עצמ' שלא לראות"],[1900640471,"חוב כו' וד\"ל. ומכש\"כ בדורותינו החדשים שמקרוב באו שלא התחילו מנעוריהם בבחי' לב נשבר הנ\"ל כלל, רק מיד נתפתחו עיניהם בחכמה אלהי להשיג ולשמוע הכל בב\"א כאחד הגדולים כידוע והם שלימים בכל מהותם ילדים אשר אין בהם כל מום ולא ירגישו בעצמם שום דבר רע ומקילים לנפשם ביותר, כי שמח תשמחם מאשר משיגים ויודעים הרבה והעיקר מאהבת עצמם, וגם המעט שיש בטבעם בחי' לב נשבר כמו זר נחשב אצלם להעמיק בזה מקטנות המדריגות שקורין לזה (פרומקייט טבעי') כי כך קבלו מהדרשנים הגדולים עליהם האומרים רזי לי כו'. והוא טעות גמור מן הקצה כו'. וחי נפשי אשר בטעות זה נפלו רבים מהגדולים שבחדשים לולי קצת מהישנים שיודעים האמת וגם המה עזבו דרך זה מצד נפילתם בעוה\"ז כו'. והגם שישמעו בדרושי' [ב] זה דברים רבים באור תורה אמיתית של אאמו\"ר ז\"ל נ\"ע יאמרו שזהו רק לקטני הערך כמו בעלי תשובה וכה\"ג. וחי נפשי שהגדולים צריכים לזה הרבה יותר מהקטנים, וזהו עיקר סיבת נפילתם מעט מעט בלי הרגש בנפשם כלל וכלל כידוע בבירור וד\"ל. ועוד זאת הסיבה העיקרית למחלה הקשה הנ\"ל, מיעוט היגיעה והעסק בד\"ח ולהביאם בנפשו במעשה דוקא, כי גם שיש הרבה מאד שמתעסקים ומייגעים א\"ע בהבנת וחזרת הענין הרבה פעמים עד שיהי' בקי בהם ובשמותיהם שגורים בפיה' להשיב לשואלים כו'. לא לזה יקרא עסק ועבודה האלהי' כלל רק בחי' לימוד בעלמא מן השפה לחוץ ולבו [ונפשו] בל עמו כלל, מפני שלא עסק בהם בעבודה האלהית לקבוע הדברים בנפשו"],[1900640472,"בהתקשרות עוז ותעצומות להיות חי בהם ממש (הנקרא לעבידיקייט בנפש ולהיפוך נק' טוטקייט) ודא\"ח הם חיים ממש לדורשיהם. וכמ\"ש ואתם הדבקים כו' חיים כולכם כו', ולהיפוך כמת יחשב, וגם במילי דעלמא יש הפרש גדול בין מי שכל הדברים בענין המה יוצאים חיים (דער ענין איז לעבידיק עס לעבט זייער כו'), בין כשהענין הוא בלתי שום חיות כלל (דער ענין איז טויט זייער כו'). ודבר זה ידוע שבחי' חיות הנפש בדא\"ח אינו אלא ע\"י העסק בעבודה האלהי' וביגיעה גדולה בתפלה ובלימוד בעיון בתורות ובזוהר הק' וספרי קבלה להעמיק ולקשר נפשו ולבו בהם באמת (בל\"א איין שטא[רקין קלע( באמת פון נפש כו') עד שתחי' נפשו בחיות חדש ממש, וזה צריך להיות בתמידות ושקידה רבה עד שיקבע בנפשו ותחי' חיי עולם בל תמוט ולא תחשך אורה, ואז כאשר ירצה לבקש דבר ה' יוקבע בנפשו לעולם ויבקע כשחר אורו להשביע נפשו בשביעה שיש בה ממש להוסיף אור אלהי בתוס' מרובה ובשרש ויסוד המתקיים לעולם והי' כעץ שתול [על] כו'. ולא יזיזוהו כל רוחות רעות שבעולם כו' וד\"ל.\n<b>והכת</b> הד' מאותן האנשים אנשי לבב שמחוש השמיעה הנ\"ל הנקרא אוזן שומעת נכנס ללב ומתפעל ולא האוזן לבד שומעת כו'. ויש בזה מינים שונים מאד יש אשר מיד שמתפעל בלבו תקצר חוש השמיעה ששומע בהרחבה (או בהתבוננותו או בראותו בכתבים וספרים הקדושים) ולא יעמיק"],[1900640473,"לתכלית אורך ורוחב ועומק המכוון, ויעמיד הכל על אחת בקיצור הנאות לו שאותו דבר נתקבל אצלו וזהו החולי רעה שיאבד את הכל כי לא נשאר אצלו מאומה, ולא די שמאבד את העיקר אלא שיצא שכרו בהפסדו שיפסיד גם מה שנשאר אצלו כי לא יתקיים כלל להיות שאין לו לב חיות כלל בלא מוחין כידוע. ונשאר בלב בלא מוח, ע\"כ וודאי כל אשר חפץ באמת בקרבת אלהים בנפשו יראה שלא יעשה יש ודבר מהתפעלות לבו ולא ירגישנו כלל, אדרבה התפעלות זו תוסיף תת כחה בכח בינתו להרחיב ולהעמיק לתכליתו יותר ולא יטעה הטועה לאסור ולפסול התפעלות זו ח\"ו רק שיראה שלא תקצר לו העומק והאריכות, והוא הנק' שהלב נמשך אחר המוח (בל\"א דיא הא[רץ איז אין מוח) כאדם שמתפעל בלבו במו\"מ טוב וכה\"ג שלבו עולה במוחו ואינו מרגיש אותה"],[1900640474,"אדרבה תוסיף תת כחה להרחיב ולהעמיק כו' (ועדיין אין זה בחי' הכוונה שבמוח עצמו הנ\"ל רק שהתפעלות הלב נכלל ומתאחד במוח), אך הנה זה דוקא באותן שהתפעלות לבם נמהר מאד אחר ההתבוננות או השמיעה דבר שהוטב בעיניו כו' (עד שיוכל להיות שההתפעלות תגבר על ההתבוננות ולא ידע ממה נתפעל כידוע), ובהם בנקל יותר להביא התפעלות הלב אל המוח לגמרי כנ\"ל, אבל יש במין זה להיפוך, דגם בשעה שמתפעלים במוח מתעכב אצלם זמן מה ולא יומשך ההתפעלות בלב עדיין עד אשר יביאו ללב בהדרגה וישוב נכון כידוע, ובהם נעשה קצת הבדלה בין המוח והלב שאינם שוכנים כאחד, כי בהגיע ההתפעלות ללב אז תנוח ההתפעלות המוח כמעט לגמרי ואין זה רק התפעלות הלב רק שנולד מצד השכל (והוא הנקרא בכן כו'),"],[1900640475,"ובהתפעלות המוח אין שם התפעלות הלב ע\"כ ימצא ג\"כ שיהי התפעלות הלב יותר מבמוח, או להיפוך שהתפעלות המוח יותר מהתפעלות הלב (אך זהו המעלה שידע ממה נתפעל רק שהוא הקיצור כו', משא\"כ בנמהרי לב הנ\"ל שיוכל להיות שבלב מתפעל ברשפי אש יותר עד שלא ידע ממה כו'), ויהי' איך שיהי' הכל הוא בחי' גילוי התפעלות ביותר שהוא התפעלות הלב רק שבזה אינו מרגיש בעצמו כ\"כ מפני שעולה למוח ובזה מורגש בעצמו יותר. אמנם הנה לא ראי זה כו'. דהנה באמת העצה לקיים נצחי' של דו\"ר טבעיי' הנולד מצד השכל בדרך בכן הנ\"ל. היינו דוקא כאשר הוא בא בבחי' פנימי' ועומק הלב והוא בתשוקה ואהבה אמיתית מקרב הלב בהמשכה רבה, או התפעלות תשוקה [ברשפי אש] יתירה, וכן להיפוך בעוצם מרירות הלב על היפוך המנגדו, משא\"כ כאשר ההתפעלות הוא דרך מעבר בעלמא (בל\"א זייער פון אויבין זייער גינא[רט כו') אז כמעט רגע חולפת ועוברת ההתפעלות לגמרי, וזהו בדוק ומנוסה כידוע למבקשי עצות ע\"ז כו' וד\"ל."],[1900640476,"<b>ועוד</b> זאת הסיבה לחולי זו הנקרא חלישת הלב בלתי תוקף כלל שבמעט רגע יפול כו'. הוא העדר המעשה המסתעפת מדו\"ר טבעיי' הללו, להיות ידוע שאין לאור אחיזה ותפיסה רק בכלי, וכל מה שיתרחב הכלי יתרחב האור כמשל הניצוץ בנר הדולק כו', והיינו המעשה שהוא בחי' כלים מכלים שונים להלביש האור דדו\"ר הנ\"ל, והוא מה שמקבל קבלת מלכות שמים באהבה להיות דבוק בתורתו ובמצותיו, ולהיפוך להתרחק מרע כו' ומקיים מיד בפו\"מ שזהו כידוע בענין כי טוב לגנוז האור בכלי שאז מתקיים דוקא, ובלא כלי אין קיום לאור כלל. והתוכחה בזה ידוע לכל כי רבים חללים הפילה חולי רעה זו כו'. אשר מיד אחר העבודה ועסק בד\"ח בהתפעלות עושי' היפוכו אשר לא ניתן לכתוב ויצא שכרם בהפסדם על להבא ג\"כ, כי כלי ריקן אינו מחזיק מאומה, ואם יאיר אור התפעלות בלב הרי זה כשלהבת הפורח באויר שאין לו קיום או, כאש התבערה מן שריפת הקש שנראה תחלתה ברעש גדול ומיד תכבה כו'. משא\"כ התפעלות שבעומק הלב שזהו כדמיון בישול בשר הגשמי שבגמר"],[1900640477,"בישולו נעשה רך וראוי לאכול (בל\"א עס איז גוט איבער גיקא]כט כו') ונקרא לב בשר, משא\"כ כשלא נתבשל כ\"צ הוא קשה כו' (בל\"א רויע פלייש כו') וזהו שבדק ר\"ע לתלמידיו כידוע וד\"ל. ועוד סיבה לזה יותר מצוייה והוא מלבד ריחוק התפעלות הלב מן המוח, הנה הוא בא ממיעוט לב נשבר הנ\"ל (הנק' צו ברא]כינקייט כו') שכאשר טבעו בלב נשבר אזי חיות נפשו ולבבו מההתבוננות חזקה ביותר, וזהו בדוק ומנוסה שכל מי שלבבו נשבר ובשפלות הלב ביותר (הנק' נישטיקייט בייא זיך בתכלית כו') יותר תתקיים התפעלות לבו באמיתת יותר להיות לאור וחיות לכל אשר ירצה בעבודת ה' כל היום בתו\"מ וכה\"ג. וגם במילי דחסידות עצמו כל השפל ונבזה בעיניו ויותר בלבו דוקא אזי לבו כלי מוכן להכיל יותר התפעלות אלהי שמן ההתבוננות, וע\"ז נאמר שפת אמת תכון לעד ולהיפוך עד ארגיעה לשון שקר כו'. והוא בחי' מ\"ש ההיולי הנ\"ל (הנק' אשענצייע טובה) שמתפשטת בכל פרטי הדברים כנ\"ל אם בהתבוננות ואם במדות שבלב ואם ברצון ותענוג כו' הכל הולך אחר המעמיד והמקיים והוא בחי' לב נשבר האמיתי הנ\"ל כידוע ברור כשמש גם בגדולי עולם. וזהו פסק המשנה דאין מתפללין אלא מתוך כובד ראש והכנעת הלב דוקא כי רם ה' ושפל יראה דוקא וד\"ל. (ועוד יש סיבה להסתלקות האור בלב במעט רגע מסיבת עיפוש האויר מתאוות לבו הרע כו'. כמשל האור באויר עכור שאינו טוב, ולהיפוך בחי' אויר זך [שבלב] שבא מטהרת הלב ופרישותו מגשמיות עוה\"ז גם מהוללות וכה\"ג ויסודו היינו ענין לב נשבר הנ\"ל וד\"ל):"],[1900640478,"<b>ו</b> והכת הד' מאותן האנשים שנכנסו לעומק יותר בד\"ח בשקידה רבה והוקבע מאד בנפשם בבחי' כוונה פנימית שבמוח, הנ\"ל במדריגה הד' שבנה\"ט ומלובש בה התפעלות עצמי' דנפש האלהית שנקרא שיר כפול כנ\"ל, והוא בחי' עונג עצמי להתענג על ה' בעומק הכוונה באלהו' שנטרד כל נפשו בזה עד שלא יבוא לכלל התפעלות בלב כנ\"ל באריכות (בל\"א זייער איין טיפען קוועל אין מוח מיט איין שטא[רקע צו טרא]גינקייט בעומק עצם ההשגה מצד דער זא[ך א[ליין דוקא ביז ער איז פון זיך גא]ר א[רויס באמת בהעדר הרגשה הנקרא ביטול עצמי' דבחי' מ\"ה דחכמה כידוע). הנה בזה רבו מינים שונים מאד במדריגות חלוקות זו למעלה מזו לא ראי זה כו'. דהנה כת החדשים אשר אין להם טבעית מ\"ש (בל\"א טיפע צו ברא]כינקייט הנ\"ל) ע\"ז אמרו אם אין יראה אין חכמה, שבוודאי מטעים א\"ע בזה ביותר שנדמה להם מיד בהתפעלות העומק שבמוח מצד אלהות עצמו בבחי' עונג עצמי (הנק' קוועל גדול) ואין זה רק מבחוץ ולא מבפנים כלל וכלל (בל\"א עס איז זייער פון אויבין און גינא[רט זייער). וסימן לזה שמיד שחלף זה ועבר, בא לכלל הרגשת העצמיות מזה עצמו דוקא"],[1900640479,"(הנקרא ער איז מלא וגדוש פול זייער פון דעם גופא) וידמה לזולתו כבהמה ממש ויבוא לכלל התנשאות עצמו בבחי' הפנימית בבחי' [ה] תמימות בלתי נודע לו באמת, כי שפל בעיניו לכאורה ונבזה ובטל ביטול עצמי כנ\"ל. ולהיפוך הוא שזהו תכלית הגסות האמיתי' (ער הא[לט פון זיך באמת, זיין אורט קען ער ניט צו נישט מא[כין ח\"ו). והמופת לזה כשיבטשוהו בבזיון (הנק' שאר) מתפעל ביותר עד שיחלה כו'. הרי יצא דבר והיפוכו, כי גם באותה השעה מוטעה הי', והי' להיפוך שרצה להגיע למדריגות הביטול כי לא יחסר לו רק זה וכה\"ג. ומזה מסתעפת ריבוי תאוות הרבנות בנערים להשפיע לזולתו [רק] בטעות שמטע' א\"ע שמכוון לטובת זולתו כו'. וחולי זה מצוי ברוב הילדים היינו הענוגים והרכים אשר לא טעמו היטיב מטעם מרירות האמיתי' מ\"ש הטבעיות (הנק' צו ברא]כינקייט) ומפני גדילתם במעט זמן להגיע לתכלית ההתפשטות בחכמת האלהי' כידוע, והרוב הוא מסיבות תערובות הקשה בנה\"ט שהמשיכו לו אביו ואמו בהרגשת עצמיות' שהוא רע שבנוגה כידוע. ע\"כ בכל דבר גם בענין אלהי לא ימלט מזה כו'. וזהו סיבה כלליות (ויוכל להיות שיהי' לו נשמה גבוה מזולתו, וגופו דנה\"ט ממקום נמוך יותר, ע\"כ התפעלות עצמיות דאלהי' יש בו יותר, אבל בלבושים דנוגה דגופו הוא בחי' מורגש יותר, ולהיפוך יש שנשמתו נמוכה ורחוק ערכו"],[1900640480,"בהתפעלות אלהו' מזולתו, אבל גופו דנפש הטבעי' דקה יותר בבחי' ביטול והעדר הרגשת עצמו כ\"כ. והסימן הוא בדבר שבממון וכל בחי' לגרמי' שיוכל להפקיר א\"ע, וכן כל הטוב שעושה בלתי מורגש בעצמו שעושה דבר מה כו'. ומי שנשמתו וגופו ממקום עליון ביותר כל טוב האלהי יצלח בידו כי ה' אתו להיות כלי מוכן לכל כי כל הכלים שלו בבחי' ביטול שזהו העיקר כו').\n<b>והיותר</b> עליונים בסוג זה המה הישנים שקבלו בנפשם כל טעם מר עד הנפש על דא\"ח, וגם בהתפעלותם במוח אינם מכוונים להגיע למדריגה או להנאת עצמן כ\"א קרבת אלהים יחפצון מצד עצמ[ו] , והכוונה לעומק ורוחב הוא לתכלית האמת (בל\"א ניט גינא[רט בתכלית כו') אזי הוא נקרא עונג האלהי שבכוונתם האמיתי' אשר ה' שוכן בזה בכל חד לפי ערך טהרת עומק הכוונה האלהי' (הנקרא איין טיפע צו טרא]גינקייט באמת לאמיתו). וסימנו שאח\"כ יבוא לכלל שפלות אמיתי' (הנקרא נישטיקייט ער איז נישט בעצם ניט גימא[כטע נישטיקייט ע\"פ חשבון פחיתת עצמו כו'). וע\"כ לא יתפעל בשום אופן מן הביטוש (הנקרא שאר) ואינו מרגיש זה כלל כי נבזה בעיניו נמאס באמת מפני שאין לו מצד עצמו כלום, וזהו היפוך ההתנשאות (רק מבזיונות פשוטים מתפעל מפני"],[1900640481,"שיש לו גוף, ואין זה סתירה לענין זה כלל כידוע). וגם בזה מינים רבים שונים חלוקים באופן עומק השפלות, כי יש מטעים את עצמם בזה שנדמה לו שפלות אמיתי' כו', וכל אחד ידע וישגיח על עצמו וימצא א\"ע בטעות אם ירצה לראות על עצמו ולא למחול לעצמו מצד אהבת עצמו כו' (הוא הנק' נא[רין זיך). ועוד מסימנים טובים לאמיתת הביטול והעונג האלהי שבכוונה הנ\"ל (הנק' קוועל גדול) הוא בחי' ההמשכה של הנפש כל היום אחר קרבת אלהי' במעשה דוקא, וימאוס בהבלי עולם לילך פנוי בלב ומוח עד שייצר לו מאד בביטול שיחת הילדים והוללות הנהוג בזמן הזה (הנק' ער קלע(ט זיך זייער און ציט זיך צו אלקות תמיד במחשבה עמוקה מאד, או ללמוד נגלה או נסתר בדיבור וכה\"ג). ועוד סימנים במיעוט תענוגי עוה\"ז בכבוד ולבוש ומאכל טוב וכה\"ג בשאר תאוות גסות מעשה בהמה (בל\"א דיא וועלט איז ניט קיין עיקר לעבין) (ובלשון הזוהר שדי מילי דעלמא בתר כתפוי כו') (בל\"א זיין לעבין איז דער עיקר אין קרבת אלקים באור תורה פנימית וחיצונית כו') וגם בעסקו במו\"מ אינו אץ להעשיר כ\"א רק ההכרח ולא יהי' כל עומק לבבו במס\"נ במו\"מ כי הן ולאו [יכול לבא ל] השתוות אצלו וישליך על ה' יהבו כו' (כמשי\"ת בארוכה בקונטרס מיוחד בענין עסק הפרנסה כו'). ולהיפוך מי שהילוכו מבחוץ בענין כוונה הנ\"ל מיד שיעסוק במו\"מ יבוא להיפוכו לתכלית עומק הרצון בכל נפשו במדריגה כזו ויותר מזה במו\"מ. וכשחוזר וניעור ה\"ז הענין רחוק מאד אצלו וצריך להתייגע עד שיתקרב כו'. והאריכות בזה אך למותר כי מיעוטא דלא שכיחא הוא והמעט אשר היו ראויים לזה נפלו מכמה טעמים וסיבות, אם מצד עומק לבם ביותר"],[1900640482,"בטרדת הפרנסה שהגיע לעומק הנפש ביותר עד דשדי תכלא בכולא עד שכל אוכל תתעב כו'. דהיינו שנעשה בבחי' ריחוק גם בלא אוזן שומעת כו' הנ\"ל, ואם מצד עוצם הגסות והפריקות עול עד שנהפך האור לחושך שהוא מסיבת ההרגשה בעצמו ביותר שבא מסיבת הרבנות בדרשנים המתחכמים כו'. או מצד שתחילתו מעורב ברע הנקרא שקר וגסות עד שכל פנימית התחלתו לא הי' רק להתגדל כו'. וזאת החולי הרעה נמצא מכוסה ונעלם בהעלם אחר העלם, גם במי שמלובש בלבושים יפים בעסק הד\"ח לעיני אדם, אבל ה' יראה ללבב וסופו מוכיח על תחילתו בנפול הנופל שחוזר לאמיתת מהותו, כידוע ברור לכל מעיין ובדוק ומנוסה בכמה אנשים שעלו וירדו תכלית הירידה שאין משיחין על פני השדה בדבר כזה כו' וד\"ל. (וגם יכול להיות מסיבת הנפילות בתאוות גשמיות שמטמטמת לבו ומוחו בתכלית עד שנתגשם ביותר ונעשה בחי' דומם כו'), ועוד מסיבת החוצפה הטבעי' הנק' תקיפא דרא (בל\"א א[שטא[רקייט בייא זיך זייער כו') שזהו היפוך בחי' הביטול ע\"כ לא ניזוז ממקומו כלל בתחילתו (ער איז בתכלית הגא[נצקייט) וכל שלא הי' ב[ו] בחי' הזזה וביטול אמיתי לא יוכל לקרב לאלהי' קירוב אמיתי לעולם כידוע, ע\"כ סופו מוכיח שנשאר ריקן רק בחי' עזות פנים בחוצפא מלכותא בלא תגא עד שיבעט וימאס בכל כו'. וימאס גם באחרים כו' (וז\"ש בזוהר פ' שלח אבן בחן כו' דצדיקי' כד מבטשין להון סליק נהורא כו'. ולהיפוך מחרף ומגדף כו' ע\"ש) וזהו הסימן האמיתי לכל עיקר אמיתת הענין הנ\"ל וד\"ל. ומין זה שכיח טובא [כידוע] וצריכים שמירה מעולה מתחילתם שלא יזיקו אחרים כו'. ושומר נפשו ירחק מהם כו'."],[1900640483,"<b>והכת</b> החמישי מאותן שמאיר בנפשם מבחי' יחידה שהוא בחי' העונג והרצון הפשוט העצמי שלמעלה מן הכוונה והטעם שבמוחו כו' כנ\"ל במדריגה החמישי' דנה\"ט ומלובש בזה התפעלות עצמיות דיחידה שבנה\"א, ע\"ד שאמר רשב\"י בי' אחידא כו', וע\"ז נאמר ואתם הדבקים ממילא כו' כנ\"ל באריכות. הנה הגם שמדריגה זו לא שכיח גם באחד מעיר כו'. רק אפשר מצד הארה דיחידה בהעלם בניצוץ בכ\"א מישראל כנ\"ל, שיוכל לבוא לפרקים גם בגילוי קצת בשעה שמתפעל בעונג הנ\"ל (הנק' קוועל שבמוח) שיבוא לכלל עונג הפשוט העצמי שלמעלה מן הטעם לגמרי, רק שלא יהי' נקבע בנפשו, כ\"א במעט רגע ומיד מסתלק מצד העדר הכלי לזה מפני חומר הגוף כו'. ויש בזה רבים מאד המטעים את עצמן ונדמה להם בקל שמתענגים בעונג זה הפשוט כו' וא\"צ לדבר בהם כלל, כי דמיונות שוא הוא לגמרי הבאה מרתיחות הדמים וקלקול עצמי בכלי המוח הנקרא שקר עצמי (בל\"א איין גינא[רטער מענש בטבע דוקא), שאין לזה תיקון לעולם כידוע. ומסתעף מזה שקר ודמיון שוא כ\"כ עד שנדמה [לו] שנסתלקה נפשו (הנקרא אויס גיין) ולא יוכל לעמוד בגופו כו'. וגם יראה חזיונות מבוהלות ונוראות כו' ובשוטים כאלה א\"צ לדבר. ואמנם דבר השכיח בזה גם במביני מדע שאינם מטעים א\"ע, הוא בא מצד תערובות התפעלות הלב בזה כאשר יתפעל בנקודת לבו שלמעלה מהטעם כו' ויתערב בבחי' עונג דיחידה המאיר במקצת כנ\"ל, הנה אז ידמה לו אמיתית בהתפעלות העונג הזה הפשוט כו'. וסימנו שבא במורגש בלב בשר וידמה לו שזהו מ\"ש כלה שארי"],[1900640484,"ולבבי כו'. אך יש בזה תערובות טעות גדול מאד, [ו] הוא להיות שלב בשר הזה מעורב טו\"ר מבחי' נוגה, ואיך אפשר שיהי' כלי מוכן לעונג האלהי הזה העצמי, אם לא שנזדכך מחומריותו היטיב, וזה אינו בנמצא כלל, א\"כ וודאי אין זה אמת גמור רק מעורב בטעות (הנקרא גינא[רט). אמנם הנה מצד אחר יוכל להיות שיהי' אמת לתכליתו ממש, והוא להיות ידוע שיש התפעלות בלב בשר ג\"כ מצד נקודת הלב שנקרא בחי' בהמה שלמטה מן הדעת ששרשה למעלה מן הדעת כו' וכמ\"ש [ו] אני בהמות הייתי עמך כו'. והגם שמביני מדע מואסים בזה טח עיניהם מראות שיש בזה שורש העונג העצמי הנ\"ל בלי תערובות כלל וכלל, והוא להיות שזהו בא מצד בחי' התמימות האמיתי' שבלב, וכמ\"ש והיה תמים, ותמימות זו היינו בבחי' יחידה דוקא שמאיר בלב בנקודה הפנימי'. ואמיתית הסימן ועיקר התנאי בזה, הוא דוקא כאשר עושה התפעלות לב בשר ג\"כ בבחי' התמימות דוקא בלי הרגש עצמ[ו] בזה כלל וכלל. כמו ע\"ד דוגמא איש המעונה בעינוי קשה שיצעק לבו צעקה פתאומית בלב בשר מנקודת פנימי' נפשו ולבו שהוא עד הנפש ממש כו'. שבוודאי אין בזה שום תערובות כלל רק אמיתת הדבר כמו שהוא בעצם ההיולי ממש כו'. וכן להיפוך בעונג נפלא ביותר כמו שיבשרוהו בהצלת נפשו [מ] סכנת מות ממש וכה\"ג שיחיה חיות לבו הבשרי ממש ממקורו העצמי, וכמו ותחי רוח יעקב מבשורת יוסף האהוב כנפשו וכה\"ג. וכך יוכל להיות בבע\"ת האמיתי שיצעק במר נפשו ביותר מתוך לבו הבשרי עד שנוגע לבחי' יחידה כו'. כמו ראב\"ד שיצאה נשמתו"],[1900640485,"בבכי' ולהפך בהתענג על ה' בעונג נפלא ביותר. הרי חיות עונג בשרי זה מגיע לבחי' עונג העצמי' שביחידה כו', והוא התפעלות לב בשר שלמטה מן הדעת ג\"כ כמ\"ש ואני בהמות כו' כאשר הוא בבחי' התמימות דוקא שאז הוא בלי הרגש עצמו כלל וכלל ואז לא יחשיך לו חומר גופו בזה כידוע ברור בתמימים אמיתי' הנאמנים בלב ונפש עד כלותם ממש מבלי ידעו וירגישו בעצמם שום דבר מה כו'. וזה המין שכיח בפשוטים יותר מבמבינים וחכמים רק שחלוקים במדריגות שונות באמיתת הדבר, ומשכיל עד\"ז ימצא הכל ברור כשמש כו' וד\"ל.\n<b>ואחר</b> כל הדברים והאמת האלה בכל מיני חלוקי המינים הנמצאים באנ\"ש, כ\"א יכיר את מקומו ומדריגתו וישגיח על עצמו ולא יטעה א\"ע לילך בגדולות ממנו. כמ\"ש מי יעלה כו'. ואם לא יעלה מסתמא לא ירד ואיש את רעת רעהו לא יחשבו וגם לא יקנאו במעלתו וטובו כי לכ\"א יש לו מקום מיוחד והקנאה עושה תערובות קשה בכל דרכיו כו' רק כ\"א יעשה כפי מה שהוא בעצם (נא[טירליך ניט נא]ך גימא[כט), וכשיהי' פנאי יש הרבה לדבר בתוכחת מגולה במנהגים רעים וקשים הנמצאים באנ\"ש שנסתעפו מימים רבים מסיבות הטעיות ולכל העם בשגגה ה' יכפר בעד שארית [ה] פליטה הנמצאים לבקש קרבת אלהים כו'. וגם יש הרבה לדבר בעיקר ענין מצות עסק התורה לשמה בכמה אופנים שונים אשר זה נעלם גם מרוב מביני מדע ומכש\"כ מן הנערים"],[1900640486,"וחדשים. ובאיכות ענין המצות בכל פרטיהם ובצדקה ובגמ\"ח הכללי', וגם בענין ההיתר בעומק הלב בפרנסה אשר יכלה בהבל כל ימיו לגמרי מכל וכל, שזהו כל עיקר סיבת הנפילה ברוב אנ\"ש גדולים וקטנים ישנים וחדשים עד אשר יערה עליהם רוח ממרום להשיב רוחם כו' ויקיצו משינתם כו'. וזהו עיקר הגלות שנמשל לשינה. כמ\"ש בשוב ה' כו' היינו כחולמים כו' וד\"ל.\n<b>אך</b> אהוביי אחיי וריעיי כל השלמים אתי עד הנפש כו' המקשיבים ושומעים לדא\"ח באמת ובאמונה ואין בלבבם שרש פורה ראש כו'. לראות בעין רעה ח\"ו, ובפרט מאשר יודעים ומכירים אותי מנעורי יאמינו נא לכל דברי אלה שהמה נאמרים מכל נקודת לבי כמו שהן בהוייתן כלבבי ונפשי בעצם טבעי ומהותי כפי שהורגלתי בהם מנעורי ע\"פ הדרכת אאמו\"ר ז\"ל מדי יום ביומו, ולא יאמר ח\"ו שיש בזה דברים נעלמים עוד שאין מגלין אלא לצנועים כו' או שנכתבו כמה דברים לפנים כו', ליתן מקום לאנשי' הבלתי מורגלים עדיין באמיתת הענין כו', כי כאלה, דיבת האנשים החפצים להתגאות ולקנות שם לעצמן לומר רזי לי כו' שאין כל אדם יודע כו', ותולין הכל בי. ובאמת ובאמונה אני נשבע בחיי נפשי האם יש בכל הדברים שפירשתי שיחתי לפניהם אפי' חצי דיבור [ש] לא יצא מתוך נקודת לבבי, והכל נמצאים הם ומובנים לכל מי שטעם טעם בעסק הד\"ח מנעוריו. ולפי שמאד הורגלתי מנעורי זה יותר מעשרים שנה בהיכל קדשו של אאמו\"ר ז\"ל וידעתי ממנו כל פרטי מכאובי אנ\"ש ובדקתי בעצמי לב כ\"א וטעות כ\"א כפי שכח השגתי מגיע ע\"ז בניתי כל דברי אלה השומע ישמע כו'. ועל תשובתם אם נתקבל כל דברי האמת האלה לטובתם כל הימים לרצון, ע\"י ידידינו המופלג כו' מוכ\"ז אני מצפה, [לו] ויהי' למשיב נפש כו' דברי ידידם דורש אמיתת טובת נפשם מלונ\"ח כל ימי חיי הבלי.\nדובער בהרב אאמו\"ר הגאון האמיתי האלקי נזר ישראל ותפארתו כ\"ש\nמוהר\"ר שניאור זלמן ז\"ל נבג\"מ זיע\"א"],[1900640312,"<b>[זוהר פרשה וישלח דף קע\"ה ב]</b>\nר' יהודה פתח ואמר כי ישרים דרכי ה' וגומר כולהו ישרים וארחוי קשוט כו' וע\"ד צדיקים ילכו בם בגין דאינון ידעין אורחי' דקוב\"ה ומשתדלי באורייתא וכו' דלא סטי לימינא ולשמאל' ופושעים יכשלו בם כו' אינון כשלי בהו באינון אורחי בהאי עלמא ובעלמא דאתי, ת\"ח כל בר נש דאשתדל באורייתא כד נפיק מהאי עלמא נשמתי' סלקא באינון ארחי' ושבילין דאורייתא כו' ואינון דידעי ארחוי דאורייתא בהאי עלמא יהכון בהו בההוא עלמא כד יפקון מהאי עלמא כו', וצ\"ל מאי סמיכות הפרשה היא זו דמאי שלמד תורה הגשמיות בהאי עלמא כו' כמו שנים אוחזין בטלית כו' יהי' זה דרך ושביל לנשמה לילך בה בההוא עלמא. גם צ\"ל איך שייך בחי' אורח למעלה כי הנה באדם שייך בחי' אורח שמתחלה הוא במקום זה ואינו במקום אחר ואח\"כ הולך באורח ונעשה במקום אחר ואינו במקום הראשון, אבל אצל הקב\"ה איך שייך בחי' דרך הלא כתיב מכה\"כ ולית אתר פנוי מני' שאין בו בחי' מעלה ומטה כלל ואיך אפשר לומר אורחי' דקוב\"ה משמע שזה אורח שיבוא בו אבל מקודם לא הי' כו' הלא מכה\"כ. גם צ\"ל כי הנה כתיב גבי תורה ארוכה מארץ מדה ורחבה מני ים משמע שאין לה בחי' מדה כלל, ובאמת הרי היא ניתנה לנו בקו המדה שהרי כתוב בזוהר דלא סטי לימינא ולשמאלא, אך הענין שהתורה הנתנה לנו למטה הרי היא בקו המדה אבל כמו שהיא למעלה בשרשה היא ארוכה מארץ מדה כו', והענין כי הנה כתיב בראשית ברא אלקים ות\"א בקדמין וי\"ת בחוכמתא והיינו חכמה דאורייתא כמ\"ש בחכמה יבנה בית וכמ\"ש ה' קנני ראשית דרכו וכמ\"ש בזוהר אסתכל באורייתא וברא עלמא, וכמאמר כולם בחכמה עשית שבכל דבר השתלשלות יש בחי' חכ' והכל הוא הארה בעלמא דחכ' דאורייתא כנ\"ל.\n<b>והנה</b> צריך להקדים מ\"ש בע\"ח בתחלה הי' אוא\"ס ממלא את כל מקום החלל כמ\"ש אתה ה' לבדיך דהיינו כמו שהוא בעצמותו בחי' אא\"ס פשוט בתכלית הפשיטות כך בחי' אורו היינו התגלות עצמותו הוא ג\"כ בבחי' א\"ס ולא"],[1900640321,"הי' בחי' התחלקות ד' עולמות אבי\"ע וכמ\"ש חז\"ל קודם שנה\"ע הי' הוא ושמו בלבד ואתה אחד ושמך א' אתה קדוש ושמך קדוש הוא קיים ושמו קיים, ואח\"כ כשעלה ברצונו לברוא העולם נעשה צמצום מקו\"פ היינו שהאור נכלל במאור ומאמצעות החלל נעשה ד' עולמות אבי\"ע, ואין בחי' זאת כמ\"ש ישת חושך סתרו אלא האור נכלל במאור ונעשה מקו\"פ כמשל כח הראי' שבעין אם עוצם עיניו שאינו רוצה לראות הרי גילוי כח הראי' נכלל בעצם הראי' וכמו אדם העוסק באיזה חכמה אזי מתפשט מעצם כח החכמה להשכיל, וכשפוסק מלעסוק בחכמה אזי נכלל כח התפשטות החכמה בעצם כח החכ', וכמו כח התנועה שביד שבשעה שעוסק באיזה מלאכה אזי מתפשט כח הפועל בנפעל וכששובת ונח ממלאכתו אזי חוזר ההתפשטות לעצם כח התנועה שביד, וכמשל מחיות הנפש בגוף וכשהנפש מחי' את הגוף אזי נק' חיי בשר אבל הנפש קודם בואה לגוף הרי יש בה כח החיות להחיות אך שהוא כלול בעצם הנפש, וכך יובן הנמשל למעלה שהאור נכלל במאור היינו שבחי' גילוי אוא\"ס נכלל במאור ונעשה בחי' מקו\"פ ואח\"כ נעשה בחי' קו להיות מקור לאבי\"ע בלשון הע\"ח ובלשון הפרדס נק' בשם צינור כמ\"ש בשער הצינורות, עד\"מ נהר גדול מאוד שכשרוצה למלאות כלים קטנים מן הנהר והם לא יוכלו לקבל מחמת גודל ריבוי שפע הנהר אזי מעכב את הנהר מלצא[ת] בהתפשטות רב ועושה צינור שימשך בו מי הנהר ומצינור זה עושה צינורות לצדדים כדי שיוכלו לקבל את מי הנהר כלים קטנים ג\"כ , וכל מה שהצינור נתרחק מן הנהר יותר אזי יתקבל בכלים קטנים יותר ונק' הצינור הנמשך מן הנהר צינור כללי ומה שעושים צינורות לצדדי הצינור נק' צינורות פרטי'. וכך יובן הנמשל למשכיל למעלה שהנה יש ג' קווין חח\"נ [מימין] ובג\"ה משמאל ודת\"י באמצע וקו האמצעי נק' צינור כללי וחח\"נ בג\"ה נקראו צינורות פרטים כמ\"ש עבד מאני רברבי וקרא בי' גרמי' חכם עבד מאני רברבי וקרא בי' גרמי' בינה וכן חסד גבורה נצח והוד כו', וכל הצינורות פרטים כולם נמשכו מבחי' צינור הכללי כי כל ספירה היא כלולה מיו\"ד ולכולם יש להם שרש בצינור הכללי וגם בחי' כלים של כל ספירה וספירה כמ\"ש איהו וחיוהי וגרמוהי כולא חד עד"],[1900640329,"בחי' מל' שבמל' דעשי' שנק' בחי' התנשאות כמ\"ש ה' מלך גאות לבש ופעם נק' בשם מדה איך שנק' הכל יש לו שרש בצינור הכללי הנ\"ל וד\"ל, וזהו משל גשמי ומשל היותר רוחני הוא מנפש כי הנפש מושלל מכל בחי' עשר כוחות רצון ושכל כי א\"א לומר שהנפש היא בחי' רצון כי הנה אינו רוצה בכל עת כי יש עת שאינו רוצה כלום ואם הי' הנפש רצון הי' צריך שיהי' לו רצון בכל עת בלי הפסק כלל וכלל אלא הנפש הוא בחי' היול\"י רק שנמשך אח\"כ בחי' רצון קודם ואח\"כ בחי' שכל ולהמציא השכלות ואח\"כ בחי' בינה היינו ההשגה וההבנה לאורך ורוחב ואח\"כ מדות ומדו\"מ, וכ\"ז הוא כשהוא בבחי' התפשטות חוץ ממנו אזי מתחלה צ\"ל רצון ואח\"כ בחי' שכל ומדות ואח\"כ בחי' סוף מעשה, אבל כשהוא בפ\"ע יכול לידע תחלת הרצון עד סוף המעשה בסקירה אחת בלי קדימת רצון למעשה.\n<b>והנמשל</b> מזה יובן למעלה שכשנעשה בחי' קו אזי יש בחי' התחלקות ראשית הקו שהוא מקור עולם האצי' וסוף הקו שהוא בחי' עשי' אבל קודם שנמשך בבחי' קו כתיב צופה ומביט עד סוף כל הדורות בסקירה אחת בלי שום התחלקות עולם האצי' ועולם העשי', ובחי' זו נקרא שיער בעצמו בכח מה שעתיד להיות בפועל היינו שכשהוא בכח קודם שבא לבחי' התפשטות בפועל אזי סוקר הכל בסקירה א' כנ\"ל וכמ\"ש ברמב\"ם בידיעת עצמו יודע את כל הנבראים, וצ\"ל איך שייך לומר בידיעת עצמו שהוא בחי' א\"ס ובלתי בע\"ג ואין לו דבר חוץ ממנו יודע את הנבראים שהוא בחי' בע\"ג דבר שחוץ ממנו, אך הענין הוא שאף אחר התהוות כל הנבראים אין הם חוץ מעצמותו כי גם אחר שנתהוו הרי לכולם יש להם שורש מיוחד למעלה כי כל עיקר התהוותם הוא מבחי' אלקות כנ\"ל במשל הצינורות שגם צינור היותר אחרון נמשך מצינור הכללי כנ\"ל, ובתיבת עצמו כו' יש ב' פירושים הא' הוא שעצמו היינו כמו שהוא בעצמותו ממש כמשל הנפש כמו שהוא בבחי' היול\"י שמושלל מכל בחי' עשר כחות, והב' היינו הארה פשוטה מהנפש קודם שנמשך להיות בבחי' התחלקות פרטים לעשר כחות שכלולים בו כל היו\"ד כוחות ביחד בלי קדימת רצון למעשה, ובבחי' זה יכול לידע תחלת רצונו עם סוף מעשה ביחד בסקירה א' מאחר שכלולים בה כל הכוחות ביחד מפני שהיא הארה פשוטה הנעשה מן הנפש והיא דומה ממש לעצמות הנפש שהיא מושללת מכל עשר כחות וקמי' כולא שוין בחי' רצון וסוף מעשה כנ\"ל.\n<b>ובזה</b> יובן מ\"ש ברמב\"ם בידיעת עצמו כו' היינו הפי' הב' של עצמו כנ\"ל, ובחי' זו נקרא למעלה שיעור בעצמו בכח מה שעתיד להיות בפועל, ובלשון הזוהר"],[1900640337,"גליף גליפו בטה\"ע ולכן יודע את כל הנבראים בסקירה אחת כי הרי בבחי' זו כלולים כל הכחות ביחד בלי התחלקות כלל מפני שנמשכת מבחי' עצמות אא\"ס ולכן הוא בדומה לעצם. והנה יש להבין ענין כל ההשתלשלות מפני מה נעשה באופן זה ולא באופן אחר כמאמר כי הוא ציוה ונבראו כו' חק נתן ולא יעבור כו', כמו במלאכים שיש שש כנפים לאחד אמאי ששה ולא חמישה וגם צורת אדם מפני מה באופן זה ולא באופן אחר וגם לבהמות יש ד' רגלים אמאי לא יותר או פחות. אך הענין כי שיער עצמו בכח בזה האופן ולכך נמשך הפעולה ג\"כ בזה האופן כמשל באדם כמו שמצייר איזה ציור בכח אזי כמו\"כ עושה הפעולה, אך עדיין י\"ל מפני מה שיער עצמו בכח ע\"ז האופן שהנה אמת הוא שאם שיער עצמו בכח אזי יהי' הפעולה דווקא לפי האופן שהוא בכח כנ\"ל במשל, אך מפני מה הי' הכח ע\"ז האופן דווקא ולא באופן אחר והי' אז הפעולה ג\"כ באופן אחר, אך הענין הוא כמ\"ש בזוהר אסתכל באורייתא וברא עלמא וכמ\"ש ואהי' אצלו אמון כמו למשל אומן הבונה בנין נאה ומפואר שמסתכל בלוח נייר שמצייר שם כל אופני הבנין וכמ\"כ הוא עושה בבנין ג\"כ וצ\"ל הבנין דייקא עפ\"י אופן שצייר בלוח, אך למה לא צייר באופן אחר בלוח ויהי' הבנין באופן אחר ג\"כ, אך הענין מפני שעפ\"י חכמה עמוקה השכיל שדייקא ע\"ז האופן יהי' נאה הבנין ולא באופן אחר מפני שאסתכל באורייתא כו' שהוא בחי' חכמה עמוקה שדייקא ע\"ז האופן צ\"ל אופן ההשתלשלו' ולא באופן אחר כנ\"ל במשל.\n<b>וזהו</b> ארוכה מארץ מדה ורחבה מני ים ארץ וים היינו בחי' עלמא דאתגליא ועלמא דאתכסיא והתורה ארוכה מהם מפני שהכל נעשה עפ\"י חכמה דאורייתא כנ\"ל, וכמ\"ש אם לא בריתי יומם ולילה חוקות שמים וארץ לא שמתי כו', שאם לא החכ' דאורייתא חוקות שמים וארץ לא שמתי היינו שלא הי' החקיקה הוא בחי' שיער עצמו בכח ע\"ז האופן כנ\"ל, אך עדיין י\"ל כי הנה האמת הוא שהתורה היא בחי' חכמה עמוקה ואם הי' נתונה לנו ברוחניות צריך שיהי' אורח כו' אך הלא היא נתונה לנו בגשמיות כמו שנים אוחזין כו' המחליף פרה בחמור כו' שגם תינוק יכול להבין אותו ואיך שייך שיהי' זה אורח להנשמה כנ\"ל, והענין כי הנה שית סדרי משנה, הם ו\"ק דיצירה זרעים בחי' חסד ומועד בחי' גבורה כו', וצ\"ל כי הלא כבר הי' עולם היצירה קודם שניתנה לנו תורה בעשי' וכן תלמוד"],[1900640345,"בבריאה ומקרא ומצות מעשיות בעשי' ג\"כ אינו מובן דהלא כבר הי' עולם הבריאה כו'. אך הענין כי הנה זרעים הוא בחי' חסד כי כל ענינו הוא רק להחיות רוח שפלים כמו לקט שכחה ופאה תרומות ומעשרות עשירי יהי' קודש כו' וחמשה לא יתרמו ואם תרמו אין תרומתן תרומה ומוץ ותבן פטורים מן המעשר, הרי שהמשנה היא הוראה שבאופן זה יהי' חסד דיצירה ואם לאו לא יהי' חסד דיצירה כמו חמשה לא יתרמו ואם תרמו כו' מפני שלא נעשה בזה בחי' חסד כלל וכמו מוץ ותבן פטורים מן המעשר היינו מפני שאין להם עלי'. וזהו ששאל עשו לאביו אם מעשרין את התבן היינו ששאל אותו אם אפשרי להיות לו עלי' שמדריגתו הוא בחי' קש ותבן בחי' פסולת וקליפות והשיב לו שתבן פטור ממעשר שאין להם עלי' כי חטה הוא בחי' פנימיות כמ\"ש קודש ישראל לה' ראשית תבואתו ואפשר לו ליכלל בקדושה אבל תבן הוא פסולת וא\"א לו ליכלל בקדושה. וסדר מועד הוא בחי' גבורה כמו שבת ועירובין כי הנה בשבת מאירין בו מוחין דאבא אבל אם הוא מחלל שבת ועושה מל\"ט מלאכות כנ\"ל אינו מאיר ממוחין דאבא וכמו סוכה אם הוא עושה כהלכתה אזי מאיר בחי' מקיפי' ואם לאו אינו מאיר מבחי' מקיפים כל זה הוא בחי' גבורות. והגם שתורה היא מלובשת בגשמיות ואיך יש בה כח להורות שאם עושה כן אזי הוא חסד כו' אך מפני ששרשה הוא בבחי' חכ' עמוקה וכמו למשל אדם החכם ביותר יכול להלביש השכל במשל וחידה יותר גשמיי' ולכן התורה היא הוראה שאם עשה כן הוא בחי' חסד מחמת שהוא בחי' חכ' עמוקה ונעשה כך בכח ואח\"כ בפועל כנ\"ל וזהו שאמר דוד בחוקותיך אשיחה ואביטה אורחותיך אשיחה הוא ענין שיחה בעלמא כי התורה הוא רק גשמיות כנ\"ל כמו ארבעה אבות נזיקין השור והבור והמבעה כו' אעפי\"כ עי\"ז אביטה אורחותיך בחי' אורחות הוי'.\n<b>וזהו</b> כי ישרים דרכי הוי' כל ארחוי דקב\"ה כו' עד\"מ דרך שהוא מעיר גדול לעיר גדול כדי שיוכלו להתחבר יחד, ולא שבני עיר זאת יוכלו לעבור לעיר אחרת ושל אותה העיר לא יוכלו לבוא לעיר שלהם כי אין זה נקרא חיבור אך המכוון של הדרך הוא שבני עיר זאת יוכלו להביא סחורה שלהם לעיר אחרת אשר אין להם סחורה זאת ושל אותה העיר יוכלו להביא הסחורה שלהם לשם שאינו"],[1900640353,"באותה העיר זהו דייקא הנקרא התחברות וגם יש עוד דרכים קטנים לכרכים קטנים שיכולו להתחבר כולם ביחד וכמו בנ\"א שאוהבים זא\"ז אין נק' חיבור רק שילכו זה אצל זה ולא שא' ילך לחברו והשני לא ילך אצלו. וכמ\"כ יובן למעלה שהתורה נקרא בחי' דרך כי כשנברא עולם הבריאה ועולם היצירה הי' נשאר כך ואין זה נקרא חיבור כי החיבור הוא דייקא שיהי' הליכה והחזרה כנ\"ל. וע\"י לימוד התורה הוא מעלה אותם לשרשם בחי' חכ' העמוקה וזהו שאמר דוד בחוקותיך אשיחה ואביטה אורחותיך כנ\"ל וזהו וצדיקים ילכו בם באינון אורחין כו' שע\"י לימוד התורה בהאי עלמא נעשה דרך וילכו באינון אורחין בההוא עלמא. ופושעים יכשלו בם אינון כשלי באינון ארחין בהאי עלמא ובעלמא דאתי כי הנה ארז\"ל אשרי מי שבא לכאן ותלמודו בידו בין לשמה ובין שלא לשמה כי הנה מבואר בכהאריז\"ל שיש ג' בחי' לשמה ושלא לשמה ומיצוע. המיצוע היינו שלומד מחמת טבעו ויש לו מזה תענוג כמו שיש לו תענוג בבגד נאה ואכילה טובה והגם שאחר הלימוד מתפאר בזה שיודע הדין לאמיתו ויכול להורו' כראוי מ\"מ אין זה נקרא רע גמור רק דברים המותרים שמקליפת נוגה כמו קדש עצמך במותר לך ולפיכך בשבת מותר לאכול אכילה לתאבון דאעפ\"י שהוא מקליפת נוגה אך הם דברים המותרים שמנוגה ובשבת יוכל להכלל בקדושה. וזהו אשרי מי שבא לכאן ותלמודו בידו אפילו לימוד כזאת מפני שכד נפיק מהאי עלמא הולך אחריו הדבר ה' שהרי גם כל המחשבות והרהורים הולכים אחריו וכש\"כ הדבר ה' הגם שהי' לו איזה פני' כנ\"ל מ\"מ נזדכך ע\"י נהר דינור וגהינם שאש גדול שואב אש קטן ממנו והתועלת מלימוד התורה הוא שנעשית ע\"י לבוש להנשמה שתוכל להנות מזיו השכינה בג\"ע.\n<b>ומ\"ש</b> ולרשע אמר אלקים מה לך לספר חוקי קאי על לימוד התורה שלא לשמה לגמרי דהיינו שעיקר נקודת כוונתו הוא רק להתייהר ע\"מ שיקראנו רבי ואם לאו לא הי' לומד כלל ואין בו בחי' טוב כלל והוא עושה עצמו כע\"ז כמ\"ש לי יאורי כו' ידינו רמה כו' ע\"ז אמר הכתוב מה לך לספר חוקי כי עי\"ז נותן תוספות יניקה לחיצונים וז\"ש בזוהר לאתערא דינין ומ\"ש אורך ימים בימינה בשמאלה"],[1900640361,"עושר וכבוד וארז\"ל למיימינים בה היינו שעוסקים לשמה אורך ימים ולמשמאילים היינו שעוסקים שלא לשמה, עושר וכבוד כו' וכן מה שארז\"ל רשע שעה משחקת לו כי הלא העוסקים שלא לשמה נותנים תוספות יניקה לחיצונים כמארז\"ל יורד ומסטין עולה ומקטרג ורוח אייתי רוח ואמשיך רוח וכל חיותם של החיצונים הוא רק לפעול רע כמארז\"ל למיימינים בה סמא דחיי ולמשמאילים בה סמא דמותא ואיך משפיעים לו עושר וכבוד ואיך שעה משחקת לו שהוא בחי' חסד. אך הענין הוא שטובתם שנותנים לרשעים זהו גופא הוא רע כדי להאבידם וכמשל אדם שהוא שונא לחבירו ורוצה להאבידו ועושה סעודה גדולה וקורא אותו על הסעודה ונותן לו כל מעדנים טובים ואח\"כ הורג אותו. ונמצא שכל הטובות שעשה לו באמת הוא רע גמור כדי להאבידו כי אם לא הטובות לא הי' יכול להורגו וכך הוא ברשעים שכל טובתם שנותנים להם בעוה\"ז אינו רק כדי להאבידם בעוה\"ב ונמצא שהטובה היא רע גמור. וזהו ופושעים יכשלו בם בם דייקא שכד נפיק מהאי עלמא מוליכין אותו להיכלות החיצונים והולך אחריו גם דבר ה' שניתוסף עי\"ז יניקה לחיצונים וזהו יכשלו בהו כו'. ולכן בעוסקים לשמה כתיב אדם כי ימות באוהל וארז\"ל אין התורה מתקיימת אלא במי שממית עצמו עלי' וכמו שארז\"ל הלומד את התורה מעוני סופה לקיימה מעושר היינו מפני שהוא מעורב בתערובות הגוף אעפ\"י שעוסק לשמה מ\"מ א\"א שיהי' בלא תערובות הגוף לכן ע\"י לימוד התורה מעוני ודוחק הוא מברר לאיזה תערובות הגוף שיש כו' כנ\"ל וד\"ל."],[1900640313,"<b>פ' וישב תקע\"ח לפ\"ק\n[זוהר וישב קפ\"א ע\"א]</b>\n<b>ר\"ש</b> פתח אך אל הפרוכת לא יבוא כו', כד סהירא אתפגים כו' כדו כל אינון נשמתין דנפקין אע\"ג דכולהו דכיין וכולהו קדישין כו' בכמה צעירין ובכמה כאיבין כו' ואילן איקרין יסורין של אהבה וצ\"ל הענין שנשמות של צדיקים שנבראו בשעת פגימות הלבנה חייהם בצעירין וכאיבין ונקרא יסורין של אהבה, כמ\"ש וישב יעקב וארז\"ל ביקש לישב בשלוה וקפץ עליו רוגזו של יוסף, ונשמות של צדיקים שנולדו בשעת מילוי הלבנה חייהם בנחת ושלוה, וצ\"ל תחילה ענין פגימות הלבנה כי פגימה משמע לשון חסרון והלא הלבנה בעצמה אינה נחסרה כלום רק שאור השמש אינו מאיר בה כי סיהרא לית לה מגרמה כלום, פי' שבעצמו' היא אור רק שאין בה כח להאיר על הארץ כ\"א כשמקבלת מאור השמש, וזהו לית לה מגרמה כלום היינו שאין בה כח מצד עצמה להאיר על הארץ כ\"א שמקבלת כו' ואיך שייך לקרות לשון פגימה כשאינה [מאירה] על הארץ כי הלא בעצם הלבנה אינה נחסר כלום רק מה שאינה מאירה למטה הוא מחמת שאינה מקבלת מאור השמש. והראי' לזה כי הרי אחר ב' וג' ימים כשמקבלת מאור השמש הרי היא מאירה למטה ואם הי' חסרון ופגם בעצם הלבנה לא הי' יכולה להאיר אף שמקבלת אח\"כ מאור השמש, כמו למשל כח הראי' שבעין שאם איזה קלקול בעין כמו בדקין שבעין לדידן הוי מומא כו' אינו רואה בעין לעולם מחמת קלקול הכלי, ואם הי' הלבנה ג\"כ נפגמה בעצם לא הי' מאירה לעולם כנ\"ל במשל.\n<b>להבין</b> זאת צריך להקדים מ\"ש אך אל הפרוכת לא יבוא כו' כי מום בו כו', וצ\"ל הענין מה שכהן בעל מום אסור לבוא למקדש ואע\"פ שהוא חכם וצדיק רק אם הוא מחוסר אבר גשמי כמו אצבע כו' מפני שכל ההמשכת אלקות שעשה ע\"י כהן ואם הוא בעל מום א\"א להיות ע\"י השראת אא\"ס ב\"ה וגם אין מקריבין קרבן בעל מום ע\"ג המזבח מפני שא\"א לו ליכלל בקדושה, אבל בכנס\"י כתיב כולך יפה רעייתי ומום אין בך וכמארז\"ל אפילו חגרת או סומא מ\"מ כלה נאה וחסודה. להבין זה צריך להקדים עוד מארז\"ל אתם קרוים אדם ואין אוה\"ע קרוים"],[1900640322,"אדם וכמ\"ש ויברא אלקים את האדם בצלמו ובצלם אלקי' עשה את האדם, כי אא\"ס בעצמו הוא פשוט בתכלית הפשיטות כמ\"ש חכים ולא בחכ' ידיעה מבין ולא בבינה ידיעא כו' ולאו מכל אילין מדות כלל כמ\"ש כי לא אדם הוא ואין לו גוף ולא דמות הגוף אפילו דמות גוף רק אחרי הצמצום נעשה בחי' ציורי אדם, וכשיש איזה מום באדם התחתון אזי אינו שורה עליו אא\"ס בחי' כי לא אדם הוא, וצ\"ל הטעם מפני מה אם יש איזה פגם כמו חסרון אבר באדם התחתון אזי אינו שורה עליו אוא\"ס הלא הוא למעלה מבחי' אדם כמ\"ש כי לא אדם הוא.\n<b>אך</b> הענין שאא\"ס בחי' כי לא אדם הוא אינו שורה דייקא כ\"א על בחי' אדם כשהוא בשלימות בלי שום חסרון, אך עדיין צ\"ל כ\"א הי' הפגם באדם רוחני' אזי שייך לומר שאא\"ס אין שורה עליו אבל איך שייך לומר שאא\"ס אינו שורה אם יש איזה פגם וחסרון רק באדם התחתון. אך הענין הוא כמ\"ש בזוהר שיש ב' מיני אברים, ובלשון הע\"ח נק' אורות וכלים ולבושים, כי הנה יש ב' דעות בבעלי המקובלים הא' שתחילה נעשה בנין אורות ואח\"כ בנין כלים כמו הנפש קודם בואה לגוף יש בה כל העשר כחות כמו שכל ומדות שהרי נק' נפש המשכלת בשלימות כמו שיהי' אחר ע' שנה בגוף שיהי' בתכלית גדלות המוחין וכן מדות כו' ונקרא אדם פנימי, ואח\"כ בנין כלים היינו כשבאה לגוף נתלבשו האורות בכלים ונקר' אדם חיצוני', ומה שתינוק שכלו קטן היינו מפני שהכלי שלו קטן אבל אור השכל הוא בשלימות כמו כשיהי' בן ע' שנה, ולכן ארז\"ל בוצין בוצין מקטפי' ידיע מפני שהאור הוא בשלימות כמו שיהי' כשיגדל כנ\"ל וכן מדות, בתחלה כלי המדות הם קטנים ואח\"כ נגדלים ולכן אז מקחו מקח וממכרו ממכר אבל האורות הם בשלימות מתחילה וכו', וח\"א שתחילה בנין כלים ואח\"כ בנין אורות היינו שהאורות נעשים לפי ערך הכלי, כי כאשר נתהווה הכלי אזי לפי ערך יומשך בו האור ומתחילה הכלי קטן אזי האור ג\"כ קטן ואח\"כ כשנתגדל הכלי נתגדל ג\"כ האור, ומחלוקתם היא גבי מ\"ם יום של יצירת הולד דח\"א מתחילה בנין אורות היינו שתחלה יומשך הנפש ואח\"כ נתהווה הכלים אודם שממנו בשר מן האם מ\"נ"],[1900640330,"ולובן שממנו העצמות מן האב וגידים הוא המחבר עצמות עם בשר כו', וח\"א שתחלה בנין הכלי' היינו שמתחלה נתהוה בשר גידין ועצמות ואח\"כ בנין האורות שאח\"כ יומשך בהם הנפש, וכמארז\"ל שהמלאך הממונה על ההריון מביא טיפה ושואל טיפה זו מה תהא עלי' חכ' או טיפש כו', הרי מובן מכ\"ז איך שיהי' אם תחלה בנין האורות ואח\"כ בנין כלים, ומכש\"כ כשתחילה בנין כלים ואח\"כ בנין אורות שהכלי היא עצמיות אם האור היינו אם החומר מעין הצורה דייקא כמו עד\"מ שכח הראי' דייקא יתלבש בעין מפני שהעין הוא עצם בהיר מעין עצמיו' הצורה ולכן בם דייקא יתלבש כח הראי' ולא בזולתה. ונמצא אם יש איזה חסרון ופגם בכלי העין יש חסרון בכח הראי' ג\"כ ולא שכח הראי' הוא בשלימות רק שאינו מתפשט בהכלי אלא שבכח הראי' ג\"כ יש חסרון, וזהו שכהן בעל מום אסור לעבוד עבודה ואע\"פ שהוא חכם וצדיק מפני שאם יש איזה חיסרון ופגם באבר גשמי יש חסרון ג\"כ באבר הרוחני וא\"א להיות ע\"י השראת אא\"ס בחי' כי לא אדם כו' וכנ\"ל, ולכן אין עונשין כ\"א על המעשה דייקא מפני שרמ\"ח פיקודין רמ\"ח אברים דמלכא ואם עושה עבירה באבר גשמי אזי פוגם באבר רוחני משא\"כ הרהור לא עביד מידי, והגם שהרהורי עבירה קשים מעבירה היינו מפני שהוא ממשיך עליו כח הטומאה אבל אינו עושה פגם למעלה כ\"א ע\"י מעשה בפו\"מ דייקא, ולבושים הוא בחי' מחשבה דו\"מ שנקרא בשם לבושים כמ\"ש כלבוש תחליפם היינו שאינם בחי' עצמיות כמו אור וכלי רק הוא כמו לבוש האדם שברצותו פושט לבוש זה ולובש לבוש אחר, כי יש ב' בחי' שכל פשוט ושכל מורכב, שכל פשוט היינו עצם מהות השכל קודם שבא לידי גילוי בהשגה כמו שנים אוחזין בטלית או כמו ברוך שאמר והי' העולם שיכול לחשוב בזה בכמה אופנים כמו שאמר פי' בדבור הי' העולם או פי' במח' זה נקרא בחי' שכל מורכב שמתפשט באותיות השכל, ושכל פשוט היינו עצם מהות השכל של ב\"ש והי' העולם קודם שיחשוב באותיות השכל להשיגו, והראי' לזה מב' בנ\"א ששומעין שכל א' שזה משיג השכל באופן זה וזה משיג באופן אחר, הרי נראה שעצם השכל א' הוא אך כשבא לידי התפשטות לזולתו אז יש בו התחלקות שזה תופס באופן זה וזה באופן אחר ונק' שכל מורכב."],[1900640338,"<b>והנה</b> השכל הפשוט כלי שלו מוח גשמי שנקרא חומר הפשוט והוא עצמיות עם השכל כי החומר הוא מעין הצורה דייקא וכפי מזיגת המוחין ככה יתלבש בו צורת השכל אבל שכל מורכב הוא בבחי' לבש שהוא אותיות השכל, ונקרא לבוש משום שיכול לחשוב באותיות אלו ואם ירצה יחשוב היפוכו ממש ואינו עצמותו כמו בחי' אור וכלי הנ\"ל, וכן במדות יש ג\"כ בחי' אלו שעצם המדות שבלב אינו יכול להשתנות בשום אופן כמו למשל אם נתעורר בלבו חסד כמו להחיות רוח שפלים אם מתפשט החסד בכלי היד ונותן לעני צדקה ואינו יכול לעשות היפוכו בכלי היד כמו להכות העני, או להיפוך אם נתעורר בגבורה אינו יכול לעשות בכלי היד חסד מחמת שהכלי הוא בחי' עצמיות עם עצמיות עם האור כנ\"ל כמאמר חוק וזמן כו' שלא ישנו את תפקידם, אבל מדות שנתהוו מצד השכל יכול לחשוב היפוכם ממש כמו אם השכיל בשכלו לאהוב ממון וכה\"ג יכול לחשוב מיד היפוכו דהיינו ליטול המעות ולזרוק בנהר וכה\"ג, מחמת שאינו עצמיות עם האור רק כמו לבוש שכשרוצה פושט ולובש לבוש אחר, ויש עוד בחי' שאותיות מגבילות להשכל ויש בזה מעלה וחסרון, החסרון הוא שידע איך להלביש השכל באותיות השייכים לו דייקא כמו שאמר והי' העולם צריך לכתוב ד' אותיות שאמר ואם יהי' פחות או יותר אזי לא יהי' השכל מובן מזה כלל, והמעלה הוא שאם הלביש השכל כראוי אזי מובן מזה השכל לאמיתתו.\n<b>והנה</b> כשצריך להלביש השכל באותיות מחולקים תחלה ואח\"כ יסדרם ביחד ואם יהי' מפוזרי' במקומות רבים כמו אותיות שאמר אם יהי' השין רחוק מהא' אזי לא יהי' מובן תיבה שאמר רק שצריך להיות סדק מפולש בין אות לאות כמארז\"ל כל אות שאינו מוקף גוויל מארבע רוח' כו' שצריך להיות אויר מקפת בין אות לאות, וכמו דברי חכמים בנחת נשמעים שאם מדבר במהירות אזי האותיות מבולבלים ואינו מובן ממנו השכל, אבל כשמדבר בנחת אזי האותיות מסודרים כראוי ולכן מובן השכל לאמיתו (כמו למשל בצק שכשהוא חתיכה א' אין ניכר בו שום התחלקות אמנם כאשר מחלק לחלקים רבים הגם שאח\"כ לש אותם ביחד ומחברם היטב אעפי\"כ א\"א שלא יהי' סדקים מפולשים מעט בין חתיכה לחתיכה, וכך יובן בנמשל שמתחלה מחלק השכל לחלקים באותיות ואח\"כ כשמקרבם יחד צריך להיות אויר מקו\"פ בין אות לאות כו'). ויש עוד שנקרא ג' נקבי עור שהן ג' מיני אותיות אותיות המחשבה ואותיות הדיבור ואותיות הכתב שיש בעור נקבים שהזיעה יוצאת משם והוא פסולת הדמים, והשערות"],[1900640346,"נמשכו מאותן הגומות שהזיעה יוצאות כמ\"ש בשערהא אחידן כו' שהיא פסולת ומותרות לגמרי.\n<b>כמו\"כ</b> יובן למעלה כי בחי' מל' דאצי' מחי' בי\"ע וכתיב זלעו\"ז עשה אלקים שמחי' גם ע' שרים אין החיות שלהם מהקדושה רק מהפסולת ומותרות לגמרי, משם מקבלים חצוניות יניקה ולא ממקום פנוי שבין אות לאות שהמקו\"פ בחי' חכמה הוא שאם לא יניח מקו\"פ בין אות לאות לא הי' השכל מובן מזה כלל כנ\"ל וכתי' וכבודי לאחר לא אתן שהוא בחי' חכמה לא אתן לאחר שהוא החיצונים ואין לע' שרים שרש ויניקה אלא מבחי' פסולת ומותרות, עד\"מ אדם המדבר שכל לערך שעה או חצי שעה א\"א שלא יהי' כמה דיבורים זרים שאינם שייכים לשכל כלל אלא הם מותרות ונובלות לגמרי (כמ\"ש ועליהו לא יבול וארז\"ל שיחת חולין של תלמידי חכמים צריכים לימוד, שמי שהוא חכם ביותר אין בדיבורו שום נובלו'), כמו\"כ יניקת החיצונים הוא מבחי' נובלות ומותרות שאין בו בחי' חכמה כלל.\n<b>ועתה</b> צ\"ל מגוף המאמר הנ\"ל באהבה זוטא דאתדחיא מאה\"ר, והנה יש בזה ב' פירו' האחד הוא דאהבה זוטא אתדחיא מאה\"ר כשבא אה\"ר אתדחיא מיני' אהבה זוטא ופי' הב' והוא עיקר כשאה\"ר אתדחיא נשאר רק אהבה זוטא והוא עד\"מ הצמא למים שיתאוה מאד בתשוקה רבה מיסוד האש שבלב אל המים, ואח\"כ כשמביאים לו המים אזי נתקרר ההתלהבות ושותה בנחת ואינו יכול לומר שמתחלה כשלא הי' לו מים הי' מתאוה לה ועכשיו כשיש לו מים אינו מתאוה להם, אדרבה בודאי התענו' יותר גדול כשמביאים לו המים מתחילה כשלא היו לו מים שהרי כל ההתלהבות שהי' לו מתחלה אינו רק אלא שהי' צמא למים, אך הענין הוא שמה שאין נראה ההתלהבות כשמביאים לו המים לא מחמת שאין לו תענוג אדרבה אז הוא עיקר התענוג ולכן אינו מורגש בהתלהבות, אבל מתחלה כשאין לו מים אז הוא היפך התענוג כי כל עיקר ההתלהבות מיסוד האש הוא מחמת שאין משיג התענוג והוא בחי' צער היפך העונג, כי עונג אותיות נגע ולפי ערך הדבר שיש בו תענוג גדול כשמשיגו אזי לפי ערך יש לו צער גדול"],[1900640354,"מהעדר השגה, ואם הדבר שיש בו תענוג גדול כשמשיגו אזי לפי ערך יש לו צער גדול מהעדר ההשגה, ואם הדבר ההוא אין לו תענוג כ\"כ כשמשיגו אזי ג\"כ לפי ערך אין לו כ\"כ צער מהעדרו. ויש עוד שבשעת הצימאון לא יוכל לסבול צערו עד שיהי' כל דבר הקל גדול בעיניו לסובלו שהוא היפך התענוג שיסבול אף כל דבר הקשה בעיניו מאד כו', ובצער הצמאון לא יוכל לסבול אפילו דבר קל מאד שהי' יכול לסובלו כו'.\n<b>ועפ\"י</b> כל הנ\"ל יובן למעלה דאהבה זוטא נקרא קטנו' המוחין כמשל תינוק שאין לו רק קטנות המוחין בחי' נה\"י, כי הנה יש מושכל מורגש מוטבע, מוטבע בחי' נה\"י מורגש חג\"ת מושכל בחי' חב\"ד, ובתינוק אינו מאיר בו רק בחי' נה\"י ואה\"ר נקרא בחי' גדלות המוחין בחי' מושכל, וזהו ההפרש אשר בין תפילת שבת לתפילת חול כי על תפילת חול נאמר כי חולת אהבה אני שהוא קטנות המוחין דהיינו מרירות מהעדרו שאינו משיג אלקות כנ\"ל במשל הצמא למים, אבל בשבת כתיב אז תתענג על הוי' שהוא בחי' התענוג מאלקות שמשיגו כנ\"ל, וזהו אהבה זוטא דאתדחיא מאה\"ר שאין אה\"ר מאיר כעת בזמן הגלות שהוא בחי' קטנות המוחין שהוא בחי' מרירות מהעדר אלקות, ובחי' אה\"ר הוא בחי' מוחי' דגדלות זה יהי' לעתיד.\n<b>וזהו</b> שכתיב בזוהר כד אתפגמת סיהרא שהוא בחי' מוחין דקטנות שאין מאיר בהן מאור השמש בחי' אה\"ר לכן הצדיקים שנולדים בזמן הזאת הם צעירין וכאיבין ונק' יסורים של אהבה היינו שכל עבודתם הוא בחי' צער ומרירות מהעדר אלקות, אבל לעתי' כתי' והי' מידי חודש בחדשו יבא כל בשר כו' והי' אור הלבנה כאור החמה כאור שבעת ימי בראשית בחי' אה\"ר גדלות המוחין התחדתותי' דסיהרא שיהי' הלבנה במעלה עליונה אזי יתעלו הצדיקים שנולדו בשעת פגימת הלבנה בחי' קטנות המוחין, ועבודתם מצד מרירות יותר מהצדיקים אשר עבודתם בבחי' עונג וכמ\"ש באביתר כי התענית בכל אשר התענה אבי היינו מפני שהי' אתו בצרה אחת לכן לסוף כשמלך ריחם עליו ג\"כ וכמו\"כ בצדיקים הנ\"ל בחי' מוחין דקטנות שהוא בחי' א' עם פגימות הלבנה, לכן לעתיד כתי' והי' אור הלבנה כו' יתעלו גם הם כנ\"ל וד\"ל."],[1900640314,"<b>בעז\"ה ויגש תקע\"ח לפ\"ק\n[זוהר דף ר\"ה ע\"א]</b>\n<b></b>[זוהר דף ר\"ה ע\"א] ויגש אליו יהודה רבי אלעזר פתח כי אתה אבינו כי אברהם לא ידענו וישראל לא יכירנו אתה ה' אבינו גואלנו מעולם שמך כו', אבל ת\"ח כד ברא קוב\"ה עלמא כל יומא ויומא עביד עבידתא כדקא חזי בכל יומא ויומא כמה דאצטריך כיון דאתא יומא שתיתאה ואצטריך למברא אדם אתי' אורייתא קמי' אמרה האי אדם דאת בעי למברי זמין הוא לארגזא קמך אלמלא לא תאריך רוגזך טב לי' דלא איתברי. אמר לה קוב\"ה וכי למגנא איתקרינא ארך אפים אלא כולא באורייתא אתברי וכולא באוריית' אשתכלל בגין דעד לא ברא קוב\"ה עלמא אתיין כל אתוון קמי' ועאלו כל חד וחד למפרע. עאלת אות תי\"ו אמרה קמי' רעותיך למברי בי עלמא אמר לה לאו כו', כיוון דנחת כ\"ף מעל כתרא אזדעזעו עלאי ותתאי כו' עד דאתקיים כולא באת בי\"ת דאיהו סימן ברכה ובי' אשתכלל עלמא ואתברי. ואי תימא דאל\"ף איהו רישא דכל אתוון יאות איהו אלא בגין דאתקרי בי' ארור כו', בגין דלא למיהב דוכתא לסט\"א דאקרי ארור לא אתברי בי' עלמא ואשתכלל בבית עלמא ובי' אתברי כו', כי אברהם לא ידענו דהא אע\"ג דבי' קיומא דעלמא לא אשתדל עלן כמה דאשתדל על ישמעאל דאמר לו ישמעאל יחי' לפניך. וישראל לא יכירנו בגין דכל ברכאן דאצטריך לברכא לבנוי כו' שבק להאי דרגא לברכא כולהו. אתה ה' אבינו כו'. פי' באת אות בי\"ת ב' דבראשית כמ\"ש בחכ' יבנה והנה כתיב חכמות כו' שיש ב' מיני חכמה חכ' בראש אור אבא דאצי' וחכ' בסוף הוא חכ' שבמל' דאצי' חכ' תתאה חכ' שבדיבור כמ\"ש אבא יסד ברתא מצרף לחכ' שבחי' חכ' מצרף האותיות, שאותיות עצמן שרשם למעלה מבחי' חכ' רק כשירצו לדבר החכמה מצרף אותם איך לדבר, כמ\"ש ה' אבנים בונות ק\"ך בתים פי' אבנים הם אותיות אינו רק חמשה בונות ק\"ך בתים דהיינו כשמצרף האותיות באופן זה ויהי' הדיבור ג\"כ באופן [זה] וכשמצרף באופן אחר יהי' הדיבור באופן אחר, ויוכל לעשות מה' אותיות ק\"ך מיני צירופים, ושרש הצירוף אינו מחכמה הגלוי' בהשגה אלא מחכ' הסתומה כי חכ' מאין תמצא שבחי' חכמה נמשך"],[1900640323,"מבחי' אין מקור השכל ונקרא משכיל וח\"ס ומשם נעשה הצירוף והראי' שאינו מרגיש בעצמו איך נעשה הצירוף כשמדבר אלא הוא נעשה מאליו ואינו מרגיש כלל, ונמצא שהצירוף נעשה מבחי' אין מקור השכל שנק' משכיל ולכן אינו מרגיש איך נעשה, ועוד ראי' דהרי לפעמים גם שמשיג איזה שכל אינו יכול להוציאו בדיבור והוא מפני שלא נמשך הצירוף ממקור השכל וכשנמשך אופן הצירופי אותיות איך לדבר אז יכול לדבר, וכמו תינוק שאינו יכול לדבר כל ימי יניקה הוא ג\"כ מפני שלא נמשך הצירוף ממקור השכל וכשנשלם ימי יניקה אז נמשך הצירוף ממקור השכל ויכול לדבר, וז\"ש אבא יסד ברתא אינו קאי על בחי' חכמה הגלוי' אלא על בחי' חכמה סתימאה, וזהו מ\"ש בחכ' יבנה בית הוא חכמה טל תורה כמ\"ש בראשית ברא כו' וארז\"ל בשביל התורה שנקראת ראשית וכמ\"ש בזוהר אסתכל באורייתא וברא עלמא, וצ\"ל ענין כי אברהם לא ידענו וישראל כו' כי אברהם הוא בחי' כמ\"ש אברהם אוהבי לא ידענו וכמאמר הזוהר את לא השתדל על עם, וצ\"ל והלא כתיב והוכן בחסד כסא וכתיב כי אמרתי עולם חסד יבנה.\n<b>להבין</b> כל זאת צריך להקדים מ\"ש והחכמה תחי' בעלי' שיש בזה [ב'] פירושים, הא' הוא שבעלי' היינו הכלי דחכ' פי' מי שראוי לחכמה החכמה תחי' אותו היינו שמשפיע לו חכ', והב' היינו שבעלי' הוא מקור החכ' כי החכ' מאין תמצא מבחי' אין וכתר, וזהו דבר הפלא שהחכמה תחי' למקור החכ' בחי' כתר. והענין כי הנה לפעמים נק' החכ' בחי' חסד קו ימין כי חח\"נ מימין כו' כי אבא הוא מקור החסדים כי טבע הטוב להטיב שכל מי שיש בו יותר חכמה יותר יוכל לסבול אף דבר שנגד רצונו והתינוק מתקצף מדברים קטנים מפני ששכלו קטן ולפעמים נקרא חכמה דין כמו ה\"ג שבחסד. אך הענין הוא כי תחילת בריאת העולמות הי' מצד כי חפץ חסד הוא כמ\"ש בע\"ח כשעלה ברצונו לברוא כו' מצד כי חפץ חסד"],[1900640331,"כו' אך עיקר המכוון של הרצון הוא כדי לאהפכא חשוכא לנהורא ולברר בירורים. ויובן זה עד\"מ מאדם התחתון למטה שיש אדם ששכלו מטה כלפי זכות ויש אדם ששכלו מטה כלפי חוב וכמו ב\"ש וב\"ה הללו אוסרין והללו מתירין משום שמי ששכלו מטה כלפי זכות כל השכלות שלו הוא רק לזכות, ולדין לא תוכל להמציא השכלות, והגם שממציא איזה שכל לדין אינו לאמית', ומי ששכלו מטה כלפי דין הוא להיפוך שכל סברא והמצאה שמשכיל הוא רק לדין בסברות נכונות באותו דבר עצמו שזה מוצא בו השכלות לזכות וכמ\"ש באחיתופל כאשר ישאל איש בדבר אלקים כל עצת כו' וכמו חכמים המה להרע ואע\"פ שחכמה הוא אך שהוא רק להרע. והנה לכאורה הוא מצד בחי' עצמותו שזה בעצם טבעו חסדן לכן מוצא השכלות רק לזכות כו' וזה טבעו בחי' דין לכן מוצא השכלות רק לדין כנ\"ל, אך אנו רואים שגם מי ששכלו נוטה לדין יכול להתהפך לחסד כמו כי השוחד יעור כו' וכמו אי בעי טעין הכי, כי הענין הוא כי או\"א מלבישים זרועות דאריך חכמה מלביש לבחי' נצח דאריך כו' כי א\"א להיות רצון פשוט שאם הוא רוצה אזי הוא מלובש באיזה דבר מה כמו באהבה או להיפוך דבר שנגד רצונו הוא מסלק הרצון, ונמצא שיש ברצון ג\"כ התחלקות קווין גבורה דאריך וחסד דאריך וכל השכלות שמוצא הכל ע\"י הרצון היינו שאם רוצה חסד מוצא השכלות לחסד ואם רוצה דין מוצא השכלות לדין, ונמצא שהרצון הוא מקורם ויסודם ולכן השוחד יעור כו' הגם ששכלו נוטה לדין היינו שרצונו הי' לדין אבל ע\"י השוחד רוצה לזכות אותו לכן מוצא שכל לזכות, ויש כח ברצון שאם הוא רוצה לעשות חסד הגם שיהיו כמה קטיגורים שמוצאים עליו חובות בשכל גמור אך מחמת תוקף הרצון אינו שומע להם כלל, כמו שמי שהוא בטבע חסדן אזי משפיע לכל גם למי שאינו ראוי כי ההשפעה הוא מצד עצמו שהוא חפץ חסד ולא מצד המקבלים, כמו דור אנוש שהיו מושפעים כל טוב הגם שהיו רשעים ועפ\"י שכל לא היו ראוים לזה רק מחמת שהוא רצה להשפיע ואינו תלוי במקבל כלל כמו ויבואו בני האלקים כו' שמלמדים חוב הגם שאומרים בשכל וטעם אינו שומע להם מצד שהוא רוצה כך כנ\"ל וכמארז\"ל כמה ארך אפים לפניו כו', ולהיפוך אם רוצה דין הגם שיהי' כמה סניגורים שמלמדים זכות בטוב טעם ודעת אינו שומע להם כלל מחמת תוקף הרצון לדין כמו תכלית שנאה שנאתים כו', וכמו בזמן חורבן בהמ\"ק הגם שע\"פ"],[1900640339,"תורה לא היו מחויבים עונש בזה אך מחמת תוקף הרצון לדין נחרב בהמ\"ק, וכמו מי יודע עוז אפיך כו'.\n<b>והנה</b> מ\"ש בחכמה יבנה בית קאי על בחי' חכמה שנקרא דין ולא על בחי' חכמה שנק' חסד קו ימין חח\"נ כי זה אין נקרא שלימות כי יש ג\"כ עוד קו שמאל בג\"ה, ועוד שהם סותרים ומנגדים זע\"ז רק בחכ' שנק' דין בחי' תיקון התכללות ב' קווין ימין ושמאל היינו להשפיע רק עפ\"י שכל וטעם שישקול במאזני שכלו אם ראוי כן אם לאו, וחכמה זו נקרא בחי' דין דהיינו לעיין ולפקח בעין השכל אם צריך להשפיע אם לאו, ונקרא בחי' תיקון וקיום להעולם כמ\"ש מלך במשפט יעמיד ארץ שע\"י משפט דייקא יהי' קיום והעמדה, עד\"מ מלך שהוא בשביל קיום המדינה וצריך לפקח בשכלו איך להתנהג שאם ישפיע הכל חסד איש את רעהו חיים בלעו ואם יטיל אימה ביותר שיתנהג רק בבחי' דין וגבורה אזי יהיו רוצחים וכדומה רק שצריך להיות המיצוע, כמו אם משפיע חסד לאוהבו ורואה בעין שכלו שאם משפיע לו חסד יותר מדי יהי' לו רעה מזה החסד אזי משפיע לו דין, או להיפך לשונאו אם ירחיקהו לגמרי אזי יפרוץ הגדר לגמרי לכן מקרבו באהבה וחסד וכמו ונקלה אחיך לעיניך כיון שלקה הרי הוא כאחיך ואין הכאה זו שמכה אותו רק בשביל שהוא ראוי לההכאות מחמת שעשה רע אלא שכל עיקר ההכאה הוא רק בשביל הטובה שלו שאח\"כ יחזור בתשובה ונמצא שההכאה היא טובתו ממש, ולכן ארז\"ל חייב אדם לברך על הרעה כשם שמברך על הטובה ואין מספיק בזה שיקבל הרעה בשמחה אלא שצריך לברך ג\"כ והיינו מפני שאינו יודע מהו רעה ומהו טובה כי אין אדם יודע מה רעתו ומה טובתו. וזהו בחכמה יסד ארץ שעיקר היסוד ותיקון ארץ ע\"י חכמה שנקרא קו המדה וכמאמר הזוהר בי' אשתכלל עלמא, ונמצא שבחי' תיקון הוא שהמדה נעשית עפ\"י שכל היינו שאם שכלו מורה שצריך להשפיע חסד אזי משפיע חסד ואם השכל מורה שצריך להשפיע דין אזי משפיע לו דין ולא שהשכל נעשה עפ\"י המדה, שכמו שרוצה מוצא ג\"כ שכל כזה אלא שהוא אינו רוצה כלל לא דין ולא חסד רק איך שהוא מפקח בעין שכלו ככה תעשה המדה כנ\"ל, ובחי' התורה היא ג\"כ בחי' חכמה שנקרא דין קו המדה בחי' תיקון כי ארז\"ל למיימינים בה היינו שעוסקים לשמה"],[1900640347,"סמא דחיי למשמאילים בה שעוסקים שלא לשמה רק לקנטר ולהתייהר סמא דמותא, כמו למשל דבר מתוק ודבר מר שהם שני הפכים בתכלית, אדם שאוהב מתוק אם נותנים לו דבר מר אינו כלום אצלו, אך ברפואה יש התכללות מב' הפכים שמרכיבים כמה מינים שונים ונותנים אותו להחולה אם הרופא משיג החולאת אז הוא לו סמא דחיים ואם לאו אזי הוא לו סמא דמותא, ונמצא שרפואה זו עצמה יכול להיות סמא דחיים וסמא דמותא כנ\"ל, כמו\"כ התורה היא ג\"כ סמא דמותא וסמא דחיים כנ\"ל.\n<b>ובזה</b> יובן מ\"ש והחכמה תחי' בעלי' דקאי על בחי' חכמה דתיקון שתחי' למקורה בחי' כתר מפני שבכתר יש התחלקות קוין חח\"נ מימין בג\"ה משמאל ויכול להיות שתגבר קו ימין על שמאל ויופסק קו שמאל ויהי' רק בחי' חסד או להיפך שתגבר שמאל על ימין ויהי' הכל בחי' דין, משא\"כ בחי' תיקון שהוא בחי' התכללות משניהם ומתנהג רק עפ\"י הוראת השכל שאם צריך לחסד משפיע חסד ואם דין משפיע דין ואם צריך לשניהם אזי נכללים שניהם יחד, אז לא יופסק לעולם ולכן החכמה תחי' בעלי' מפני ששרש דתיקון הוא משלימותא דכולא שלפני התחלקות הקוין דכתר. ובזה יובן מ\"ש ימותו ולא בחכמה שכשמאיר הארת חכמה דתיקון אין בו בחי' מיתה והפסק כנ\"ל.\n<b>ועתה</b> צ\"ל מאמר הזוהר כל יומא עביד עבידתא, היינו יום ראשון הוא בחי' חסד כמ\"ש יהי אור כו' יום ב' כתיב יהי רקיע ויהי מבדיל בין מים למים בחי' גבורות כו' כיון דאתא יומא שתיתאה ואצטריך למברי אדם אתת אורייתא כו'. והנה דבר זה הפלא שהרי התורה היא בחי' תיקון כנ\"ל ואדם הוא ג\"כ בחי' התכללות כמ\"ש בצלם אלקים עשה את האדם ומפני מה קיטרגה התורה על אדם יותר מעל יום א' וב' שהם בחי' קוין מחולקים חסד בפ\"ע וגבורה בפ\"ע כו', ועל אדם שהוא בחי' תיקון שיותר נעלה מהם כנ\"ל קיטרגה. ועוד שהרי התורה בעצמה היא בחי' התכללות ותיקון איך קיטרגה על האדם שהוא בחי' תיקון כנ\"ל. אך הענין הוא שבאמת אם הי' האדם הולך בדרך הישר לא הי' מקטרגת אך האדם יכול לעשות נגד רצונו וגורם שיומשך השפעה לחיצונים ואם לא הי' האדם בחי' התכללות רק מקו א' לא הי' פוגם רק בקו א' אבל הוא בבחי' התכללות ולכן כשהוא פוגם אזי הפגם הוא ג\"כ בבחי' התכללות ששרשם למעלה מבחי' קוין. אמר לה הקב\"ה וכי למגנא אתקרינא ארך אפים מפני שבחי' ארך אפים הוא מאד נעלה אשר אין שם מגיע פגם ועון כלל כמ\"ש נושא עון ועובר על פשע, ולפעמים נתעורר בחי' ארך אפים כמו ביוכ\"פ ומתקן כל הפגמים בגין דכד ברא קוב\"ה עלמא אתיין כל אתוון לקמי' ועאלו כל חד וחד למפרע עאלת אות תי\"ו כו' כיון"],[1900640355,"דנחית כף מעל כתרא אזדעזעו עילאי ותתאי כו' משום שהוא בחי' כתר ולכן לא נברא בו העולם משום שהוא בחי' ארך אפים לרשעים ולצדיקים ובאות א' ג\"כ לא אברי עלמא משום שא' וכ' הוא ענין אחד ויכול להיות השפעה לחיצונים ג\"כ, וזהו מ\"ש בזוהר בגין דאתקרי בי' ארור שיכולים הי\"א ארורים לקבל ג\"כ יניקה, עד דאיקיים כולא באות בית כו' בי' אשתכלל עלמא כמ\"ש בחכמה יבנה בית בית דבראשית בחי' תיקון כנ\"ל.\n<b>וזהו</b> כי אברהם לא ידענו, שאברהם הוא בחי' חסד כמ\"ש אברהם אוהבי, ויכול להיות מותרי חסדים כמו אברהם שיצא ממנו ישמעאל [כמו גבי נט\"י שכל השפעת חסדים נקרא בשם יד ויש מותרות שהן ציפרנים ולכן לא אשתדל עלן עם שהן בחי' תיקון רק אמר לו ישמעאל יחי' לפניך, שכאשר הוא למטה הוא ישמעאל גשמי אבל הוא רצה להעלותו למעלה בבחי' אלקות מפני שהוא מותרי חסדים שלו, וישראל לא יכירנו ישראל הוא בחי' פנימיות ז\"א דאצילות ויעקב הוא חיצוניות ז\"א דאצילות, ויש להבין שהרי ישראל הוא קו האמצעי בחי' התכללות ומפני מה לא יכירנו, אך הענין הוא שלשון לא יכירנו משמע שמתחלה הכיר אותו ואח\"כ לא יכירנו היינו כמ\"ש בזוהר בגין דכל ברכאן דאצטריך לברכא לבנוי כו' שביק להאי דרגא כמ\"ש וזאת אשר ברך כו' ששבק הברכות לבחי' זאת בחי' מל' דאצילות כי יש שבטים בבחי' אצי' כמ\"ש ששם עלו שבטים שבטי י\"ה י\"ב גב\"א ונק' שבטים דדכורא ויש שבטים בעולם הבריאה ונקרא שבטים דנוק' ונקרא י\"ב בקר שהים עומד עליהם בחי' מל' כמ\"ש כל הנחלים הולכים אל הים כו', וזהו לא יכירנו היינו שלא רצה להשפיל א\"ע בבחי' בריאה יש מאין רק שבק לבחי' מל'"],[1900640362,"שנקרא זאת מפני שלא הכיר שיש בהם ג\"כ בחי' תיקון, הנה כתיב אם יגאלך טוב יגאל ואם לא וגאלתיך אנוכי, טוב הוא בחי' יסוד והתורה ג\"כ נקרא בחי' יסוד, וזהו אם יגאלך טוב היינו שאם יקיימו ישראל תומ\"צ ויבררו ויתקנו הכל יגאל ואם לאו שלא יהיו ראוים לגאולה מצד תומ\"צ שלהם וגאלתיך אנוכי אני הוא בחי' אני ראשון ואני אחרון וכו' שבאנוכי הוא בחי' כתר בחי' אריך אני פי' כנ\"ל שיתעורר ב' בחי' כתר והגם שלא יהי' להם תורה ומצות יגאלם מצד עצמו כנ\"ל וד\"ל."],[1900640020,"(א) <b>להבין</b> שרש ענין חבלי משיח, הנה כתיב כמו הר\"ה תקריב ללד\"ת [תחיל] כו' שהגלות נמשל לבחי' עיבו\"ר והגאולה נמשל לבחי' ליד\"ה כמ\"ש במשיח אני היום ילדתי\"ך כו', וזהו כמו הרה תקריב ללדת כו' כמו המעוברת לסוף ט' חדשים תחיל תזעק בחבל\"י' שנק' חבלי לידה כידוע, כך בסוף זמן הגלות כשמגיע סמוך לגאולה אשר עת ישועה קרובה לבא שהוא בבחי' ליד\"ה שאחר תשלום העיבור שבזמן הגלות אז נק' חבלי ליד\"ה, והוא ענין חבלי משיח שיצירו לישראל ומן המיצר שנק' עת צרה ממנה דוקא יושע כו', והוא סימן לאתחלתא דגאולה כידוע, אך זהו דוקא לאחר גמר ותשלום כל זמן משך העיבור שהוא לסוף ט' חדשים ממש, אבל קודם לזה גם שהיא הרה ויש לה צער הריון אין זה נק' צער לידה כלל כי אין לה חבלי לידה כלל רק דוקא סמוך ללידה ממש אז יאחזוה חבלי לידה כדי שתוליד, והוא הסימן שהגיע זמנה לילד אבל כל זמן שלא יש לה חבלי' עדיין לא תוכל לילד כי לא הגיע זמן הלידה עדיין לפי שלא נשלם עדיין זמן העיבור, ונמצא ענין החבלי' הוא לתועלת הלידה דוקא בהגיע זמנו שהוא לאחר תשלום העיבור והעיבור הוא היפך הלידה שהעיבור הוא עצירת והעלאת וסתימת הולד בבטן אמו למעלה במדור העליון בג\"ח האחרונים דוקא כידוע, ובזמן הלידה מתהפך ויוצ\"א ממדור העליון למטה לבא בגילוי לחוץ דוקא, שזהו היציאה מן המיצר שדוחק ויוצא שלזה צריך חבלי' דוקא והחבלי' הן עושין להיפך מענין הלידה, אבל מחמת זה דוקא נעשה הלידה וכידוע שהחבלי' הוא אחיזת כאב גדול בצדדי הולד למנוע יציאתו שזהו עיקר הכאב כו', אך עי\"ז דוקא נמשך הכח והעוז ללידה ולזה נק' החבלי' משב\"ר כמו היושבת על המשב\"ר כו' וכמ\"ש כי באו בנים עד משב\"ר וכח אין ללידה כו' שזהו כמתמי' על שאין כח ללידה אחר שיש חבלי לידה שנק' משב\"ר כו' והוא בעת צרת ישראל בימי יחזקיהו מלך יהודה שהיצר לו סנחרב מלך אשור כידוע, וכך בענין חבלי משיח סמוך לביאתו דוקא יהי' בחי'"],[1900640034,"חבלי' במלחמו' גוג [ומגוג] שהן היפך הגאולה כו' כמו חבלי לידה, אבל עי\"ז דוקא יהי' כח הגאולה שנק' ליד\"ה, וז\"ש כמו הרה תקריב ללדת תחיל תזעק בחבלי\"ה, וכל זה מפני שהגאולה היפך הגלות שהגלות הוא תכלית ההסתר בבחי' עיבור כמו שאמרו אפי' בשעה שאתה מתמלא עליהם עברה כאשה עוברה כו' והגאולה הוא בחי' לידה, ע\"ז צריך לחבלי' שיעשו את הגאולה שהן עיקר התועלת ללידה כו'.\n<b>אך</b> יש להבין למה התועלת ללידה הוא נעשה בדבר היפוכו שהן החבל\"י' וסמוך ללידה דוקא, וכמו כן בחי' מיצר הגלות והשיעבוד שסמוך לגאולה הוא העושה לבחי' גאולה, וזהו הסימן לאתחלתא דגאולה כמ\"ש עת צרה היא ליעקב וממנ\"ה דוקא יושע כנ\"ל, וכל זה [הוא] פלא גדול לכאור'. אך הנה כל זה יובן בהקדים תחלה ענין א' הידוע בבחי' יסוד שהוא סיומא דגופא שנק' לב\"ר מגופ\"א כי חו\"ג ות\"ת נק' גופא וגם בחי' נו\"ה כליות יועצות שהן המבשלות הזרע כו' בכלל גופא הם רק יסוד נק' לבר מגופא גם שהוא נק' סיומא דגופא כו'. וביאור הדברים ידוע שבחי' יסוד בו ועל ידו הוא בחי' גמר יציאת ההשפעה למקבל בגילוי גמור, וכמ\"ש בזהר בראשית ע\"פ יקוו המים מתחת השמים אל מקום אחד דא יסוד שהוא כניש\"ו דכל נהורין כו' שכל ההמשכו' של המוחי' והמדו' דגופא נמשך ביסוד ומתקבצי' שם לבא לידי גילוי במקבל שהוא בחי' המל', וזהו ותראה היבשה עלמא דאתגליא כידוע, וזהו ג\"כ מ\"ש כי כל בשמים ובארץ דאחיד בשמי' וארעא וידוע שבחי' יסוד נק' הוא שנק' טוב שממנו נמשך אור האצי' בבריאה"],[1900640047,"והאור נק' טו\"ב וגי' דטו\"ב הוא גי' דר\"ת א\"ת ה\"שמים ו\"את ה\"ארץ א\"ה ו\"ה שזהו ענין א' עם מ\"ש כי כל בשמים ובארץ דאחיד כו' וד\"ל, וע\"כ נק' לבר מגופ\"א להיות שעל ידו נמשך השפע לחוץ מן המשפיע עצמו שנק' גופא שהן בחי' המדו' כו'.\n<b>ויובן</b> דבר זה עד\"מ כאשר אדם רוצה לבנות איזה בנין או לעסוק באיזה מו\"מ הנה תחלה יעלה לו תענוג לעשי' זו שאם איננו חפץ ומתענג כלל בבנין או מ[ו] \"מ לא יבא לידי מעשה כלל, ואחר זה נולד לו רצון לעשי' זו והרצון מתלבש בשכל וטעם שמחייבי' ומחזקי' את הרצון ואח\"כ מן השכל והטעם נולדו בלבו מדו' באהבה וחשק לעשות עשי' זו, ואחר שנולדו המדות בלבו יוצאי' לידי גילוי מהבל הלב בדיבור ומעשה עד שיצוה לעשות ועושה בפ\"מ, ומקור המביא לידי גילוי בדו\"מ הוא בהבל הלב שמתקבצי' שם כל המדות והמוחי' עד היותר עליון שהוא התענוג והרצון, ואותו הכח שבהבל הלב להוציא לידי גילוי בדו\"מ הוא הנק' בחי' יסו\"ד שהוא המביא המדו' והמוחי' לידי גילוי בדו\"מ ובחי' דו\"מ נק' בחי' מקבל כידוע, ועיקר ענין דבר זה הוא בענין זיוג גשמי שהטפת זרע שבמוח נתהווה בבחי' התענוג הרוחני שבמוח ויוצא' ונמשכת אח\"כ דרך חוט השדרה עד שמגעת לכליות ובתרין ביעי' לבשל ולחמם הזרע ומתעכבת שם מעט ואח\"כ יוצא' בפי האמה שהוא הנק' בחי' יסוד שממנו ועל ידו נמשך כל המשכו' מ\"ד בגילוי עד שמוליד ולד כשיורה כחץ וכל שאינו יורה כחץ אינו מוליד כידוע, ונמצא שבחי' גמר כל השפע משרשה והתחלתה כמו שהיתה במוח הוא בבחי' יסוד דוקא ששם באה לידי גמר מהעלם לגילוי למקבל כו' ועד שבא [שם] הטפה, לא הי' נק' שפע עדיין למקבל רק היתה בעצם המשפיע עדיין והוא הנק' גופא שהוא המשכת הטפה בחוט השדרה עד הכליות וכו', שגם הן בכלל גופא מאחר שמבשלות הזרע כו' ועדיין לא נפרדת השפע בהם לצאת לחוץ כ\"א בבחי' יסוד דוקא, ואמנם גם שמפני שמביא לידי גילוי למקבל נק' לבר מגופ\"א להפריד השפע לחוץ מגופא ע\"כ הוא בול\"ט לבר מגופא, מ\"מ הוא עצמו מתאחד בגופא ונק' סיומ\"א דגופ\"א שהרי הוא מקבץ בעצמו כל שפע המ\"ד ומתאחד עם גופא ממש רק מחמת יציאת השפע ממנו לחוץ נק' לב\"ר מגופ\"א (וגם בחי' פנימי' יסוד נק' [בחי'] לבר מגופא וחיצוני' יסוד בחי' אור בכלי גם בחי' הכלי נק' סיומ\"א דגופ\"א באחדו' גמור, וזהו ענין יוסף ונח כמ\"ש בזהר פ' נח וכמ\"ש במ\"א)."],[1900640059,"<b>והנמשל</b> מכל זה יובן למעלה בבחי' יסוד העליון שנק' צדיק עליון שם הוא בחי' גמר המשכת השפע מכל האורו' עליוני', דהיינו כל בחי' התענוג ורצון העליון שנמשך בחו\"ב ומחו\"ב למדות חג\"ת עד בחי' נו\"ה כו' בבוא האור והשפע לבחי' יסוד ז\"א הוא המביא לידי גילוי למקבל שהוא בחי' המל' שנק' דו\"מ וכה\"ג [ו] כידוע, ונק' לבר מגופא דז\"א וגם הוא סיומ\"א דגופ\"א בהתאחדו' עם המדו' והמוחי' העליוני' שזהו הנק' כנישו דכל נהורין עילאי' כמ\"ש יקוו המים עליוני' כו' אל מקום אחד כנ\"ל, וז\"ש כי כ\"ל בשמי\"ם ואר\"ץ דאחי\"ד בשמי\"א שמקושר במדות שנק' גופ\"א והוא הנק' שמי\"ם א\"ש ומי\"ם יחד בחי' ת\"ת שכלול מחו\"ג כו', וגם בארעא בחי' המקבל להתקשר שם בבחי' גילוי והבאת השפע מ\"ד למקבל, וע\"כ נק' שלו\"ם כמ\"ש הנני נותן כו' וידעת כי שלו\"ם אהלך כו' בחי' התקשרות השפע במקבל כו' וכמבואר ומובן ממשל הנ\"ל בהשפעת המעשה בנין ומו\"מ שבא לידי פ\"מ מחמת הבל הלב כו', ועיקר המשל בזה הוא מבחי' יסוד בזיוג גשמי שהוא המשכת הטפה לצאת בגילוי למקבל משא\"כ בעודנה בגופה גם בנו\"ה שהן כליות כו' כנ\"ל וד\"ל, וזהו ענין יום הששי ויכולו השמי\"ם כו' שהוא בחי' יסוד כשגמר כל מלאכתו וכמ\"ש וירא אלקי' את כל אשר עש\"ה והנה טו\"ב מא\"ד שהוא en.en.בכלות וגמר כל השפע דוקא בבחי' יסו\"ד שנק' טו\"ב כידוע וד\"ל.\n(ב) <b>ומעתה</b> יש להבין מ\"ש בזהר ע\"פ ולא יכול יוסף להתאפק לכל הנצבי' עליו כו' אלין אינון דקיימין לאתזנא מיני' כו', להיות שאנו רואים דבר פלא ביותר והוא אשר תגבר ותתגדל גודל הלהב והתשוקה בכלות וגמר הדבר דוקא ודוקא סמוך לגמרו אז ניתוסף בו ותתגבר עליו להב התשוקה והחפץ והכוסף שיוגמר הדבר בחיש ומהר דוקא כמו ברצון שהי' לו בבנין או מו\"מ וכה\"ג כנ\"ל, הרי קודם שהוא בא סמוך לגמר השלמת הבנין וכה\"ג עדיין איננו משתוקק בהתלהבות וחשק שיוגמר הבנין אע\"פ שבודאי יש לו תענוג ורצון שמחמתו עוסק בבנין, אבל בהתחלת עסק הבנין או גם באמצעו עד סמוך לגמרו ממש עדיין אין בלבו התלהבות החשק הנפלא שיוגמר בחיש ומהר דוקא אך דוקא סמוך לגמרו ממש כשלא יחסר בו רק דבר האחרון כמו עד\"מ העמדת חלונו' ופתחי' שיוכל לשבת בו מיד אז באותה מעט רגע תכסוף נפשו בלהב התשוקה ביותר שיעמדו"],[1900640071,"מהר החלונות והפתחי' וכה\"ג כדי שיוכל לשבת מיד בביתו אשר לזה הי' טרחו כמה ימים, וזה דבר פלא ביותר למה לא יש לו התשוקה הזאת באמצע עסק הבנין אלא דוקא סמוך לגמרו ממש כו', והלא בעסקו בבנין מתחלתו לא הי' כוונתו רק בשביל הישיבה והדירה שם ולמה נתגבר [התשוקה ו] החשק לעשות במהירות השלמת הבנין בשביל ישיבתו בו בסופו דוקא ולא באמצעו ותחלתו שלא חפץ en.למהר בכל בבנין כו' וד\"ל.\n<b>והנה</b> דבר פלא זה יותר הוא נראה בגמר וכלות השפע ביחוד וזיוג הגשמי אשר דוקא בסוף וגמר שפע המ\"ד ביציאתו בפי האמה אז דוקא תתגבר ותתלהב להב התשוקה והתענוג בהשפעה זו אשר ע\"כ תצא בחיש ומהר ביותר שהוא ענין מה שמורה כחץ כידוע ולא מקודם לכן בהיות הטפת מ\"ד במוח ובחוט השדרה ובכליות ותרין ביעין כו' שלא תתלהב התשוקה אז כ\"כ למהר יציאת השפע למקבל כו', רק בסמוך לגמר ביאה שהוא בכלות הזרע בפי האמה אז נתוסף להב התשוקה והחפץ להזריע במקבל בחיש ומהר כו' כידוע, וראי' לזה ממה שפי' רש\"י בפסוק ותאלצהו שבגמ\"ר ביא\"ה דוקא היתה נשמט\"ת מתחתיו כו' שאז הוא עיקר להב התשוקה והחפץ ע\"כ [י] ורה כחץ כו', ולזה הצער גדול ביותר כשנשמטת מתחתיו שלפי ערך גודל להב התענוג והתשוקה כך ערך גודל הצער בהיפוכו המונע אותו ומבטלו, משא\"כ אם היתה נשמטת מתחתיו מקודם לגמר ביאה כו' שאין הלהב בתשוקה כ\"כ אין הצער אז מן המניעה לזה גדול כ\"כ, וכמ\"ש במ\"א בענין המאמר כד ארי' ואריותא קיימי' ווי למאן דעבר בינייהו כו' וד\"ל.\n<b>ולפי</b> הנראה ומובן מתוך כל הנ\"ל בבחי' יסוד שנק' לב\"ר מגופ\"א כו' שאינו רק כח המביא השפע לחוץ במקבל כו' הי' מהראוי להיות להיפך שבסוף וגמר גילוי השפע תתקרר ותחלש יותר כח התשוקה כו', וכמשל מים הנמשכי' והולכי' באורך גדול כמו מי נהר הנמשך והולך כמה פרסאות וכה\"ג שבודאי תחלת יציאתו יצאו המים ממקורם בכח גדול אך ע\"י הליכתן בהמשך רב נחלש כח ההילוך וההמשכה עד שבסוף הולכי' בנחת או כמו כח היד בזריקה שבהגיע הילוכו ברחוק בסוף יפול וינוח בנחת בלי כח גדול מפני שנתמעט כחו בדרך הילוכו כו' וכידוע, ומכ\"ש אם באמצע הילוך מי הנהר הפסיקו למרוצתו במה שהמשיכוהו אנה ואנה למעלה ולמטה ולצדדי' כמו הילוך עקלתון שעי\"ז נתמעט יותר כח מרוצת המים בשטף כו', וכן בזריקת האבן בכח גדול כשמפסיקי' אותו באמצע הילוכו לצדדים כו' נחלש כח הילוכו בודאי כידוע, וא\"כ הרי יותר יפלא על בחי' כלות השפע בבחי' יסוד למה הוא בהתגברות כח הלהב יותר מכמו שהוא"],[1900640082,"באמצע הילוכו כו', ומכ\"ש כאשר מפסיקי' כח מרוצת השפע מ\"ד בשעת ההילו\"ך בחוט שנתעכב שם ובפרט בכליות כו' כידוע שעי\"ז הי' מהראוי שיחלש כמו בסוף היפך ההתגברות של הלהב כו' וד\"ל.\n<b>אך</b> הנה תחלה יש להקדים בתוס' ביאור בענין ובחי' יסוד למה נק' לבר מגופא כנ\"ל, להיות ידוע שבחי' יסוד הוא בסוף קו האמצעי דת\"י שהדעת כולל חו\"ג והת\"ת כלול מחו\"ג וגם בחי' יסוד מתכלל מחו\"ג שבנו\"ה שהנצח ענף החסד וההוד ענף הג', ונמצא שביסוד הוא בחי' מזיגה והתכללות היותר אחרון שאחר כל המזיגות וההתכללות שבדעת ות\"ת ונו\"ה בפנימי' וחיצוני' כו'. וביאור הדבר הנה מבשרי אחזה כו' בהיות ידוע שבחי' הדעת הוא ממוצע בין ב' מוחין דחו\"ב שהוא תרין עטרין דחו\"ב עטרא דחסד ועטרא דגבורה כו' (ונשים דעתן קלות אין להן רק עטרא דגבורה שמסט' דאימא וחסר להן עטרא דחסד דאבא ע\"כ דעתן קל\"ה קל ה\"א בחסרן ה\"ח דאבא כו'), והדעת כולל לחו\"ג דאו\"א וע\"כ יש בכח הדעת להטות אור השכל לחו\"ג בכמה אופני' ובחי' שונות לפעמי' מטה אור השכל כלפי חסד לזכות באופני' שונים כו' ולפעמים מטהו לדין באופנים שונים כו', ובכל הטיי' יש מזיגה והתכללות שונות בריבוי אופני' שונים ובכולם הוא דבר והיפוכו דוקא ולא שיהי' נוטה רק בענין מדה א' לבד רק חסד או רק דין אלא בכל דבר יש בו עצמו המנגד אליו דוקא דבר והיפוכו, וזהו עיקר ענין ההתכללות והמזיגה כידוע, וכמו ע\"ד דוגמא מ\"ש כי יצר לב האדם רע כו' ע\"כ לא יענש ואעפ\"כ יהיו ימיו ק\"ך כו', דהיינו לא לענשו במבול לשחתו לגמרי וגם לא יאריך ימים כ\"כ והכל משכל וטעם א' זה כי יצר לב כו' שבו כלול דבר והיפוכו זה וד\"ל, וכך יוכל בחי' הדעת להטות השכל בכמה מזיגו' והתכללות מדבר והיפוכו להיותו בחי' המכריע לב' הדיעות דחו\"ג שבשכל בכמה מיני הכרעות שונות כמו משק\"ל הק\"ו של המאזנים"],[1900640093,"ששוק\"ל בהטיו\"ת שונו\"ת כו', וכמו עד\"מ כאשר יעלה בשכל האדם לעסוק באיזה מו\"מ שהוא טוב בעיני שכלו הרי מיד יצא לנגדו שכל וטעם לסתור לשכל וטעם הראשון ועושה להיפך שלא יבחר וירצה בעסק זה שהוא לרעה ולא לטובה, וזהו ע\"י כח הדעת שמטה השכל לב' הפכיי' מנגדי' ואח\"כ חוזר ומטה השכל לבחור בעסק זה באופן אחר וחוזר וסותרו בשכל מנגדו, ועד כמה פעמים מתייש\"ב בדעת\"ו מדבר להיפוכו ממש עד שנגמר בדעתו אופן ובחי' הכרעה ממוצעת עד שתישר בעיניו אופן העסק שיהי' לטובה כו', וכמ\"כ בהשפעת שכל לתלמיד יש בזה ג\"כ בחי' ישוב הדעת במזיגו' חו\"ג מדבר והיפוכו בכמה אופני' ובחי' שונות עד שישפיע לו באופן הממוצע בהכרעה מיוחדת באופן שהוא טוב בעיניו שבזה האופן ישפיע לו כו', להיות ידוע שבכל שפע קודם שישפיע המשפיע למקבל צריך להיות בזה ב' דברים חו\"ג בחי' החסד הוא מה שרוצה להיטיב חסדו עמו כמו שהוא לאמיתתו דהיינו להשפיע לו השכל כמו שהוא אצלו בהרחבה גדולה מאד, אך מפני שיודע צמצום כלי התלמיד המקבל צריך להקטין ולצמצם בעצמו אותו השכל עד שלא יהי' רק כפי ערך צמצום כלי קבלת המקבל כי אם יאמר לו כמו שהוא לא יבין כלל והוא בחי' גבורו' וצמצומי', אמנם חוזר ומתיישב בדעתו לעורר לבחי' החסד כי פן לא יקבל מעוצם הקיצור יותר מדאי וכך חוזר הדבר בדעתו כמה פעמים בצמצום והתפשטות באופנים שונים עד שמוצא בדעתו בחי' ממוצע וממוזג בכי טוב מב' הדברים חו\"ג הללו, שבאופן זה הוא שראוי להשפיע en.בודאי שזה ודאי הוא לטוב לפי ערך קבלת המקבל כו' וד\"ל.\n(ג) <b>והנה</b> כמ\"כ במדות שבלב שנולדי' מן הדעת אחר שבירר הדבר באופן פרטי שכלול מחו\"ג שבשכל מתפשט הדעת אח\"כ במדו' וכולל שם ג\"כ לחו\"ג שבלב שלא ינטה לימין ושמאל רק כפי אופן הטיית הדעת במדות שבשכל דוקא והוא בחי' הת\"ת שמקבל מן הדעת בבחי' קו האמצעי כידוע שהוא בחי' הטיית אופן הכרעת החו\"ג שבמדות לא בחסד יותר מדאי ולא בדין יותר מדאי כו', ועד כמה פעמים מתכלל ומתמזג דבר והיפוכו שהן חו\"ג שבלב עד שבאה בחי' ההכרעה במדות שהוא מדת הת\"ת כידוע, וכן מבחי' המדות שבלב כאשר צריך לבא גילוי השפע למקבל מתייעץ בעצמו איך להשפיע לו דגם שכבר נמדד השיעור במדה ממוצעת במזיגה נכונה בלבו בבחי' ההכרעה שהוא בחי' הת\"ת כנ\"ל, מ\"מ בשעה שצריך להמשיך דבר השפע מעצמותו למקבל שנק' נו\"ה כידוע הרי חוזר מחדש להתיישב מחדש באיכות אופן הילוך וגילוי השפע הזאת למקבל כמו במשל עסק המו\"מ שגם שהוחלט אצלו הכרעת הענין במדות שבשכל ובמדות שבלב מ\"מ כשבא לידי מעשה העסק בפ\"מ מתיישב ומתייעץ תחלה איך ובאיזה אופן יהי' העסק והמעשה משום דבשביל מעשה שהוא עיקר גמר הדבר צריך מחדש להתייעץ באיכות המזיגה הנכונה כי שם הוא העיקר להיותו סוף מעשה כו', כך בעת שצריך להשפיע לתלמיד אז מתייעץ בכי טוב מחדש באיכות ההתכללות מחו\"ג כמו איך וכמה יקצר ואיך וכמה יאריך באופן שיהי' מתקבל במקבל בכי טוב על אופן היותר טוב, וזהו בחי' כליו\"ת יועצו\"ת איך להשפיע וגם"],[1900640104,"שכבר יתייעץ בבחי' הדעת שבחו\"ג שבשכל ובמדות כנ\"ל אין זה רק בהשפע עצמה איך תהי' בכמותה ואיכותה אבל היא עדיין בבחי' מהות שכל לעצמו וגם שמקטינה מפני צמצום כלי המקבל כנ\"ל, אך עדיין אינו רוצה להשפיע בפ\"מ רק שעולה בדעתו כשיצטרך להשפיע ע\"כ מקטינה במהותה, משא\"כ בשעה שצריך להשפיע אותה בפ\"מ בדיבור או במעשה אז אין עיקר העצה במזיגו' והתכללו' רק איך להשפיע ולגלות השפע ולא בגוף השפע כלל שגוף השפע כבר נמדד בדעת ות\"ת כו', וזהו בחי' נו\"ה שנק' כליות יועצו' רק איך להשפיע ולגלות השפע שלזה צריך בחי' מזיגה והתכללות מחדש והוא ג\"כ כלול מדבר והיפוכו כמה פעמי' כנ\"ל בדעת ות\"ת כו' עד שבא לבחי' אופן מיוחד שהוא הראוי להיות בהתגלות השפע למקבל ואותו הדבר שיוצא מאמצעו[ת] מזיגת נו\"ה הוא כמו בחי' ההכרעה שבדעת ות\"ת בעצם השפע כו', וזהו בחי' יסוד שהוא כמו הת\"ת לגבי חו\"ג וכמו הדעת לגבי חו\"ג שבשכל כו' ונמצא בבחי' יסוד הוא סיום כל המזיגות וההתכללות שבדעת ות\"ת ונו\"ה דהיינו שבו לא נשאר רק כדי שפע הנצרך להשפיע למקבל כפי שיוכל שאת ובאופן המצטרך, וכל מה שהי' תחלה בדעת ות\"ת ונו\"ה לא הי' רק עדיין בעצמי' המשפיע במזיגו' שונות איך שיהי' השפע בעצם מהותה ואיך תבא לידי גילוי למקבל, אבל בבחי' יסוד כבר בא המשכ' וגילוי השפע לחוץ מן עצם המשפיע מאחר שבו אינו רק כפי הנצרך למקבל השפע ולא יותר כי אינו רק צורך שפע זולתו הצריך לשיעור קבלת זולתו המקבל בלבד, וכמו בשעה שבא האדם לגמר המעשה דמו\"מ אחר כל העצות שבנפשו ומוחו ולבו איך לעשותו שאז לא נשאר כאן רק דבר א' הנוגע רק לענין גוף המעשה לבד ולא יותר כו', וזהו הטעם שבחי' יסוד נק' לב\"ר מגופ\"א לפי שכל בחי' המזיגו' וההתכללות שבדעת ות\"ת ונו\"ה הכל בכלל גופא הן דהיינו שכל זה הוא עדיין בעצם המשפיע לצורך עצמו ואין זה עדיין רק קבלת המקבל לבד שהוא לבר מגופא מאחר שמתייש\"ב בעצמ\"ו עדיין איך ומה להשפיע כו', אבל בחי' יסוד הרי הוא בחי' המשכה המיוחדת לאחר כל המזיגו' דחו\"ג שבעצם המשפיע רק כדי צורך שפע הטוב וההארה לזולתו המקבל לבד, א\"כ ה\"ז לב\"ר מגופ\"א לצורך זולתו לבד ואעפ\"כ מתאחד עם גופא ונק' סיומ\"א דגופא כי הוא סיום הקו האמצעי דדעת ות\"ת ומהם הוא מקבל וכמ\"ש יקוו המים כו' אל מקום אח\"ד כנ\"ל וד\"ל.\n<b>והנמשל</b> מכל זה יובן למעלה בבחי' יסוד העליון שהוא בחי' צדיק ח\"י עלמין כנ\"ל שהוא עיקר המשפיע לבחי' המל' שנק' בחי' מקור כל המקבלי' שבו כלול מכל בחי' מזיגות והתכללות שונו' דכל אורות העליוני' הכלולי' בקו האמצעי דעת ת\"ת כו' דהיינו כל בחי' אורות ומוחי' עליוני' דחו\"ב דאצי' שכלולי' מחו\"ג ונמשכי' בבחי' הדעת דז\"א, ובחי' הדע\"ת כוללם בכמה אופנים שונים עד שבא לאופן מיוחד והוא בחי' ההכרעה מיוחדת מדבר והיפוכו כנ\"ל במשל וממנו"],[1900640115,"נמשך לבחי' המדו' עליונו' חסד דין כו' ג\"כ בבחי' ההכרעה שבמדות שהוא בחי' ת\"ת דז\"א, ומשם נמשך לבחי' נו\"ה שנק' שחקי\"ם ששוחקי' וטוחנ\"י' כו' שזהו בחי' כליות יועצו\"ת איך להשפיע בכמה מזיגות מדבר והיפוכו עד שנמשך בבחי' יסו\"ד שנק' צדיק עליון, וז\"ש ושחקי' יזלו צדק כו' ושם אין השפע רק לצורך המקבל שהוא בחי' המל' אחר כל המזיגו' וההתכללות דמוחי' ומדו' שבז\"א כו', וע\"כ נק' לבר מגופ\"א דז\"א אע\"פ שמקבל מדעת ות\"ת כו' ונק' סיומא דגופא כנ\"ל וד\"ל.\n(ד) <b>ואחר</b> כל זה יובן מ\"ש בזהר ע\"פ ולא יכול יוסף להתאפק לכל הנצבי' עליו אלין אינון דקיימין לאתזנא מיני' כו', ומבואר למעלה להיות שעיקר להב התשוקה הוא בכלות וגמר שפע הדבר דוקא שהוא בבחי' יסוד שהוא לבר מגופא כנ\"ל, וז\"ש ולא יכול יוסף להתאפק לכל הנצבי' עליו, שיוסף הוא בחי' יסוד צדיק עליון שהוא בבחי' כלות וגמר השפע למקבל ע\"כ לא יכול להתאפק לכל הנצבי' עליו לקבל הימנו, וכמ\"ש אינון דקיימין עלי' לאתזנא מיני' מגודל להב התשוקה שנתרבה דוקא בכלות וגמר השפע של המשפיע כנ\"ל בענין יסוד בזיוג גשמי שלהב התשוקה לגמור בחיש ומהר דוקא אינו רק בכלות השפע דוקא כמ\"ש בפירש\"י בפי' ותאלצהו כו' כנ\"ל. אך הנה מבואר למעלה שזהו דבר פלא גדול לכאורה למה בסוף [ו] גמר דוקא יתגבר להב התשוקה לגמור השפע כו' ולא באמצע כמו בגמר העמדת הבנין שנכספה וגם כלתה נפשו למהר העמדת החלון והפתח כדי שישב מהר ולא באמצע עסקו כו', ולכאורה ממשל מרוצת המים כשמפסיקי' באמצע כנ\"ל מורה היפוך זה כנ\"ל.\n<b>אמנם</b> הענין יובן ע\"פ הנ\"ל בעיקר ענין ובחי' יסוד שהוא לאחר כל המזיגות מדבר והיפוכו בדעת ות\"ת ונו\"ה כליות יועצות כו', הכל בעצמי' המשפיע אז יוצא השפע שהוא לצורך המקבל לבד וזהו בבחי' יסוד כו', אך הנה כל מה שטרח ויגע בבחי' הדעת ות\"ת ונו\"ה להמזיג מזיגו' והתכללות דבר והיפוכו באופני' שונים לא הי' רק בשביל סוף וגמר הדבר האחרון שהוא מה שיוצא לאור התגלות גמור באופן מיוחד רק כפי קבלת המקבל בבחי' יסוד דוקא, ואם לא זה לא הי' מטריח כלל ביגיעות ההתכללות מדבר והיפוכו שכל היפך מייג\"ע לפי שמונע מהות השפע כמו בדעת שמנגד מהות השפע לצמצם לגמרי רק שאח\"כ חוזר ומטה כלפי חסד במהות השפע, וכן בת\"ת בחי' הגבורה מונע לגמרי וחוזר ומטה כלפי חסד רק שהוא בבחי' ההכרעה כו', וכן במזיגה שלצורך הבאת השפע למקבל בבחי' נו\"ה מצמצם ומונע בתחלה וחוזר ומטה כלפי חסד כו' עד כמה פעמי' עד שמה שיוצא השפע למקבל הרי זהו העיקר שכל הכונה גם במנגדי'"],[1900640126,"שבדעת ות\"ת ונו\"ה להיות השפע יוצא ברור רק כפי הצורך למקבל דוקא (בל\"א אושגישטיליערעט כו'), ולפי שהי' טורח ויגיעה כ\"כ במונעי' ומנגדי' רבים רק למען הביא השפע לידי גמר באופן הטוב למקבל דוקא לכך בהגיע השפע סמוך לגמרי דוקא אז יתלהב ביותר התשוקה שתבא לידי גמר במקבל השפע, כי לזאת נשא את נפשו נושא משך הזרע בכמה טרחות ויגיעות במנגדי' והפכיי', ואם לא הי' בחי' מזיגו' והתכללו' מדבר והיפוכו כ\"כ בדעת ות\"ת ונו\"ה עד בוא השפע בגמר בבחי' יסוד לא הי' להב התשוקה כ\"כ בבחי' יסוד לגמור בחיש ומהר כ\"כ כנ\"ל, רק דוקא ע\"י שהי' כמה מונע\"י' ומנגד\"י' רק בשביל סוף וגמר שיהא עצהיו\"ט כו' ע\"כ לבסוף כשגמ\"ר בכ\"י טו\"ב כו' אז תתגבר [כח] התשוקה לגמור הדבר בחיש ומהר למקבל כו', וכמו עד\"מ כשהמים הולכי' ברחבה ובמרוצה ומעכבי' אותה במסך בכמה מקומו' באופני' שונים בכדי שיומשך במקום מיוחד, הרי כשמסירי' המסך באותו המקום המיוחד יוצאי' בשטף ורעש גדול, כי עיכובי' שונים שעיכבוה בהילוכן הוא הגורם השטף בכלות שפע המים במקום נקב מיוחד כמו בחללי בנין הגשר וכידוע, וכך בזיווג גשמי שהטפה מתעכ\"ב במוח ובחו\"ט [השדרה] ומכ\"ש בתרין ביעין לבשל כו', אשר כל זה הוא רק למען הביא שפע זרע שתהי' ראוי' למקבל להוליד ולד, אשר ע\"כ בכלות הטפה ביסוד שם הוא דוקא להב התשוקה ביותר לכך יוצאת בחיש ומהר במרוצה גדולה אשר מורה כחץ ואז ראוי' להוליד וא\"ל לא תוליד כו' (וכמו החץ כל מה שיעכבוה יותר בנסוג אחור כלפי גופו או למטה בארץ כן יהי' ערך הוראת החץ בגובה ולמרחוק יותר כו'), וכן בענין השלמת הבנין שתכסוף וגם כלתה נפשו להעמדת החלונות והפתחי' כדי שישב מהר כו', כי לזאת נשא את נפשו ביגיעות העסק בבחי' ישוב הדעת דבר והיפוכו איך לעשות הבנין כך ולא כך כו', ע\"כ לא הי' עיקר הלהב באמצע העסק כלל רק בסמוך לגמרו דוקא כנ\"ל מטעם הנ\"ל. ובזה מתורץ הקושיא דלעיל ממרוצת המים שבדרך עקלתון יחלש כו' דאדרבה ממניעות ועיכובי' שיחוש מחמתן הוא הנותן כח הלהב הגדול כשיופסקו המונעי' ויתגלה השפע לחוץ שלזה הי' עיקר המכוון בתחלה כו' וכמו חום השמש המכה בארץ וכה\"ג וד\"ל. והנמשל מכל זה יובן למעלה במ\"ש ולא יכול יוסף להתאפק לכל הנצבי' עליו דוקא בגמר וסוף ההשפעה לכל הנצבי' עליו שאז לא נשאר רק כפי השפע של המקבל שם דוקא מתגבר להב התשוקה הגדולה לגמו\"ר השפעתו וע\"כ לא יכול להתאפק כלל כו' וד\"ל.\n(ה) <b>ובכל</b> זה יובן ענין אחד והוא אשר בכל מקום בדברי רז\"ל נז' בשיעור המלאכי' לשון מהלך ת\"ק שנה למה דוקא ת\"ק שנה ולא ת\"ר שנה כו', אך הענין הוא לפי שאין בנבראי' רק התכללות מה' מדריגו' שעד בחי' יסוד ולא"],[1900640137,"עד בכלל דהיינו רק מבחי' חג\"ת נו\"ה שהן ה' בחי' בלבד ע\"כ שיעורם מהלך ת\"ק שנה ולא ת\"ר שאם הי' כלול בהן גם בחי' יסוד הי' מהלך ת\"ר, והטעם הוא לפי שלא נשתלשל בהם בחי' יסוד שהוא בחי' הו' אע\"פ שלכאורה הרי כל עיקר ההשפעה הוא מבחי' יסוד שהוא המביא לידי גילוי כל מה שבמדות עד נו\"ה כנ\"ל מ\"מ הוא עצמו אינו מן החשבון שהרי בחי' המדו' והמוחי' הן הן עיקר מהות השפע עצמה רק שבחי' יסוד הוא הכח שמביאם לידי גילוי באופן מיוחד שאחר כל המזיגות מדבר והיפוכו כנ\"ל ונק' כניש\"ו דכל נהורי\"ן שכל האורות מתקבצים בו כמ\"ש אל מקום אחד כו' והן בכלל ה\"ח דנש\"ב ובפרט הן ה' חסדי' חסד שבחסד חסד שבגבורה חסד שבת\"ת עד חסד שבהוד, וה\"ח הללו מתכנשי' ביסוד וכלול מכולם והוא ענין ת\"ק שנ\"ה דוקא וכמ\"ש בזהר משום דבינה עד הוד דז\"א אתפשט' כו' וד\"ל, וזהו מפני שבחי' יסוד נק' לב\"ר מגופא ואינו נחשב בכלל גופא שהוא חג\"ת ונו\"ה לבד ושרש הנבראי' הוא מבחי' גופא דמלכא כו'. אך עדיין יש להבין למה לא אמרו לשון זה רק במלאכי' נבראי' בע\"ג דוקא ולא באצי' שגם שם אין העיקר רק ה' בחי' דחג\"ת נו\"ה ויסוד נק' לבר מגופא כו', ועוד היא גופא יש להבין הטעם למה לא נמשך בנבראי' גם מבחי' יסוד עצמו ויהי' שיעורם ת\"ר שנה (ובפרט בנשמו' שנמשכו מאור זרוע לצדיק עליון בחי' יסוד למה לא יהי' בה מבחי' יסוד ג\"כ והרי כמו נשמת יוסף שנק' צדיק עליון הי' בו מבחי' יסוד (וכן נח ופנחס כו') וכתיב אלה תולדות יעקב יוסף שהי' דומה לא[ביו] כו').\n<b>אך</b> הענין יובן בהקדים תחלה בבחי' יסוד דגם שאינו רק כנישו דכל נהורי\"ן כנ\"ל מ\"מ הרי יש בו יתרון מעלה מצד אחר והוא לפי שממנו נמשך בחי' עצמיו' של השפע דוקא דהיינו לאחר שנבררה בכל ריבוי אופני המזיגו' וההתכללות בבחי' גופא בדעת ות\"ת ונו\"ה מדבר והיפוכו המנגדו וסותרו אז יצא לאור דבר שפע הברור שאין לו מנגד עוד והוא עצם השפע ממש, שהרי בבחי' הדעת הי' שוקל הדבר מדבר והיפוכו כמה פעמים עד שבא לדבר ברור, כמו ב' דיינים זה אוסר וזה מתיר כשבא המכריע אז יוכל הדבר [לבוא] לידי פסק הלכה למעשה, ובלתי ההכרעה א\"א לפסוק הלכה למעשה לפי שבשביל מעשה שהוא כמו השפע לזולתו צריך בהכרח להיות באופן אחד ברור ולא דבר שקול כו', וכך הוא בבחי' ההכרעה במדו' בבחי' הת\"ת כנ\"ל שהת\"ת הוא ההכרעה באופן א' מיוחד, וכך הוא בבירור ה\"ג בנו\"ה כליות יועצות איך להשפיע עדיין שקול שם בבחי' צמצום והתפשטות עד שבבחי' יסוד יוצא שם הדבר שפע ברור בלי נטי' לימין ושמאל"],[1900640147,"דהיינו כמו שהוא בבחי' עצמי' המשפיע ולכך יוליד בדומ\"ה לו דוקא כו', וכל מה שהי' מזיגות והתכללות בהכרעות שבדעת שבת\"ת ונו\"ה הוא רק בשביל סוף וגמר השפע למקבל בבחי' יסוד עד\"מ הנ\"ל בדייני' שכל יגיעתם לשקול הדבר עד שבאי' לבחי' ההכרעה אין זה רק בשביל שצריכי' להביא הדבר לידי פסק הלכה למעשה דוקא ואם לא שהם צריכי' להשפיע הדבר הלכה לענין מעשה לא היו מייגעי' בשיקול הדבר כלל, וכנ\"ל שלזה הטעם עיקר להב התשוקה הוא בכלות וגמר השפע בבחי' יסוד כו' וד\"ל, ולהיות כן הרי בבחי' יסוד נמשך השפע כמו שהוא בעצם וז\"ש כל אש\"ר לאי\"ש יתן כו' וכן ביונתן ודוד כתיב ויתפשט ממעילו עד כו' שהמשפיע נותן כל אשר לו למקבל, והגם שלכאורה נהפוך הוא שהרי לא נשאר ביסוד רק הצריך לקבלת המקבל כנ\"ל וכל ההתכללות אופני' שונים מדבר המנגד נשאר בעצמו כמשל פסק ההלכה למעשה שאינו או' רק מה ששייך למעשה לבד כו', מ\"מ הרי הוא בחי' העצמ\"י' של השפע כמו שהוא רק שהוא בא אחר כל הבירור\"י' מכל המנגד\"י' בתחלה כנ\"ל במשל המו\"מ שבתחלה ישתף דוקא המנגד לסתור הדבר בשכל וכן במדות ובנו\"ה כו' עד שאח\"כ כשנגמר לעסוק במו\"מ הרי זהו פנימי' ועצמי' רצונ\"ו כו' וד\"ל, ונמצא נותן המשפיע בחי' העצמי' שלו, ואמנם כלולי' בו מכל ההפכי' שבשכל ומדות כו' וע\"כ יוליד בדומ\"ה לו, אבל הנה הדבר הנולד הוא מהות ויש בפ\"ע בדומה למשפיע כמו הולד שנולד מן הטפה שהוא יש בפ\"ע ממש כו', לפי שזהו עצמו הגורם להיות בחי' יש ומהות בפ\"ע מאחר שנמשך מבחי' עצמי\"ו' של המשפיע כבן לגבי האב (וז\"ש במשיח בני אני היום ילדתי\"ך ויהי' במהות ויש בפ\"ע דומה לאור האלקי ממש ולא בבחי' פירוד ח\"ו אדרבה בתכלית הביטול כמ\"ש והריחו ביראת ה' כו', אבל בחי' היש שלו הוא בדומה לבחי' יש האמיתי דבחי' העצמי\"ו' וכמ\"ש ליעקב אתה יחיד בתחתוני' כו' וכמ\"ש במ\"א, וזהו ההפרש בדרך פרט בין נשמו' למלאכי' שהנשמות שרשן הוא מבחי' יסוד כמ\"ש אור זרוע לצדיק עליון כו' משא\"כ המלאכים, ע\"כ המלאכי' דוקא ת\"ק שנים ולא הנשמות (ומ\"ש הנפילי' היו בארץ שהן מבחי' פסולת מ\"ד דיסוד העליון נעשי' נפרד גמור כמ\"ש במ\"א שאם הי' הארת בחי' יסוד במלאכי' הי' גם הן בבחי' יש נפרד משא\"כ בנשמות וד\"ל)."],[1900640156,"(ו) <b>ומעתה</b> יובן הטעם אשר לא בא בחי' יסוד בהשתלשלות בנבראי' בע\"ג כמו המלאכי' כנ\"ל, דהנה כתיב וצבא השמים לך משתחוי' כו' וכתיב והחיות רצוא ושוב כו' הרי יש במלאכי' עליוני' בחי' ביטול במציאו' כו', וזהו מצד ה' בחי' ומדריגו' שבבחי' גופא הנ\"ל אבל אם הי' מאיר בהן מבחי' יסוד ששם השפע בבחי' עצמי\"ו' והוא נותן כולו למקבל כמו שהוא במשפיע ולבר מגופא, הרי לא נמלט מב' פנים או שהי' הנברא בבחי' אלקו' ממש כי כח המוליד יוליד בדומה לו ואע\"פ שהי' בבחי' יש בפ\"ע אבל הי' בבחי' אלקו' ממש (כמו דוגמת הנשמו' שנק' אד\"ם אדמ\"ה לעליון כנ\"ל בבחי' משיח) או שהי' בבחי' נפרד גמור בלי ביטול כלל (כמו הנפילי' שהיו בארץ כנ\"ל) מאחר שהוא לבר מגופא דהיינו רק לבחי' קבלת המקבל וניתן הכל למקבל, הרי נפרד השפע מן המשפיע כאדם שנתן כל אשר לו לזולתו שנפרד הדבר מעצמו לגמרי מב' טעמי' הא' במה שנתן לזולתו והפרידה מעצמו, והב' במה שנתן כולו ולא השאיר לעצמו חלק בו שאם הי' אחוז וקשור הדבר בעצמו ג\"כ ולא הי' נותן כולו לזולתו עדיין לא הי' הדבר נפרד הימנו לגמרי כי יש בו בחי' ביטול במקצתו אל הנותן כו', וכך בבחי' שפע דיסוד הרי נתן הכל למקבל ולא השאיר לעצמו חלק בו כמ\"ש כל אשר לאיש כו', והוא לבר מגופא שנתן למקבל הרי יוכל להיות בחי' נפרד גמור או שיהי' בבחי' אלקו' ממש מאחר שהוא בחי' העצמיו' של המשפיע כנ\"ל, אבל במלאכי' יש ב' הפכי' שהן בבחי' יש והן בטלי' לאין שזהו בחי' ממוצע בין נפרד גמור לתכלית הביטול דאין האלקי' שזה א\"א להיות מבחי' יסוד כ\"א מבחי' ה\"ח שבגופא ששם הוא במזיגו' דחו\"ג צמצום והתפשטו\"ת והכל בבחי' עצמי' עדיין, ועכ\"ז הוא לצורך גילוי השפע למקבל דוקא כנ\"ל בבחי' הדעת ות\"ת ונו\"ה כו', ומזה בא סיבת ביטול הי\"ש לאי\"ן במלאכ\"י' שהן יש ובטלי' לאין כו', ולזה א' במלאכי' דוקא ת\"ק שנה ולא ת\"ר [שנה] משא\"כ בנשמות וכן באצי' דאיהו וחיוהי חד כו' בבחי' עצמי\"ו' דאא\"ס שבק\"ו כו' ולא נז' לשון זה דת\"ק שנה רק בג' עולמו' הנפרדי' יש מאין שהן בחי' המלאכי' דבי\"ע דוקא מטעם הנ\"ל וד\"ל.\n(ז) <b>ואחר</b> כל הנ\"ל יובן ג\"כ בשרש ענין חבלי משיח הנ\"ל, דהנה ידוע בשרש ענין בחי' משיח שהוא בחי' לידת כללו' נשמות ישראל כמ\"ש אספרה כו' בנ\"י היו\"ם ילדתי\"ך שהוא בחי' ב\"ן לזו\"נ דאצי' ובחי' מל' דאצי' היא אימא תתאה המולדת אותו כמ\"ש בזהר בלק ע\"פ כי מראש צורים [אראנו] כו' ולזה אמרו"],[1900640163,"דבכל ט\"ב נולד משיח כו', וז\"ש כמו הר\"ה תקריב ללד\"ת שבזמן הגלות נק' עיבו\"ר דכללו' נ\"י, וביאת משיח נק' בחי' ליד\"ה כנ\"ל וכמארז\"ל עד שיכלו כל הנשמו' שבאוצר ששמו גוף כו' שהן כל נשמות ישראל שנולדי' מבחי' המל' שנק' גוף, כמו שאמרו למה האשה דומה לאוצר רחב מלמטה [ו] קצר מלמעלה כו' וכאשר יושלם זמן העיבור דכנ\"י בבטן המל' אז יולד משיח, וז\"ש אנ\"י היום ילדתי\"ך כו' וקודם וסמוך ללידה יש צירי' וחבלי לידה כנ\"ל והוא דוחק הגלות והשיעבוד כמו במלחמת גוג לפני בוא יום הגדול כו' (וכמו קדרותא דצפרא שקודם וסמוך להארת אור השחר דוקא), וכמ\"ש [ו] עת צר\"ה [היא] ליעקב וממנ\"ה דוקא יושע שהחבלי' המונעי' הלידה הוא הגורמי' תוס' הכח ללידה כנ\"ל באריכות, שהעיבור הוא סתימות הולד במדור העליון ומתהפך ויוצא כו', שהלידה נעשית מדבר היפוכו ובסמוך לה דוקא כו'.\n<b>ויובן</b> כל זה ע\"ד כל הנ\"ל בבחי' יסוד דדכורא שהוא בחי' יסוד ז\"א אור הזרוע לצדי\"ק עליו\"ן להמשיך בחי' מ\"ד בנוקבא דז\"א להוליד כללו' נ\"י בבטן המל', שהשפע מ\"ד הולך בבחי' אור ישר מלמעלה למטה מן המוח אל החוט כו' עד בחי' יסוד ואין ההילוך הזה נמשך והולך מראשו לסופו בלתי עיכובי' ומונעי' באמצען אלא במוח מתעכב תחלה עד שנעשי' טפה גשמיי' בחוט, וכן בחוט כו' עד כליות יועצות בתרין ביעין לבשל כו', וכנ\"ל שהוא ענין המזיגו' והתכללות דחו\"ג למנוע הדבר שפע ולחזור ולהמשיכו בתחלה במוחי' שהוא בחי' הדעת ואח\"כ במדות, ואח\"כ בנו\"ה ששם עיקר העיכוב בהיות שהוא קרוב לגמר וסוף להביא השפע למקבל כמו עד\"מ כשצריך הדבר לידי מעשה בפ\"מ ששם יותר מתעכב ושוקל בדבר יותר לדין והיפוכו כו', אך זה עצמו הוא הנותן כח ועוז להיות יציאת השפע אח\"כ המצטרך למקבל אחר הבירור מכל המנגדי' כו' בכח ומהירות גדולה, ולכך עיקר להב התשוקה להשפיע הוא לבסוף דוקא כמבואר בכל הנ\"ל, וכך ממש יובן בבחי' יסוד דנוק' בחי' המקבל השפע דמ\"ד דדכורא שהוא בבחי' אור חוזר כי הנה מיד שקיבלה המ\"ד ביסוד שלה דהיינו בחי' קליט\"ה נק' עיבו\"ר שהוא נכלל ומתעלם ברחם הנוק' בהעלם בתוכה ובחי' המ\"ן מקיפו כו', ובג\"ח השניי' חוזר"],[1900640170,"ומתעלם העלם אחר העלם הראשון למעלה בסתימות יותר ראשו בין ברכיו כו' עד סוף ג\"ח האחרוני' הוא במדור העליון בתכלית העיכוב והעצירות יותר בבטן כו' כידוע, וה\"ז כמו בבחי' א\"י שבירידת השפע מן המשפיע אל המקבל מתעכב בהילוכו בהיפוכו המנגדו וכל שיורד יותר למטה יותר מתעכב עד שבכליו' כו' מתעכב יותר מפני שצריך לבא בבחי' יסוד, ומזה הוא הכח בהילוך המ\"ד בחיש ומהר להיות מורה כחץ וא\"ל לא הי' מוליד כנ\"ל, כך בקבלת השפע דמקבל שהוא עולה בבחי' א\"ח למעלה בהעלם אחר העלם למעלה בסתימות והתכללו' יותר עד סוף ט\"ח כשהוא במדור העליון דוקא מתהפך שם ויוצא למטה מטה ומתעכב שם ע\"י צירי' וחבלי' המונעי' והיינו בסוף ט\"ח דוקא מפני שצריך להיות בחי' הלידה בגילוי יש בפ\"ע כמו שמתעכב בנו\"ה במשפיע כשצריך להיות תולד\"ה מבחי' המ\"ד במקבל כו' ואז יש צירי' וחבלי' המונעי' ומעכבי' את הלידה ונק' צירי' ודלתו' שסוגרי' את הרחם בכדי שמן הסגירה הזאת יבא דוקא סיבת הפתיחה להוליד כנ\"ל, דכח ללידה בא דוקא מן החבלי' והצירי' והחבלי' בנוק' הן כמו דוגמת הכליות בבחי' נו\"ה דדכורא והן אברי' הנוספי' באשה מבאיש לצורך הלידה כידוע בענין בינה יתירה שבאשה כו', וכמשלים הנ\"ל בעוסק בבנין שבגמר מלאכתו נתוסף כח הלהב וכן בגמר ביאה כו', כך בסמוך לגמר הלידה דוקא שאז יגבר הכח ללידה לבא לידי גמר בבחי' יסוד דנוק' צריך להיות תחלה חבל\"י ליד\"ה (והוא כמו הצער הגדול שיש לאדם בסוף מלאכתו למה לא תגמר מהר כו' והוא הגורם להיות גמרו בפ\"מ), וכך יובן בבחי' לידה העליונה דכללו' נ\"י בהיותם כלולי' בבטן המל' למעלה כל זמן הגלות שנק' עיבו\"ר כנ\"ל ודוקא לבסוף וסמוך לבחי' הלידה שהוא זמן ביאת משיח אז תחיל תזעק בחבלי\"ה שהן צרות ישראל שממנה יושעו דוקא והוא הסימן לאתחלתא דגאולה דוקא כנ\"ל (ומ\"ד אין חבלי משיח כו' משום שאין החבלי' רק מסיבת עה\"ד טו\"ר כמ\"ש בזוהר בענין ע' קלין שהוא מ\"ש קול ה' יחולל אילו\"ת דאיל\"ה רחמ\"ה צ\"ר ונשך לה נחש כו' ולעתיד יבורר הכל ואז נא' בטרם תקר\"א ואני אענה כו' וכמו שא' לא המצריו\"ת כעבריו\"ת בטרם תבא המיילד\"ת וילד\"ו כו', וע\"ד שאמרו לעתיד עתיד\"ה אש\"ה שתל\"ד בכל\nיו\"ם כמו לפני חטא עה\"ד שעלו למטה ב' כו' כמ\"ש במ\"א וד\"ל)."],[1900640021,"יפה שעה א' בתשובה ומע\"ט כו', ולהבין זה י\"ל מ\"ש ראשית גוים עמלק ואחריתו עדי אובד. כי הנה ידוע שהתו' בחי' נצחיות וישנה בכל דור ובכל זמן ובכל נפש ונפש [מישראל] . הנה ז' עממין הן שבעה מדות רעות, כנעני הוא בחי' אהבה ותשוקה בבחי' מסחר הבלי הזמן מל' כנעני' נכבדי ארץ וכנען בידו מאזני מרמה, עד ששוכח על ה' אחד לאמר כחי ועוצם ידי כו', הוא בחי' חסד דקליפה. פריזי הוא מלשון פרזות תשב בבחי' פריקות עול מ\"ש לכל אשר ישאלנו לבבו בלי גדר ועול. וכן חוי הוא ארס נחש הקדמוני. ומ\"מ הז' מדות הנ\"ל אינם רע גמור כי חיות ומקור המדות וקיומם הוא בחי' עמלק ונק' ראש דשבעה עממין וכשם שבלי ראש מסתלק החיות ככה המדות יכולים להתהפך לטוב בלי הדעת שהוא קליפת עמלק, וכמא' המן מן התורה מנין שנא' המן העץ הזה שהוא עץ הדעת טו\"ר, וזהו ראשית גוים עמלק ראש ומקור לכל הגוים כידוע. והנה בבחי' עמלק יש ג\"כ ציור אדם ראש ומדות וכמשי\"ת, ואחריתו עדי אובד שלא יתברר כלל עד שיבוער רוח הטומאה כו' (וכידוע הפלוגתא ח\"א נושא עון וח\"א כובש עון, ואלו ואלו דא\"ח נושא הוא על התפעלות המדה בעצמה שאינו רע גמור כי יכולה להתהפך אותה התאוה ממש לאלקות, וכובש הוא על התלבשות המדה במחדו\"מ שהוא רע גמור וכובשה במצולות ים וכמ\"ש ותשליך במצולות ים)."],[1900640035,"<b>ולהבין</b> כ\"ז הנה כל מדה הוא מדידת הנפש בחסד או בגבורה והוא רק זיו והארה מן הנפש, וידוע שזיו וגילוי הוא רק ההמשכה בבחי' אין שתשתנה לפי ערך הכלים אבל אין בה שום המשכות ממהות ועצמות הנפש, כמו\"כ כל מדה הוא בחי' זיו וגוון הנפש. ולכן כח המתאוה שבמדות תיכלל בבחי' הקדושה ממש, כידוע מכח המתאוה למאכלים ערבים בשבת אותה התאוה ממש נכללת בתכלית הקדושה וכמ\"ש וקראת לשבת עונג במה מענגו כו' ואומר ע\"ז דא היא סעודתא דעתיקא קדישא ממש, וכמ\"ש פרש חגיכם ולא פרש שבתכם. אלא עיקר ומעמד המדות שלא תשתנה הוא בחי' הדעת דקליפה שהוא המשכת מהו\"ע הנפש ממש כמ\"ש גם בלא דעת נפש לא טוב ומתרגם דלא ארגיש נפשי', כי הדעת הוא הרגשת החיות (בל\"א ער וויל הערין ווי ער לעבט) והוא בחי' עומק העונג שבתאווה והנחת הנפש ברצונו להרגיש העונג בתשוקה מורגשת הוא בחי' הדעת ועושה התמשכות הנפש בתאוה זו. כמו שאנו רואים בחוש שגם בקטן ימצא התפעלות המדות לכסף וזהב ומ\"מ אפשר שיסיח דעתו מזה ע\"י פיצוי [בדברי] הגדולים עד שישכח על תאוותו, משא\"כ בגדול שמרגיש שזה נוגע לעצמות החיות א\"א לשנות [תאוותו ו] דעתו כי בהרגשה נמשך עצם הנפש בדבר האהוב לו ותדבק שם, ואם גם שיסיח דעתו ויתלבש במח' ובלבושים שונים מ\"מ כ\"ז שהנפש בחיים חיותה היא קשורה בדבר ההוא. והסימן לזה הוא עוצם ההרגשה בשעת מעשה בחמימות יתירה והוא מחמת שתשוקתו להרגיש חיותו, וכל מה שפועל ועושה בהתפעלות וחמימות נתוסף בו חיות ומחמת זה א\"א לו להתפשט מתאותו זאת כי א\"א לו להניח חיותו וד\"ל. וכמו שאנו רואים שגם בצדיקי' נמצאו כללות המדות כמו אכילה ושתי' ומשגל ומולידים בנים ואין לך אדם שאינו אוהב א\"ע ומ\"מ הם מופשטים בתכלית מכל הבלי העולם ממש וחבוקי' ודבוקי' בא\"ח ממש גם בעודם בגופם ממש, אין זה אלא מחמת שעיקר רצונם וחפצם להכלל במקור החיים כמ\"ש כי הוא חייך ממש ותשוקתם להרגיש חיותם בהתפעלות עצומה וזה נק' דעת דקדושה ע\"כ נמשך כל מהות נפשם לדבקה בו ית', וגם שא\"א להם"],[1900640048,"להיות בגופם בלתי מזון ולבוש וכל מיני מציאות, אך התלבשותם בזה הוא רק [דרך] זיו וגוון לבד ומחמת זה כל תאות העולם הוא בבחי' קרירות בהם ודרך טפל en.en.ואגב לבד מחמת שרצון ה' וחפצו לבד הוא העיקר (וכמאמר בע\"כ אתה חי).\n<b>ולהבין</b> בדרך פרט איך שכל מדה עיקר חיותה וקיומה הוא הדעת דוקא הוא כך, בחי' חסד דקליפה הוא עיקר המתאוה כמו לאכול ולשתות ואנו רואים שזה אוכל וזה אוכל ומ\"מ אנו רואים הפרש גדול ביניהם והוא זה שלאחד אם יחסר לו המזון בשר ודגים מרגילותו נוגע לו עד הנפש עד שנחלה וכ\"ש כשיחסר לו לחם כמו בתענית וכדומה, וכמה בנ\"א שאינו נוגע להם הדבר ואוכל גם דברים שאינם ערבים ומתוקים כלל וגם בתענית אינו נוגע כ\"כ וגם לא יכשל במאכלות אסורות ח\"ו, ויש בנ\"א שא\"א להם למשול ברוחם עד שיוכשל ח\"ו במאכלות אסורות. ועיקר ההפרש ביניהם הוא מחמת העמקת הדעת שהוא הרגשת נפשו בחיותו ועושה התאוה לאכילה כלי שירגיש בזה העונג ומחמת זה תמשך הנפש בזה ותדבק בזה ומחמת זה א\"א לו להניח עצמותו עד שיכשול בה ח\"ו (בל\"א דעם לעבין קען מען דאך ניט לאזין). וכל מה שתמשך הדעת באותה התאוה יותר תדבק בה הנפש יותר ומחמת זה יש חלוקי מדריגות רבות בזה, אבל אם דעתו והתקשרותו בזה מטעם שהוא ית' המחי' ונמשך זיו וחיות ממנו ממוצא פי ה' שבמאכל, לא יגיע כלל לנפשו העדר עונג המאכל ואפילו תענית, כי מוצא פי ה' מחייהו ומחמת זה אינו סותר לו התענית וכש\"כ שבתועבת ה' כמו במאכלות אסורות תמאס נפשו. וכמו\"כ בתאוות הממון אנו רואים חלוקים רבים ומינים שונים מאחד לחבירו שכמה בנ\"א עוסקי' במו\"מ עד שתדבק נפשו ממש שאין לו פנאי להפנות עצמו לקבוע לו עיתים לתורה, וגם בשעת התפילה הוא מלא מח\"ז מן העסק שמבלבלים אותו, ויש כמה בנ\"א היפך זה שבשעת עסקיו הוא ג\"כ אינו מוטרד ואין זה אלא שלזה יש בו דעת להרגיש חיותו וממציא לנפשו כלי שירגיש בה תאוות הממון ומחמת זה תתמשך הנפש ותדבק בה ובמקום הנפש שם נגררים לבושי הנפש כמו המח' ודיבור ומחמת זה גם בעודנו פנוי וחושב או מדבר ד\"ת או תפילה מ\"מ הנפש נשארה שם ואינו כאן כ\"א זיו והארה מן הנפש. והסימן לזה"],[1900640060,"ההתפעלות והחמימות בזה. משא\"כ למי שדעתו אינו בזה ונמצא בעסקיו רק זיו הנפש ולבושי' ואינו רק טפל ואגב בשביל שימצא מזון לנפשו לעבודת ה', וע\"כ התורה והתפילה הוא העיקר. ומחמת זה יש שינוים רבים בקימוץ ופיזור לצדקה מטעם זה ממש שמי שיש בו ההרגשה ביותר באותה התאוה אז הממון הוא נוגע לנפשו וא\"א לו להניח נפשו שבכל פרוטה ופרוטה הוא מרגיש תוספות חיות ובהעדרו מרגיש הסתלקות חיותו ממש, משא\"כ למי שהמו\"מ הוא טפל וע\"כ עיקר המכוון והחיות הוא לעשות צדקה וחסד וד\"ל. וכמו\"כ בבחי' תאוות המשגל כולם מולידים מדור דור וא\"א להוליד באבר מת מ\"מ אנו רואים חלוקי מדריגות רבות בזה שיש בנ\"א שבהתהוות איזה סיבה שיחסר לו תאוותו מזה יבא לידי מקרה רע ח\"ו בלילה, ויש שנוגע לו הדבר יותר עד שנופל בעבירות חמורות ח\"ו, והרבה בנ\"א הגם שיש להם החוש מ\"מ ישלוט ברוחו עד שאינו נוגע לו הדבר כלל, והכל מסיבת הדעת כנ\"ל שמי שיש לו חוש ההרגש חיי נפשו ועושה בנפשו התאווה זו [חיותו] מחמת שיש בה תענוג מורגש מאד הוא כלי לחיותו ומחמת זה נדבקה נפשו וקשורה בחבלי עבותות תאותו ובהעדרה תחסר אור וחיות נפשו. ומטעם זה ארז\"ל אין קישוי אלא לדעת הנ\"ל. ורוב הטומאה הנ\"ל הוא בלילה בשינתו שעולים ונכללים גילוי הארת הנפש בעצמותה ונשארה הנפש בעצמה אזי יבא בעצמו לידי זה וד\"ל. ומטעם זה הרהורי עבירה קשים מהעבירה [עצמה] כי העבירה גופא הוא התפעלות הנפש בהיות לפניו המעשה אבל ההרהור הלא אינו המעשה לפניו ומדוע מהרהר בזה, אם לא מחמת שנפשו יודעת זה העונג ומרגשת בעצמותה לכן גם שאין הדבר מוכן לפניו מ\"מ כ\"ז שנפשו בו הוא שם, וכידוע שכח הזוכר תלוי במוח הדעת שכל מי שלומד ומקבל עונג וחיות מזאת ההשכלה תדבק נפשו בזה מאד וגם שיתלבש במחשבה ולבושים אחרים מ\"מ הנפש שם היא ובטלים ונכללים כל גילוי זיו הנפש לעצמותה כביטול זיו השמש בשמש, משא\"כ במי שלומד בלי קבלת העונג אינו מלובש בזה כ\"א זיו הנפש ולבושי' ולכן בהתלבשותה בלבושים אחרים תסתתר ותתכסה הזיו בלבושים אחרים, ולכן סעודה גדולה זוכרין זמן מה וסעודה קטנה מהר תשתכח מהנפש מסיבת העדר הרגש העונג והחיות וכל שבא en.en.בהרגשה יתירה יותר תדבק בה נפשו ולא ישתכח ממנו וד\"ל.\n<b>וכמו\"כ</b> במדת הגבורה הוא הכעס וההקפדה על המנגד נגד רצונו הוא ג\"כ עיקר סיבת הקיום מהדעת הנ\"ל כי אנו רואים ג\"כ חילוקי מדריגות שונות בזה"],[1900640072,"מאד שלזה אומרים נגד רצונו ואינו מקפיד כלל ולזולתו מתקצף מאד, והוא שלזה יש בו בחי' הדעת וההכרה מחיותו ואם רצונו מאיר מרגיש חיות רב מזה ומחמת זה תדבק הנפש בזה וכל הבא לסתור ולעשות נגד רצונו הזה הוא כאשר קם על חיותו ליטול נפשו ממנו כאשר יקום איש על רעהו ורצחו נפש, אבל מי שאין בו הדעת הזה גם שיש בטבע האנושית לקבל נחת משלימות פעולת רצונו מ\"מ אינו אלא זיו הנפש וכנ\"ל. וכמו\"כ במדת התפארות אנו רואים שנוים רבים שזה משכיל איזה השכלה וחכ' [או] במעשה ולא יפארנה ויגביהנה כזולתו שמשבח ומפאר הדבר מאד ומספר לרבים והכל מטעם הדעת והרגש חיות נפשו כל שיוצא לידי גילוי יש יותר חיות בזה הרגע וניתוסף בה חיות רב, לכן מפרסם ומטעים רום ערך חכמתו, אבל זולתו גם שלנחת יחשב אבל איננו עמוק כ\"כ שתגיע עד הנפש, וכן כולם סיבת קיומם הוא הדעת הנ\"ל. ומ\"מ אין זה אלא מדות דעמלק אבל בחי' ראש דעמלק גבוה הרבה בערך והוא שהגם שבהדעת הנ\"ל נוגע לנפש ממש ויש בזה המשכה עצמי' אבל אינו רק מדידת הנפש [והוא] באופנים שונים, ותדע שהרי אנו רואים הרבה שיש להם חוש ההרגש בממון ואינו כלל בתאוות אכילה וכן להיפך, מזה נראה שלא כל הנפש הוא בבחי' ההרגש הנ\"ל. וכמו\"כ אנו רואים שיש דבר ועת שתתבטל ההתקשרות הנ\"ל כמו מי שיש בו הגבורה והשנאה לאיזה איש מחמת שנוגע לחיי נפשו בעשותו נגד רצונו ומחמת זה תגבר השנאה בלבבו, מ\"מ בעת חתונת בנו או בר\"מ בנו אנו רואים שיש בו שינוי ממהותו עד שחפץ ומשתוקק מאד שיגיל [וישמח] עמו, וא\"א לומר מחמת רום ערכו אינו תופס מקום כלל דבר השנאה, [כי] הלא אדרבה מצד רום הערך והמעלה ביותר תתגבר בו השנאה ולא יוכל לסבול מנגדו כלל כמו בהמן אחרי שגדלו המלך אמר וכל זה איננו שוה לי בראותי את מרדכי היהודי כידוע, אלא שיש כמה בחי' בדעת הנ\"ל מדות ומוחין וגולגולת, מדות הוא ההרגש בנפש במדה פרטית, וראש דדעת דעמלק הוא בחי' תאות ותשוקת עצמיות הנפש להרגיש עצמותה, ובעת שהוא בעונג עצמות הנפש בטלים ונכללים עונג המדות במציאות והי' כלא הי' ממש. וכמו שאנו רואים שיש תשוקה לממון ותשוקה לכבוד מ\"מ לפעמים יניח כבודו עבור הממון הגם שיתבזה כבודו כמו לילך ברגליו להשתכר ולפעמים הוא להיפך שיפזר ממון רב כדי לעשות לו שם וכבוד, וחלוקי מדריגות"],[1900640083,"מינים ממינים שונים בבנ\"א בזה. ומזה נראה שאותו הדבר שנוגע בבחי' עומק הנפש יותר תתבטל עונג הנמשך ממנו ואינו בבחי' ביטול לגמרי כי יש לו חוש ואהבה גם לזה כנ\"ל, וכמו\"כ כשהוא ברוממות הנפש לא נמצא אור וחיות מדת הנפש והראי' בעבור אותה הסיבה והרוממות כשיבוא לעצמותו (צו זיך) אזי השנאה כמקדם. וכן במדת הקימוץ הוא מחמת דעת והרגשת כל פרוטה ופרוטה ומ\"מ ברוממותו יפזר ממונו להתעלס באהבים והכל מטעם הנ\"ל שאין זה כל הנפש רק עד שתתרומם למקום גבוה מזה ובהבטל הסיבה הוא חוזר והדר לטבעו כנ\"ל. וכן אנו רואים ההפשטה מזה בעת ביטושו שישכח על תאוותו באכילה [ושתי'] ומשגל מזה נראה שלא כל הנפש בזה. אבל בחי' ראש דעמלק הוא מה שאנו רואים שלא תתבטל ותשתנה לעולם כל עוד שנפשו בו כמו הקמצנים והכילים שגם בעת רוממותו אינו זז מטבעו ובשעת מעשה מדקדק על כל פרוטה ופרוטה או בשנאה הנ\"ל הוא בתוקף ועוז שלא יוכל לסבול המנגדו לעולם, או כמו שגם בעת ביטושו מבעט ביסורים ואומר יעבור עלי מה ביני לביני צריך למלאות תאותו המושרשים, ואדרבה נעשה כבהמה ממש (ער צו לאזט זיך נאר נאך צו געבין זיך) ואין זה אלא מצד תאוות הנפש בעצמה להרגיש עצמותה. והוא מצוי בנערים המורגלים למלאות תאוות נפשם (נאך צו געבין זיך מנערותם) לכל אשר תשאלם נפשם ולזה יש בו תשוקה וחפיצה לכל דבר שנמצא בו הרגש ועונג הן באכילה הן בממונו והן במשגל (נאך צו געבין זיך אין אלע תאוות מקטן ועד גדול) וזה נק' גס הרוח (א גראבער רוח) כי טבע הרוח ליכלל וליבטל במקורו וזה טבעו בהיפך רק להרגיש עצמותו בבחי' יש ופירוד ממקורו, וזה ראש דדעת שלא תשתנה לעולם כנ\"ל. ואין ב\"ד בא אלא בהיסח הדעת הזה (מען זאל זיך אפ רוקין און פאר לירין דעם דעת והרגשה) [ויהי' ההרגשה באלקות] כי כולם ידעו אותי en.ממש. וזהו עיקר המעמיד והמקיים לכל הז' מדות שלא ישתנו לעולם וכנ\"ל."],[1900640094,"<b>והנה</b> לבחי' מדות דעמלק יש להם בירור ותיקון מהנפש ביסורי גיהנם כידוע כי בחי' גיהנם הוא תיסרך רעתך והאדם בעצמו הוא העושה כל מיני גיהנם כי ידוע שבהפרד הנפש מן הגוף אין להנפש אחיזה בלי כלי כדמיון אור הנר שיאיר ויאחז בפתילה דווקא, ומהו הכלי והאחיזה להנפש הוא כל מחשבותיו והבל דיבוריו שעסקה בחיי חיותה בגוף, כי כל מחשבה ודיבור ותשוקה וראי' אינו נפרד מן הנפש כי המה רוחנים ובכל רוחניות לא תשלוט בו הכליון וההפסד כלל כנודע, וא\"כ בהפרדה מגופה חוש הנשמה לאור ולהכלל במקורה ממש כמ\"ש ואתם הדבקים בה' אלקיכם חיים כולכם היום הדבקים ממש גם בעודנה קשורה בגופה ומכש\"כ בהסירה מתוך גופה שאז ראייתה והסתכלותה ראי' אמיתית ורוחנית כי גם בצדיקים גדולים עבודתם וחיותם מה' חיים נק' חיי בשר ובחי' הודאה לבד ואינו בסוג וערך חיי נפשו כמו שהוא (כי כל רוחניות א\"א להשיג בהיותו בגוף כ\"א דרך שלילה ממש, וכל עמקות שישיגנו ע\"י חומר מוחו ידוע שאינו רוחניות ממש, ומהו רוחניות ממש שמושלל כו' וד\"ל). ובראות הנפש ביטול דכל צבא מעלה באמרם קדוש (וכידוע שג\"פ קדוש אומרים כל הי\"ב שעות שביום ד' שעות על כל קדוש וקדוש) תכסוף ותכלה הנפש להכלל במקורה ממש ומי המעכב אותה כל מחשבה [ודיבור] ותשוקה אשר לא לה' המה מקיפה ומראה לה היפוך חיותה האמיתי, כי כל חיי העוה\"ז הוא חיות דיש ודבר נפרד וא\"כ המח' דעוה\"ז הן הפכים ממש למהות חיי נפשו, ומכש\"כ מחשבות דברים אסורים דל\"ת ח\"ו שתועבת ה' המה ממש ונגד רצונו כביכול ומסתירים לגמרי הארת פני מלך ית' ונעשה מזה מלאכי חבלה ר\"ל, והן יסורים קשים לנפשו שאין לזה דמיון ביסורים גשמיים בגוף, עד\"מ למטה אם ישימו אברי האדם באש שתכלה ממש ותסתלק החיות לגמרי, אין ערך כלל לאש דגיהנם כמארז\"ל אש שלמטה א' משישים דאש דגיהנם כמו שבשישים הוא שיעור ביטול הטעם כידוע, כמו\"כ בטל"],[1900640105,"ממש הצער דאש דלמטה לגבי בחי' אש דלמעלה הנ\"ל. ומי הוא האש הנה הוא אש ותשוקה דחמדת עוה\"ז בהיתר ואיסור כנ\"ל. וכל מה שהנפש תתפעל בחמימות ותשוקה יתירה, יותר תדבק נפשו בזה ונעשה מזה יסורים קשים לנפשו להפרידה מחיי עצמותה (ודוגמא מזה מצינו למטה בעמידת צדיק גמור בתפילה באה\"ר ונפש שוקקה ויבא לנגדו גוי וטמא לבלבלו שממש כל חייו אינם חיים), ודוגמתה בגיהנם שכל תשוקה ואש זרה דעוה\"ז מסתירים ומצערים אותה, כי רואה היא האמת והאש הנ\"ל מסתיר עלי'. ומקבלת צער ויסורי' כ\"כ בכל שעה ושעה שתשכח על כל העונג שהי' לה בכללות תענוגי עוה\"ז כי הצער הוא כיווץ והסתלקות הנפש מכוחותי' שהן בחי' המשכה וגילוי אור הנפש להתמשך כו' וכנ\"ל (וכידוע שבחולי ר\"ל שכוח ישכח לגמרי על כל תענוגי בני אדם וגם אם יבריא נשכח ממנו ע\"י חולי גדול כידוע מענין ר\"י כד חלש איעקר תלמודו ממנו), ואחר קבלתה הצער מכל פרטי הדברים שבעוה\"ז שנעשה מהם בחי' אש ונחשים ועקרבים וכמבואר בתלמוד ומדרשי רז\"ל, הכל כאשר לכל הוא בחי' תיסרך רעתך הנ\"ל עד שנשכח כל העונג דיש ודבר שהי' לו בזה נעשה נקייה ונטהרה רוחו ונפשו כדבר הנזרק באש שתסיר כל חלודה, כמו\"כ ע\"י אש אוכלה דיסורים הנ\"ל שיגיע למהות הנפש בעומק אחר עומק בעצמותה יותר מן העונג וחיות שהי' לה בעוה\"ז ויוצא מן הגיהנם. והנה ידוע מיסורי גיהנם הקשים וכנ\"ל ולכן מחסדי ה' עלינו מאיר ומזכך אותנו בכור העוני והבלבול בעוה\"ז שישכח בזה לגמרי על כל חושי התענוג שהי' לו בעוה\"ז. ואברהם בתפלתו פעל כל זה וכידוע מאמר הזהר הוציאוה בגלותא ותשרף בשלהוביתא דטיהרא, וכנראה בחוש שברוב הדאגה והבלבול דסיבות פרנסה ישכח על תאוותו ממש בהיצר לו והוא בחי' גיהנם בעוה\"ז, וזהו והיו חייך תלואים לך מנגד וכנראה שבזמן הגלות אין שום א' מישראל שיעשה תכלית גדול שיהי' לבו נכון ובטוח בזה (ער האט פארזארגט דיא"],[1900640116,"גאנצי וועלט) כ\"א כל הפרנסות הם כהררים התלוים [מנגד] בשערה ממש, וכל מה שיעמיק דעתו וחכמתו ותשוקתו בעניני מו\"מ עד שיתפעל נפשו מזה מאוד, סיבת כל הסיבות מסבב בתחבולותיו שיתהפך הענין ויתקלקל עד גמירא ממש שנעשה הצער מזה בתוס' מרובה על העונג שהי' לו מזה וכידוע (עש ווערט דער פון שווארצע בלוטין) אשא תכלא דאכיל ושצי ממש, ואחר שממציא לו השי\"ת תרופה ותעלה יתקלקל ג\"כ עד שכל ימי חיי הבלו תלויים ואינו בטוח לאמר מצאתי מזור ותעלה על כל ימי חיי, כי גם העשירים הם תמיד בסכנה עצומה כנראה בחוש. ואם יהי' משאו ומתנו באמונה בלי [שקר] עוול ואיסור אזי בוודאי תטהר הנפש ותשכח כל מיני עוז התקשרותה בתענוגי הבלי הזמן. וכמו\"כ נמצא בעבודת ה' למטה והוא כשיעשה חשבון ברור ואמיתי מירידת נשמתו ממקום גבוה כ\"כ ויראה איך שרע ומר עזבו את ה' חיי החיים ממש מכל פרט ופרט יתמרמר ונעשה לו מזה גופא צער עמוק עד שמואס באמת כל תאווה. ונמצא מובן מזה שחוש התאווה שורפת ומכלה ממש כל מיני עונג והרגשה בהיפוכו בצער עמוק מריחוקו וד\"ל. ולכן אין עומדין להתפלל אלא מתוך כובד ראש שבזה יסור ממנו כל תענוגי בני אדם שמסתירים לחיי נפשו שתהי' אהבת לבבו [שלימה] זכה וברה [לה' לבד] וד\"ל.\n<b>והנה</b> כ\"ז אינו מועיל רק למדות דעמלק כי עיקר הגיהנם הוא מה שעושין צער עמוק לנפש מחמת שהנפש רואה עיקר חיותה בחי' ביטול הנ\"ל ולבושי' וכוחותי' מסתירים ע\"ז כנ\"ל, אבל בחי' דעת דראש דעמלק הוא תאוות הנפש בעצמה להרגיש חיותה ומזה שדי תיכלא בכולא. וא\"כ גם בהפרדה מהגוף מקיפה תשוקתה עד שבחושך הולך ואינו רואה אור כלל כי המות נדבקה בה ואינו קשה לה ההסתר מחמת שאינה רואה לעולם חיותה כי כל החיות שלה בעוה\"ז הי' המות"],[1900640127,"והפירוד ומזה לא תפשוט לעולם כנ\"ל ונעשה רוח רעה ח\"ו ולא יועיל לה יסורי גיהנם כלל וגיהנם כלה והם אינם כלים. ומ\"מ לא ידח ממנו נידח כתי' ויש גם לזה בירור אבל לא נק' בירור אלא איבוד מהותה לגמרי, כי בירורי גיהנם הוא סיבת הנפילה בריחוק ממקורה שמזה גופא נעשה הצעקה והמרירות העמוקה כנ\"ל, אבל לבחי' ראש דעמלק הנ\"ל לא יברר כו' כי לא תראה אור כלל אלא שיאיר עלי' אור מצד חסדי ה' להאביד כל עצמותה. וזה נק' שאול ואבדון כמ\"ש כי אין מעשה וחשבון ודעת בשאול אשר אתה הולך שמה מאחר שאינו בא על הסתר האור בדעת וחשבון כ\"א מהרגשת עצמותה ומהותה לכן אינו בא כלל על בחי' דעת, וממילא אין חשבון ודעת ומעשה המצות מועילים לרומם ולהשיב את הנפש למקורה מאחר שמהות ועצמות הנפש קשורה למטה ואין זה לבוש וזיו הנפש רק הרגשת עצם הנפש, ומחמת זה אנו רואים שגם ביוה\"כ וגילוי רצון הוי' למטה עדיין קשורה בחבלי עבותות הבלי הזמן וכנ\"ל. אלא מצד רחמים וחסד ה' על מהות ועצמות הנפש מישראל וכמ\"ש ה' מוריד שאול ויעל ואתה ה' העלית מן שאול נפשי והוא שממשיכים על הנפש בחי' יסורי מות, על כל שעה ורגע שהרגישה מעצמות חיותה מרגשת העדר ואיבוד חיותה ממש, והוא היסורים דכף הקלע שזורקים נפשו מראש העולם עד קצהו ממש, כי עולם הוא חיות וקצהו הוא העדר ואיבוד כללות החיות ממש עד שנוגע למהות ועצם הנפש ממש שתשכח על חיותה ממש ואז תתעלה. לכן בעוה\"ז הם יסורים קשים ומרים שנוגעים למהות חיות נפשו ממש כמו גע אל עצמו ובשרו דיסורי איוב, שהוא ביאוש החיות עד שיבחר המות מן החיים ממש, וכן בעסקי העולם הוא כמו השבי' שקשה ממות עד שימאס בחייו ממש, שזה בא מצד חסדי ה' עד שנעשה כברי' חדשה. וכן ע\"ד העבודה בחי' שאול הוא המרירות העמוקה עד שימאס בחייו ממש בזכרו איך שאינו מועיל לו שום בחי' דעת ומעשה וחשבון בעניני אלקות גם שמשיג מאד"],[1900640138,"מ\"מ אינו ניזוז כלל מזה, ומזה יראה שכל מהות נפשו נתקשרה ברע המקיפו וא\"א לו להתברר גם ביסורי גיהנם עד שימאס בחייו ויצטער מזה ואזי יבקש שתשוב נפשו ורוחו אל האלקי' אשר נתנה ממש וימאס בכל חיי רוחני וגשמי ומזה גופא נעשה בחי' איבוד מהות הרע הנדבק במהות נפשו העצמי כו' וד\"ל. וזהו שריפת הפרה עד שנעשה אפר (וכמאמר נשמתו נשרפת ונעשית אפר).\n<b>נוסח א'</b>\nוכמו\"כ בחי' ג\"ע נעשה ממעשה איש וכל חיי העוה\"ב הוא משכר המצות מעשיות מעצמיות האדם כי מאתו לא תצא הרעות והטוב פי' כי השכר והעונש אינו בדרך התפעלות ונקמה כמו במלך בו\"ד כשהעבד עושה רצונו יגמול אתו טוב וכשיעשה נגד רצונו יתפעל מאד ומייסר אותו בדרך נקמה כו', ובאלקות אינו שייך כ\"ז כי במלך בו\"ד שייך התפעלות כי העבד הוא ערכו מין אדם כמוהו כי אנו רואים שהזבוב מצד שאינו ערכו לא יתפעל המלך ממנו כמ\"ש שממית בידים תתפש והיא בהיכלי מלך, אף שגם הזבוב הוא בריאה יש מאין כמו המלך וד\"ל. ומכ\"ש וקו\"ח באלקות שהאדם אינו ערכו ריבוא רבבות יותר מאין"],[1900640148,"ערך הזבוב למלך וכמ\"ש אם צדקת מה תתן כו', רק השכר והעונש הוא פעולת האדם כמ\"ש תייסרך רעתך שהרע הוא בעצמו הגיהנם וכן הטוב בעצמו הוא הג\"ע כמ\"ש שכר מצוה מצוה היינו הג\"ע הוא המצוה בעצמה מה שהנפש מרגשת הגילוי אלקות שבמצוה הוא תענוג נפלא כי מעשה וחשבון והתפעלות רוחני' המעשה דבוקה בנפש, ובבחי' תענוג זה יש מדריגו' לאין סוף כמ\"ש וקדושים בכ\"י יהללוך סלה. וביאור הענין כי בקבלת שכר ממעשה המצות בג\"ע יש ב' בחי' כמו בהעונש יש ב' בחי' גיהנם הנ\"ל, היינו גיהנם מהרע שאינו נוגע לעומק עצם הנפש רק ההסתר הוא בלבושי הנפש וכחותי', ובחי' הב' נק' כף הקלע הוא כשהרע הי' בעומק כ\"כ עד שנסתר קדושת עצם הנפש לכן אין בירור להנפש ביסורי גיהנם כנ\"ל רק ע\"י איבוד הנפש. כן לעו\"ז יש ב' בחי' בג\"ע הא' הוא מה שהצדיקים מתענגים מזיו השכינה, ובזה יש מדריגות רבות כי התענוג הוא לפי ערך עומק הנפש בעת עשיית המצוה כידוע אם בדו\"ר טבעיים העונג הוא בג\"ע דיצי' ובדו\"ר שכליים הוא בג\"ע דבריאה כו' ויש עליות עד א\"ס, וכל העליות הוא רק בזיו השכינה מצד שהג\"ע הוא רק גילוי תענוג העבודה כמו שהעבודה הי' רק בלבושי וכחות הנפש בלבד שנק' זיו הנפש. כי גם צדיק גמור העובד באהב' בתענוגים אינו נוגע בנפשו"],[1900640157,"רק בנר\"ן שהוא רק זיו מעצם הנפש הנק' מקיפי' בחי' חי' יחידה שאינם מלובשים בכלי הגוף כלל לכן גם קבלת התענוג בג\"ע הוא ג\"כ מזיו השכינה, ועונג זה בג\"ע נק' בחי' יש כמ\"ש להנחיל אוהבי יש מצד שגם העבודה בגוף הוא בבחי' הרגשת החיות בחי' אה' יש מי שמתפעל, ועבודה זו רחוק מערך ביטול שבעצם הנפש. ובחי' הב' בג\"ע הוא היפוך הרגשת העונג בבחי' יש ונק' אין להם מנוחה בחי' הרגשת אין האמיתי אשר גם גילוי עונג מחכ' דאצי' נק' לגבי בחי' זו בשם עשי' גשמי' כמ\"ש כולם בחכ' עשית, והשגתו בבחי' ג\"ע זה הוא ג\"כ מצד שגם עבודתו הי' בבחי' אין היינו שלא הי' בבחי' התפעלות התשוקה בתענוג מורגש אדרבה שמואס בחייו הגשמי' וגם לא רצה בחיות רוחני רק רצונו הי' להבטל וליכלל אל המקום אשר משם לוקחה, ואין מסתפק בשום גילוי והארה אלקית מאחר שמרגיש מצד המיאוס בחייו שאין זולתו לכן עסק התומ\"צ הוא רק מצד שהתומ\"צ הוא רצונו וחכמתו ית' והוא ורצונו כולא חד ולא מצד שום תענוג גילוי אלקות שזה נק' בחי' יש לגבי עצמותו והוא אינו רוצה רק עצמותו וזהו בחי' ועמך לא חפצתי בארץ רק החפיצה הוא לו לבדו. וזה הבחי' לא יכול להשיג רק הבע\"ת אשר מצד הריחוק העצום יבוא למרירות עצומה עד שימאס בחייו ממש, לכן מצד שבעבודה כזו"],[1900640164,"מאיר בחי' אין האמיתי היינו שמהות חיות נפשו האלקית הוא מהעדר החיות וזהו מהות עצם הנה\"א בחי' הביטול כנר בפני האבוקה לכן גם אחר הפרדו מגופו יקבל ג\"כ בחי' ג\"ע שעשה בעצמו היינו בחי' גילוי אין האמיתי בחי' אין להם מנוחה. ובחי' ג\"ע זה הוא לעומת עונש גיהנם הב' הנק' כף הקלע שהוא בחי' איבוד הנפש לגמרי בחי' אין עד שהוא כמו בריאה חדשה כנ\"ל וד\"ל. ואחר כ\"ז יובן איך שג\"ע מבחי' הא' אין ערך ודמיון לג\"ע שבבחי' הב' כי ג\"ע שבבחי' הא' הוא רק זיו השכינה ובחי' יש מצד שהעבודה הוא ג\"כ בבחי' זיו הנפש ובבחי' הרגש ההתפעלות בחי' יש כנ\"ל, אבל התומ\"צ שבא מצד המיאוס בחייו עבודה כזו נוגע לבחי' עצם הנפש וגם בלי הרגש התפעלות רק בבחי' אין (בל\"א נישט באיי זיך בתכלית) מצד עוצם עומק המרירות מריחוקו מהוי' לכן הג\"ע הוא ג\"כ באופן זה גילוי עצמות אלקות בחי' אין האמיתי וד\"ל."],[1900640171,"<b>נוסח ב'</b>\nוכן בחי' ג\"ע נעשה ממעשה איש וכל חיי העוה\"ב הוא משכר מצוה מבחי' עצמות האדם כי מאתו לא תצא הרע והטוב כי מעשה וחשבון והתפעלות רוחני' המעשה דבוקה בנפשו, ומזה רואה איך שאא\"ס ב\"ה למטה כמו למעלה ממש, והוא בחי' שוב שבנפשו שלא תיכלל לגמרי כי הם מדברים גשמים כידוע וד\"ל. וכמו\"כ הוא בכל עלי' ועלי כמ\"ש וקדושי' בכל יום יהללוך סלה. הנה אותה המחשבה והעסק דתו' ומצות שעשה למטה היא עצמה מקפת את הנפש ממש ותחי' נפשו בעדן וזיו עונג ושעשועי' עצמיי' ומחמת זה יש ריבוי חילוקי מדריגות בבחי' העוה\"ב לפ\"ע עסקו בזה העולם, אבל אין זולתך לחיי"],[1900640177,"העוה\"ב כתי' היינו שגם בעוה\"ב אין מבלעדו ממש שמרומם ומתנשא רבבות מדריגות מבחי' ג\"ע ועוה\"ב כי אינו אלא זיו השכינה. ולזה נק' גם הג\"ע עליון בחי' יש ממש והוא קבלת השכר מהרגשת החיות אלקי שנוגע לנפשו כנ\"ל, אבל יש בחי' ג\"ע שנק' בחי' אין להם מנוחה בחי' הרגשת אין האמיתי ממש כי גם גילוי החכמה נק' עשי' גשמי' קמי' ית' כמ\"ש כולם בחכ' עשית. וגם בחי' זו הב' נעשה קבלת שכר ע\"י עבודתו למטה והוא מחמת שמואס בחייו כנ\"ל, ומאותיות המחשבה ותשוקה הזו שבנפשו ליכלל ולהיבטל ולמאוס בכל מיני חיות רוחני וגשמי רק להשיב הנפש אל המקום אשר לוקחה משם, הנה גם בהפרדה מגופה מקיפות אותה אותיות אלו שאינו מסתפק בשום גילוי והארת"],[1900640183,"אלקות מאחר שבאמת אין זולתו ממש רק שתשוקתו ליכלל בעצמותו, ואזי גם עסקו בתו' ומצות שעשה בזה העולם אחר שמואס בחייו ממש מאיר בזה בחי' אין האמיתי ממש.\n<b>וזהו</b> יפה שעה אחת לשון וישע כו' ולשון שעשועי' עלי' והתקשרות במקור החיים ממש עד שעמך לא חפצתי ממש רק החפיצה לו לבדו. ומעשים טובים פי' מאירים שמאיר כל עצמותו בהם, כי בלא מעשה הטוב הי' חוזר ונכלל במקורו ממש וע\"י מע\"ט נמשך תוס' אור בחי' גילוי המהות שהוא כלבוש המאיר ומגלה כל העצם כמו והלבש אותך מחלצות לבוש המראה חליצת הלבוש וד\"ל. וזהו המן מן התורה מנין, כי באמת גילוי מדות דקדושה הוא ג\"כ כך שהמדות"],[1900640189,"המאירים מן החכ' יכולים להתהפך ולהשתנות למהות אחר אבל ע\"י הרגשת החיות באלקי' חיים נעשה קיום ותוקף המדה, וזהו שארז\"ל המתפלל צריך שיתן עיניו למטה ולבו למעלה בחי' עינים דחכ' למטה הוא להשפיל עצמותו, ולבו למעלה רק הוא לבדו למעלה הרגשת העילוי למעלה ולמעלה וד\"ל.\n<b>וזהו</b> יפה שעה א' בתשובה ומע\"ט בעוה\"ז מכל חיי העוה\"ב פי' שעה הוא מל' וישע כו' פי' שנעתק מגשמי' ורוחני' רק לו לבדו. וגם שעה ל' שעשועים העצמי' היינו התקשרות במקור חיי החיים בחי' ועמך לא חפצתי כנ\"ל בתשובה, פי' שבחי' שעה הנ\"ל א\"א להשיג מדריג' נעלה כזו כ\"א ע\"י עומק מרירות התשובה. ומע\"ט פי' מצד עומק המרירות מהתשובה המעשים מהתומ\"צ הם טובים פי' מאירים מבחי' עצמיות אין האמיתי לכן אמרו שבבחי' ג\"ע הבא מתומ\"צ הבא מצד התשובה יותר טוב מכל חיי העוה\"ב פי' מבחי' ג\"ע שיש בו מדרי' רבות, כי מצד שהגילוי הוא רק מזיו השכינה לכן יש בה מדרי' רבות. כמו עד\"מ זיו השמש יש בו מדריגות כמו ביום צח מאיר הזיו בתוקף גדול ובבית דרך החלון ודרך פרסא מפסיק אינו מאיר כ\"כ בתוקף כמו בחלל העולם וכשיתלבש הזיו עוד בחלון שני יהי' הזיו בחלישות יותר וכן יכול להיות חילוקי מדרי' עד א\"ס. אבל אם הי' באפשרי שיתגלה עצם כדור השמש בהבית דרך החלון לא הי' בזה שום חילוקי מדרי' במהות האור והי' שוה בהחלון דרך הפרסא המפסיק כמו בחלל העולם, וכן ריבוי רבבות חלונות ופרסות לא יעשו שום שינוי בהארת עצם השמש כי העצם א\"א שישתנה. וכן יובן למע' הג\"ע מבחי' הא' שהוא רק זיו השכינה נק' חיי העוה\"ב כי בהזיו יכול להיות ריבוי התחלקות מצד התחלקות העבודה שאין אחד דומה"],[1900640195,"לחבירו בענין עומק ההתפעלות מצד שבחי' העבודה אינו נוגע לעצם הנפש כנ\"ל רק בזיו ולבוש הנפש לכן יכול להיות בזה חילוקי מדריגות רבות, אבל העבודה הבא אחר התשובה הוא מגיע בעצם הנפש ובעצם אין מה לחלק. לכן אמרו יפה שעה א' היינו שעה ל' וישע פי' התקשרות העצמי' שהיא בחי' אחת בלי התחלקות ונק' אחת ל' נוק' בחי' מקבל שההתקשרות העצמי' מנה\"א היא בחי' כלי לקבל מעצמות אלקות הנק' בחי' יחיד כי גם למע' בהעולמות ההתחלקות הוא רק בהזיו אבל עצמי' נק' בחי' יחיד, ומזה הבחי' יקבל הגילוי אלקות בג\"ע מי שעבודתו הי' בבחי' וישע כנ\"ל וד\"ל.\n<b>אך</b> צ\"ל שלפי\"ז הי' די להשיג בחי' ג\"ע גילוי האין בבחי' התשובה בלבד בחי' מואס בחייו ומה צריך לזה המע\"ט ג\"כ. אך הענין הוא שהתשו' בלי תומ\"צ הוא בחי' אור בלי כלי והוא כמו בחי' מיתת בני אהרן כמ\"ש בקרבתם לפני הוי' שלא רצו להשפיל א\"ע להחזיר נשמתם לגופם כי חשקה נפשם לצאת מגדרי הגבול לגמרי וליכלל באור הוי', וזה נק' בחי' רצוא בלא שוב ובס\"י אמר אם רץ לבך שוב לאחד שעיקר תכלית הבריאה הוא שנתאוה הקב\"ה להיות לו דירה בתחתונים דוקא היינו להמשיך גילוי אלקות למטה ע\"י תומ\"צ בכלים מכלים שונים וכמ\"ש לא לתהו בראה לשבת יצרה וד\"ל. ואחר כ\"ז יובן שהעיקר הוא התומ\"צ שאחר התשובה היינו להמשיך בחי' אין האלקי בכלים דוקא, וגם בחי' ג\"ע הוא הלבשת העונג בנה\"א ואם לא עסק בתומ\"צ אחר התשובה לא הי' באפשרי שיקבל הנה\"א בפנימיות' את בחי' האין האלקי רק הי' ביטול המהות לגמרי, וזהו בחי' הציץ ומת דבן עזאי. אך אינו מובן איך יכול בחי' אין האלקי להתלבש בנפש האלקי' כי ההלבשה בעצם הוא בחי' מהות היפוך מהאין, אך הענין הוא שגם העבודה בתומ\"צ מהבע\"ת הוא מצד בחי' מואס בחייו שהוא ממש העדר החיות, ואעפ\"כ יש חיות עצום בעסק התומ\"צ שלו כי ההעדר החיות בעצם הוא חיות גדול להנה\"א כי זה עצם מהות נפש האלקית להרגיש ביטול' מכל וכל כמ\"ש מלך ממית ומחי' פי' המיתה היינו הרגשת העדר החיות הוא בעצמו החיות, וכמו בחי'"],[1900640200,"הנבואה שהי' מתבטל חושי הנביא לגמרי וזה הי' עיקר החיות להשיג דוקא בעת ביטול חושי' השגות נפלאות. וכן למע' הוא חיות עצום להנה\"א ממה שמרגיש איך שהוא אין באמת וזהו והלבש אותך מחלצות פי' לבוש המראה חליצת הלבוש הזיו en.היינו גילוי האין וד\"ל."],[1900640022,"להבין ענין לקיחת אנשי חיל מישראל ביד נכרים. הנה כתיב כי רוצה ה' בעמו וכתיב רצון ה' ליראיו, רצון ה' היינו תומ\"צ שהוא עיקר רצונו ית' כידוע שעלה ברצונו הפשוט לברוא את העולם [ועיקר רצונו ית' בבריאת העולמות] כדי להיות לו דירה בתחתונים שיקבלו ישראל עליהם ועל זרעם עול תומ\"צ, והוא עיקר קיום העולם כמ\"ש אם לא בריתי יומם ולילה חוקות שמים וארץ לא שמתי כו', [וכמאמרם ז\"ל ע\"פ ויהי ערב ויהי בקר יום הששי תנאי התנה הקב\"ה עם מע\"ב אם יקבלו ישראל את התו' כו'], וכמארז\"ל ע\"פ ארץ יראה ושקטה מתחלה יראה ואח\"כ שקטה, והנה ידוע ששרש המצות הוא בכתר [עליון] דאצילות, וגם התורה (הגם דאורייתא מחכמה עילאה נפקת), פי' ששרש התורה הוא בחכמה דאצי', מ\"מ הלא שרש החכמה הוא בכתר. וביאוה\"ד הנה ידוע שיש ב' מיני רצון, הא' [נק'] רצון שלמעלה מהחכ' למשל אם רצונו לעשות או לאהוב או לשנוא איזה דבר ואין טעם לדבר, ואדרבה הטעם ודעת מלמדו להתנהג בהיפוך ואין רצונו כ\"א בדרך עקשות, והב' נקרא רצון שלמטה מחב\"ד, למשל אדם שרצונו לאהוב איזה דבר מאחר שמבין בחב\"ד שאותו הדבר [הוא] טוב וראוי לאהוב אותו. ואם יתבונן שיוכל לבוא מאותו הדבר לידי קלקול, וראוי להתרחק מזה ולשנוא אותו אז נעשה רצונו לשנוא, כי כל רצונו הוא ע\"פ טו\"ד, וכאלו ב' עניני רצון ישנם ג\"כ למעלה כמשית\"ל. והנה [בענין] עלה ברצונו הפשוט לברוא כו' ולא נברא כ\"א בשביל"],[1900640036,"ישראל, שהוא ית' יקבל עונג מהתומ\"צ שיעשו, ואין טו\"ד לזה מושג בהשגת הנבראים כי הלא א\"ס ית' הוא מובדל ומרומם מגדר עולמות בע\"ג (כמ\"ש קדוש כו') ואין שייך לומר שיברא עולמות בע\"ג ויקבל עונג מעשיית בע\"ג רצונו ית', גם איך יהי' רצונו בתרי\"ג מצות ודקדוקי המצות דוקא, אשר כ\"ז אף שלעצמותו ית' יש טעם לזה מ\"מ אין הטו\"ד מושג [ונתפס] בהשגת הנבראים בע\"ג אפי' בחב\"ד באצילות, והוא נעלם ועומד למע' מחב\"ד בבחי' מקיף בבחי' כתר דאצי', למשל כמו הכתר מל' שהוא מקיף לראש וחב\"ד המלך ואף שיצוה [המלך לעמו] לעשות דבר שאין לו טו\"ד ישמעו לו, מפני שיש כתר מל' בראשו, רק אין המשל דומה לנמשל לגמרי, כי באדם הרצון שלמע' מחב\"ד הוא [בדרך] עקשנות, שאף אם יאמרו לו למה תעשה כך שהטו\"ד מראה בהיפוך לא ישמע להם, אבל לא זו הדרך ישכון בו אא\"ס סט' דקדושה שהוא בחי' ביטול להיות נכנע ולשמוע למאן דהוא, אך הפי' רצון שלמעלה מחב\"ד [למעלה] היינו שטעם רצונו ית' אינו נתפס בחב\"ד שבנבראים כמו שאין נתפס טעם ורצון העקשנות באדם [בחב\"ד], רק אינו דומה לגמרי כ\"א [כמו] למשל אדם גדול בחכ' מאד, שאומר דבר שכל עמוק [מאד] לאיש הדיוט פתי אשר אין תבונות בו כלל, ורק מאמין הוא לכל דבר וחוזר על כל דבר החכם כמה פעמים עד שהוא שגור על לשונו, ואף שאינו מבין השכל העמוק כלל וכלל לא, אך דברי פי החכם הן יקרים אצלו מאד מאחר ש[הוא] יודע שאדם גדול הוא וכל דבריו מלאים שכליים עמוקים אף שלא נשאר אצלו כ\"א דברים בעלמא אותיות פורחות, אבל עכ\"פ יש בדבורו שכל עמוק אף שמדבר אותיות בעלמא שהאותיות אלו הם שוים לכל שארי האותיות שאין בהם שכל כלל. וכ\"ה ממש ענין התומ\"צ [רצון הוי'] שלעצמותו ית' יש טעם לרצונו, אך הוא ורצונו אחד וכשם שעצמותו ית' א\"ס כך רצונו ית' א\"ס, לכן אינו [יכול להיות] נתפס בשכל בע\"ג כ\"א עצם המצות כמו שהם בחי' אותיות בעלמא, [וישראל עמו] הנבראים [משיגים ו]מאמינים שרצונו ית' מלובש במצות אלו [אף שאינם משיגים איך ומה הוא] והוא ית' מתענג מזה, והוא בחי' רצון שלמעלה מחב\"ד למעלה וד\"ל."],[1900640049,"<b>ואף</b> שנאמר אלה החוקים והמשפטים כו' ופירש\"י ז\"ל שיש מצות שהן חוקים כמו חק ולא יעבור חק ניתן מאת המלך בלא טעם, כמו מצות לא תאכל חזיר [ומצות] לא תלבש שעטנז ומצות שילוח הקן וכדומה. ויש מצות שיש משפט וטעם לעשות כן כמו בסוכות תשבו שבעת ימים למען ידעו כו' ומצות אכילת מצה שלא הספיק בצקם כו' וכמו ע\"כ לא יאכלו בנ\"י את גיד הנשה וכדומה רבים, מ\"מ טעם זה אינו אלא [להשיב] להשטן ולאוה\"ע [שייך לומר שלזה יש טעם ולזה אין טעם] (כמ\"ש רש\"י גופי' שם), אבל באמת לאמיתו למה הי' הרצון כך דוקא, ואיך הוא ית' מתענג ממצוה זו, טעם זה אינו נתפס אפי' בחב\"ד דאצי', וזהו ששרש התומ\"צ הם בכתר דאצי' וד\"ל.\n<b>וזהו</b> כי רוצה ה' בעמו, רצון ה' (בחי' כתר) המה התומ\"צ הוא בעמו ישראל. וזה הי' באמת בזמן שביהמ\"ק הי' קיים שהיו כל המצות במילואם, אבל עכשיו בעוה\"ר שחרב ביהמ\"ק בטלו המצות רובם ככולם כמו מצות התלויות בארץ ומצות כל הקרבנות כולם. וצ\"ל ענין חורבן ביהמ\"ק שידוע שבשביל העונות נחרב הבית, ומפני חטאינו גלינו מארצנו ואין אנו יכולים לקיים המצות רובם ככולם (שע\"ז הוכיחו הנביאים קודם החורבן שיחזרו בתשובה ולא יחרב), ולכאורה הוא תמי' רבה וכי בשביל שעברו על מצות ה' וביטלו מצותו ית' יהי' העונש ע\"ז שיחסרו ויתבטלו המצות, יותר הי' ראוי להענישם בגופם ובממונם בכדי שיחזרו בתשובה עי\"ז והמצות לא יבטלו ויהיו במילואם ויתחזקו יותר במצות ה'. ועונש השעבוד מל' על העוונות שעשו הי' יכול להיות אף שהי' ביהמ\"ק קיים והמצות היו במילואם. אך ע\"פ מה שביארנו שמצותיו ית' נק' רצון ה' יובן היטב ג\"כ ענין חורבן הבית שהוא כמשל אדם שאוהב את חבירו ואזי רצונו מלובש תמיד להיטיב לו, אך אם חבירו עושה היפך רצונו אזי ממילא מסתלקת האהבה והרצון שהי' להיטיב לו מאד. וכמו\"כ יובן בענין חורבן ביהמ\"ק, שמתחלה עלה ברצונו הפשוט"],[1900640061,"לברוא את העולם במדת טובו וחסדו כמ\"ש עולם חסד יבנה, והכל הוא בשביל ישראל שעבמ\"ח כמ\"ש בנים אתם כו' וכמ\"ש בלק\"א, שרצונו ית' הי' להיטיב ע\"י קיום רצונו בתומ\"צ (שלא יאכלו הנשמות נהמא דכסופא) (אך אין לעשות עמלק\"פ כ\"א בשביל שיקבל השי\"ת עונג מזה וד\"ל), וע\"י העונות שהם היפך רצונו ית' הי' קטרוג שנסתלק רצונו ית', ולא בדרך עונש כלל, כי העונש אינו ניכר כ\"א ביסורין ר\"ל ובשעבוד מל'. אך מ\"מ לא כל רצונו נסתלק, כמארז\"ל ע\"פ דומה דודי לצבי מה הצבי כשהוא בורח מחזיר ראשו לאחוריו אף הקב\"ה כן, וצ\"ל איך שייך [לשון ראשו אצלו ית' הלא אין לו דמות הגוף ואיך שייך] לשון בורח אצלו ית', הלא [כתיב] אני ה' לא שניתי, ו[תמיד הוא כמ\"ש] את השמים ואת הארץ אני מלא כתיב דלית אתר פנוי מיני' כלל, אך הענין הוא כמ\"ש בלק\"א דהוא ורצונו א' כי הוא המדע כו' ואין ביכולת האדם להבינו על בוריו כמ\"ש כי לא מחשבותי מחשבותיכם ולא דרכיכם דרכי כו', וזהו פי' מה הצבי כו' אף הקב\"ה כשהוא בורח שהוא בחי' הסתלקות רצונו ית'. ומ\"ש מחזיר ראשו לאחוריו, הנה ראשו הוא כמ\"ש ראשו כתם פ\"ז, היינו פ\"ז מצות שנשארו מרמ\"ח כי קס\"א נתבטלו, ופ\"ז מצות אלו נק' בחי' ראשו, כי המה עיקר קיום העולם. כי הגם שחרב ביהמ\"ק ונתבטלו קס\"א מצות מ\"מ הרי לא נחרב העולם משום אם לא בריתי כו'. שהפ\"ז"],[1900640073,"מצות שנשארו המה עיקר קיום העולם, עד\"מ כמו הראש שבאדם ששם מתפשט עיקר חיות הנשמה ביותר ומשם מתפשט החיות לכל האברים והגוף ע\"י הגידים (הנק' נערווין) כידוע.\n<b>ולהבין</b> לשון החזיר ראשו, דמשמע שנסתלקו גם הפ\"ז מצות אך שהחזירם כמקדם, הל\"ל הניח דמתי נסתלקו. אך הענין הוא דבאמת ב[אותו] זמן שנחרב הבית הי' הסתלקות כל רצונו ית' אפי' הפ\"ז מצות הנוהגות גם עכשיו שהם בחי' ראשו, כי היו אז כל ישראל אבלים, ואבל פטור מכל המצות. וז\"ש בזו\"ח פ' בלק דבעת החורבן חשבו כל חילא שמיא דכל עלמא תתהפך, והיינו מפני שנסתלק כל רצונו ואפילו הפ\"ז מצות, וכתי' אם לא בריתי כו' חוקות שמים וארץ כו' [וזה לא ידעו שעתיד השי\"ת להחזיר הפ\"ז מצות בחי' ראשו וד\"ל]. אך אח\"כ החזיר בחי' ראשו שהו\"ע הפ\"ז מצות שהם עיקר קיום העולם, ו[ה]מל\"ת לא נתבטלו כלל, כי אינם יכולים להתבטל לעולם כ\"ז שיש מ\"ע אפי' במקצתם, ולמשל רופא שאמר לחולה אל תאכל ואל תשתה זה וזה, ושמור עצמך מן הצינה וכדומה שהמה דברים המזיקים לבריאותך ואח\"כ אתן לך רפואות, שאין נפק\"מ אם יתן [לו] רפואות רבים או מעט, עכ\"פ צריך ליזהר בכל האזהרות שצוה הרופא, שאם יעבור אפילו על דבר א' דמו בראשו ולא יועילו הרפואות שיתן לו להחיות גופו. ואפ\"ה עיקר הרפואה היא מן הרפואות, אך שזה בלא זה א\"א. וכ\"ה ממש ב[ענין] תרי\"ג מצות שממשיכים אא\"ס בעולמות, ואף כי שכר [מצוה] בהאי עלמא ליכא [כמ\"ש היום לעשותם ולמחר כו'], כ\"א מי שטרח בע\"ש יאכל בשבת ביום שכולו שבת דייקא לע\"ל שיגלה כבוד ה' כמ\"ש ביום ההוא יהי' הוי' אחד ושמו אחד ואמרז\"ל אטו האידנא לאו אחד, אלא דלע\"ל יהי' גילוי כמו אחד, היינו שיומשך שם כבוד מלכותו ית' כמ\"ש אז אהפך אל העמים שפה ברורה כי יתגלה בעולמות וכמ\"ש ונגלה כבוד ה' כו' בשוב ה' את שיבת ציון כו' כמ\"ש ומלאה הארץ דעה ולא ילמדו עוד כו'."],[1900640084,"<b>אך</b> כ\"ז תלוי בתומ\"צ עכשיו להזמין ליום שכולו שבת, וכדכתי' כמים לים מכסים, פי' כמו הים שמלא בכל המקומות בשוה [לפי הנראה], אך מ\"מ הדבר תלוי בעומקו, שבמקום שעמוק יותר יש שם מים יותר, וככה יובן בנמשל, שלע\"ל שכאו\"א ישיג יותר אא\"ס ויהנה מזיו השכינה [כאו\"א] כפי שטרח בעוה\"ז בתומ\"צ ואז לא יצטרך שילמדו אותו אך מי שזכה בתומ\"צ להשגה עליונה יותר לא יועיל כשילמד להקטן ממנו, כמ\"ש למקטנם ועד גדולם, הרי שיהי' בחי' קטנות ובחי' גדלות, כ\"א כפי הכלים שהכין כן יקבל, וזהו כמים לים כמו הים שמלא בכ\"מ, וכל מקום מקבל לפי עמקו, כן כאו\"א ממשיך חלקו השייך לו בעולם (וכמ\"ש בלק\"א שההשפעה נחלק לס\"ר חלקים כמספר ס\"ר נשמות בכלל, ובפרט כל חלק נחלק לס\"ר חלקים כפי מספר הניצוצות שבכל נשמה), רק כ\"ז כפי שהכין בתומ\"צ, דהנה אנו אומרים קודם כל מצוה [ומצוה] לשם יחוד קוב\"ה ושכינתי' שהו\"ע יחוד סובב בממלא כנודע, וזה אינו אלא ברמ\"ח מ\"ע אך כ\"ז לא יועיל להמשיך יחודו ית' [בעשיית המ\"ע] כ\"א בשמירת במל\"ת דוקא כמ\"ש סור מרע ואח\"כ ועשה טוב, וכתיב ולרשע אמר אלקים מה לך לספר חוקי והוא לשון אבן ספיר שמדמה בנפשו שמזהיר ומספר וממשיך אורו ית' בעשיית החוקים. אבל לא כן הוא מפני שהוא רשע ואינו נזהר במל\"ת והוא כמו במשל הנ\"ל דרופא הנ\"ל כו' שאין נפקותא אם עושה מצוה א' או הרבה מ\"מ לא יועילו אם לא ישמור עצמו [מתחלה] שלא יעשה היפך רצונו ית' ח\"ו במל\"ת, לכן אף גם זאת בהיותם שלא נשאר לנו רק פ\"ז מצות מ\"מ צ\"ל כל השס\"ה מל\"ת ולא נתבטלו ואם יעבור [אפי'] על אחת מהנה ח\"ו לא יועילו המ\"ע כלום עד שיעשה תשובה נכונה כדת חרטה ועזיבה, וד\"ל.\n<b>והנה</b> אף גם לאחר החורבן שלא נשאר כ\"א פ\"ז מצות מחמת עוונות שרבו [כו', מ\"מ] הנה עוד מוסיפים סרה לעשות נגד רצונו ית' מזה נעשה קטרוג גדול שיסתלק כל רצונו ואפי' מהפ\"ז מצות שנשארו (ויתהפך עלמא משום אם לא בריתי כנ\"ל), ואף שפושעי ישראל מלאים מצות כרמון כמ\"ש כפלח הרמון רקתך"],[1900640095,"ודרשו רז\"ל אפי' ריקנין שבך כו', מ\"מ יש קטרוגי' לומר שמה שעושים איזה מצוה היא רק כמ\"ש מצות אנשים מלומדה [והיינו] שאינם עושים [המצוה] בדו\"ר שפי' בזוהר שהוא רעותא דליבא, והראי' [לדבריהם] שעושים נגד רצונו, [ומשם יוצא הקטרוג לומר שעושים המצות בלא דו\"ר] ותומ\"צ בלא דו\"ר לא פרחא לעילא וכאלו לא נעשה דמיא, כיון שאין [להם] בזה אהמ\"ס. ולזה נעשה תיקון לבטל הקטרוג תיקוני דגברא ולתיקוני דעלמא, היינו שהוא ית' הממליך מלכים ולו המלוכה כמ\"ש לב מלכים ושרים ביד ה' ונותן בלבם לגזור הגזירה שגוזרים מלמעלה על האי והאי גברא שיטב בעיניהם והכל [הוא] בכדי לראות אם יש לו רעו\"ד, דהיינו שנותנים אותו בידיהם, והמה מעבירין תער על זקנו ופאות ראשו ואונסים אותו לחלל שבת וכדומה איסורים רבים, ומחמת הצער שמצערים אותו בגשמיות יצעוק לבו אל ה' בקול מר באמרו אלי אלי למה עזבתני רחוק מישועתי דברי שאגתי, ולמה נבראתי כ\"א לעשות רצונו ית' ולא נולדתי לבהלה וריק, ועתה אללי לנפשי איך שנתרחקתי כ\"כ עד למאד עד שאינני יכול כלל לקיים ולעשות את כל דברי התורה הזאת, ואפילו הפ\"ז מצות עשה שנשארו ברכה [והמשכה] מעת חורבן הבית, שזה חלקינו לנו ולבנינו כל ימי חלדינו, ונוגע לו זאת לעומקא דלבא, ובמסתרים תבכה נפשו ממש [וחייו אינם חיים ממש] ומבקש מה' קרבינו לעבודתיך וטהר כו', והנה כשנזדמן אח\"כ לידו איזה מצוה ואפשר לו לקיימה אזי ישמח ותגל נפשו עלץ לבו בה' וירנן נפשו בישועת ה' [זאת], ובשמחה של מצוה [רבה] זאת נתגלה שיש לו רעו\"ד ואזי נק' ירא ה' בשלימות, היינו אף שאינו יכול לקיים כמה וכמה מצות, מ\"מ בהצער שמצער א\"ע מהעדר אותן המצות נחשב לו כאלו עשאם. והרי הוא מקיים את העולם כמ\"ש וצדיק יסוד עולם, ונתבטל הקטרוג. והפ\"ז מצות אינם מתבטלים כמארז\"ל ע\"פ סוף דבר כו' את האלקים ירא כו' כי זה כל האדם ופי' כל העולם כולו לא נברא כ\"א בשביל זה ירא אלקים, והיינו שעיקר קיום העולם הוא מהפ\"ז מצות וראוי שלא יתבטלו בשבילו"],[1900640106,"(ובהטירחא שמטריח [א\"ע] בעבודת המלך בכל נפשו הוא מקיים מארז\"ל יגיע כפיך כי תאכל כו' אשריך בעוה\"ז וטוב לך בעוה\"ב, שבודאי הפי' שצ\"ל ג\"כ יר\"ש, דאל\"ה בודאי לאו מעליותא הוא במה שנהנה מיגיע כפו, והנה ירא ה' ג\"כ כנ\"ל).\n<b>ולהבין</b> כ\"ז באר היטב, גם להבין איך בהצער שמצער א\"ע נחשב לו כאלו עשה, צ\"ל תחלה מ\"ש אאע\"ה להקב\"ה אם בני חוטאים במה יתכפרו [א\"ל] בעולה וקרבנות התינח בזמן שביהמ\"ק קיים, בזמן שאין ביהמ\"ק קיים מה תהא עליהם, א\"ל הקב\"ה כבר כתבתי זאת תורת העולה כו' כשיעסקו ישראל בתורת עולה מעלה אני עליהם כאלו הקריבו עולה כו', ולכאורה תמוה כי אם יש כח בתורה לכפר כאלו הקריב כו' הלא התורה היא נצחית וא\"כ למה לא יועיל לימוד התורה כקרבן גם כשביהמ\"ק קיים, ולמה הוצרך אז דוקא עולה וקרבן כו'. אך הענין הוא כנ\"ל דתומ\"צ בלא דו\"ר שהוא רעו\"ד לא פרחא לעילא, ולכן כשביהמ\"ק קיים לא הועיל לימוד התורה כעולה וכקרבן שלא הי' יכול להתלבש באמת הרעו\"ד בלימוד התורה בלי עולה וקרבן, כי רעו\"ד היא שרוצה לעשות רצונו ית' באמת ורצונו הוא להביא קרבן. [ו]לכן לא [הי' ] יכול[ים] להתלבש [אז] הרעו\"ד כ\"א בהקריב את קרבניהם [דבידו הי' לקיים לימודו], אבל לאחר חורבן הבית בעוה\"ר יכול להתלבש הרעו\"ד בלימוד התורה ממש, והוא ע\"י הצער מזה שאינו יכול [לעשות ו]לקיים מצותיו ית' שלבו רוצה לעשות [רצונו ית'], אך מאת ה' היתה זאת מחמת עוה\"ר, והוא מצטער מזה [ב]מאד [על העדר המצוה], כי רוצה מאד לקיים מצותיו ית' שיהי' לו ית' נח\"ר מעבודתו, והנה לפי ערך הצער כ\"ה ערך התענוג (למשל אדם שמתענג מאיזה דבר ואם אין לו אותו דבר הרי הוא מצטער, אבל אם לא הי' מתענג מאין לו צער בהעדר אותו הדבר ומה איכפת לו) ומהצער ניכר שאם הי' לו הדבר ההוא הי' מתענג, ולכן נחשב הצער כמו התענוג ומתלבש ב[תוך] לימוד התורה להיות גדפין לפרחא לעילא ולהיות כאלו הקריב כו', כאלו הכ' מרמז לבחי' כתר, פי' דודאי לא זהו הקרבן ממש, רק כמו שעיקר הקרבן עצמו כשמקריבו ברעו\"ד הרי הוא עולה לשרשו שרש המצות בחי' כתר שהוא בחי' עונג שהקב\"ה מתענג נח\"ר לפני כו', כן בלימוד התורה ברעו\"ד והצער ההוא"],[1900640117,"עולה ל[שרשו] שרש הקרבן בחי' כתר (ואף דאורייתא מחכ' נפקת, פי' שלימוד התורה ברעו\"ד היינו שרוצה לקיים מצות התורה שגם זה הוא מצוה אז עיקר עליתו לשרשו בשרש המצות הוא בבחי' חכמה דאצי', אבל ברעו\"ד היינו הצער כנ\"ל הוא עולה לשרשו בחי' כתר שבמקום שהגדפין יכולין להעלות לשם עיקר עליתו וד\"ל). אך הרעו\"ד הוא כמו גדפין וצריך להתלבש בתוך איזה גוף להעלותו ולימוד התורה הוא הגוף וד\"ל. ומעתה יובן היטב שבהצער שבישראל א\"ח מצטער כו' והוא רעו\"ד עולה עד בחי' כתר שרש המצות ומעורר שם שלא יסתלק כל רצונו בחי' כתר הנ\"ל וד\"ל.\n<b>ועפ\"י</b> כל הדברים הנ\"ל מובן מ\"ש בסידור האריז\"ל [לאחר סדר קרבן פסח] שמי שהוא יר\"ש והוא מיצר ודואג על חורבן ביהמ\"ק כו' כי הרעו\"ד שיהי' כאילו הקריב א\"א כ\"א בהצער כנ\"ל. (ומ\"ש במ\"א שלימוד התורה צ\"ל בשמחה ובטוב לבב שלכן נתקן לומר קפיטל נ\"א [למנצח בבוא כו'] אחר [סדר] תיקון חצות כפי סדר האריז\"ל משום ד[ב]ת\"ח הוא מתמרמר על עונותיו וגלות השכינה ואחר ת\"ח שצריך ללמוד [תו'] עד אור הבוקר לתקן מה שפגם כידוע וד\"ת צ\"ל בשמחה ובמזמור זה כתי' תשמיעני ששון ושמחה תגלנה עצמות כו' שהוא בחי' [כתר] יתרון האור כו' זה לא נאמר רק על התורה ועל העבודה בהלכות שנוהגות גם בזה\"ז שיכול לעבוד ה' במצותיו שלומד, ולכן צ\"ל שש\"מ ששמח בזה שיכול לעבוד את ה' באלו המצות ובהתורה שלומד, אבל לימוד [כל] דת ודין שאינו נוהג לאחר החורבן צריך להצטער כנ\"ל וד\"ל. ולכן נתקן לומר קודם התפלה פ' קטורת ופ' איזהו מקומן הלכות שאינן נוהגות עתה בכדי שיתמרמר ע\"ז ר\"ל שהוא בחי' הכנעה שצ\"ל קודם התפלה. ולכן [לא] כת' מי שהוא ירא שמים הוא מיצר כו' שהוא מלתא דפשיטא שצ\"ל הכנעה וביטול קודם התפלה), ואח\"כ יבקש יה\"ר שיבנה ביהמ\"ק ב\"ב מלב ונפש חפצה אמן."],[1900640128,"<b>ולהבין</b> יותר מה שיש כמה אנשים יראי אלקים שמצטערים על חורבן ביהמ\"ק [ולמה צריכים] הלא די באחד (משום אם לא בריתי כנ\"ל) [בסוד כל העולם לא נברא אלא בשביל זה כו']. הענין הוא כמ\"ש בלקו\"א שיש ס\"ר נשמות ולכל נשמה שייך חלק א' מס\"ר בעולם (וזהו בד\"כ, ובד\"פ נחלק כל חלק לס\"ר כנגד ס\"ר ניצוצות שבכל נשמה כמבואר לעיל באריכות), ואם יש איזה קטרוג על איזה נשמה שיסתלק כל רצונו ית' מאתו מחמת העונות כנ\"ל והחלק בעולם השייך לה יאבד, אזי לוקחים ניצוץ א' מהנשמה ההיא לראות אם יש רעו\"ד בחלקו כנ\"ל לומר עליו את האלקים ירא כו' כי כל העולם השייך לנשמתו לא נברא אלא בשביל זה (והצער והיסורין הוא למרק עונותיו שעשה), והכל לפ\"ע העונות, אך יש שנבדק בנסיון בביתו ויש שגוזרין עליו מלמע' שיבדק בידיהם דוקא (לפי שצריכים שיעבור בן ישראל בעת מלחמה או שום סיבה אחרת במדבריות או במקומות אחרים בארץ לא זרועה ולא ישב אדם שם לטהר אותו האויר חוץ לארץ כמבו' במ\"א, וזה הטעם [הוא] ג\"כ שצריכים לאיש שלא נתברר [גם] בידיהם ונשאר כמו שהוא רק כיון שלא המיר דתו יכול לטהר את האויר [שעובר] שם כידוע), ועל פרטי פרטיות אלה הדברים נא' בהדי כבשא דרחמנא למה לך. ואף דגם בעת החורבן הי' כמה וכמה צדיקים ומ\"מ נסתלקו קס\"א מצות ולא נשארו בשבילם, היינו דמשום אם לא בריתי [משום מאמר דכל העולם לא נברא כו'] נשארו פ\"ז מצות [בשבילם] אבל עתה בעוה\"ר שנעשה קטרוג גדול שיבטלו גם הפ\"ז מצות והעולם יחרב משום אם לא בריתי כו' לכן כדאי הוא זה [שמצטער ברעוד\"ל] שלא יחרב העולם על ידו [שעליו נאמר] כל העולם לא נברא אלא בשביל זה\nכנ\"ל וד\"ל.\n<b>ולהבין</b> הענין מה שיש שלא הי' ממיר דתו לעולמים אם הי' בין ישראל, וביניהם הוא ממיר א\"ע, למה צ\"ל כן (ואעפ\"כ לא יתגבר הקטרוג לאמר הוברר הדבר שלא הי' לו רעו\"ד [מקודם] במצות שעשה, כיון שיש א' מהנשמות יר\"ש כנ\"ל אף שיהיו אלף מומרים לא יתבטלו הפ\"ז מצות שכדאי שיתקיים כל העולם"],[1900640139,"בשבילו וד\"ל), והענין הוא [כ]דכתי' יתבררו ויצטרפו ויתלבנו והרשיעו רשעים, היינו שקודם ביאת הגואל צדק צ\"ל בירור שלא יהי' טו\"ר מעורבים כו' כ\"א שירשיעו רשעים שיהי' ניכרים שהם רשעים וד\"ל, וכמו בחטא העגל שנשתברו הלוחות הראשונות, ואיתא במדרש שאלמלא [לא] נשתברו לוחות הראשונים הי' מתקיים מצותיו ית' יותר וביהמ\"ק לא הי' נחרב (למשל באדם זיווג ראשון האה' גדולה מזיווג שני), וכמו\"כ במ\"ת שהי' ג\"כ בחי' חתן וכלה וכמ\"ש והוא כחתן יוצא כו' היינו שהתורה שהוא וחכמתו א' כידוע הי' בבחי' חתן לשון נחות דרגא ונסוב אתתא, שהוא קדוש ומובדל מגדר עולמות, והוא בחי' השפלה אצלו ית', וכנס\"י היא בחי' כלה לשון כלתה נפשי [להוי' וכלה הוא ג\"כ כמ\"ש] ואל אישך תשוקתך כו' וד\"ל. ומי גרמו למעשה העגל המה הערב רב כמ\"ש וירא העם כי בושש משה כו' ופירש\"י כ\"מ שכתב העם היינו ערב רב, והנה אם היו [הערב רב הנ\"ל] אותן הרשעים ממש במצרים לא הי' יכולים לקלקל לכללות ישראל, אך כשהם מעורבים בין ישראל יכולים לקלקל כיון שלא נתבררו, לכן מחמת עונותיהם יכול להיות [איזה] קלקול לישראל, וכן עתה כשמתברר מישראל ויוצא מגדר כלל ישראל אינו יכול לקלקל עוד לישראל במעשיו הרעים ולהיפך אם לא הי' מתברר וד\"ל.\n<b>ובאמת</b> הדבר תלוי זה בזה שכיון שנעשה א' יר\"ש כנ\"ל לכן בהכרח נעשה בירור שכנגד פסולת גמור המה האפיקורסים ומומרים כמ\"ש ויתבררו ויתלבנו ויצטרפו למשל צירוף הכסף שכשאין הכסף מנוקה ומבורר מכל סיג ופסולת אזי גם הפסולת יש בו מעט כסף, אבל כשמתברר הכסף כ\"כ עד שאין בו"],[1900640149,"שום פסולת כ\"א כסף נקי מאד אזי אין בהפסולת שום כסף, וכ\"ה בענין בירור צדיקים ורשעים כיון שנתברר צדיק א' עד שאין בו שום פסולת כלל וכלל אזי אין בהפסולת שום טוב וזהו\"ע הזהר בגחלתן של ת\"ח שלא תכוה. וכמ\"ש במ\"א בארוכה בענין האפיקורסים המפורסמים שהיו בימי הבעש\"ט הקדוש ז\"ל נ\"ע. ובטוב מסיימין וד\"ל.\n<b>"],[1900640023,"<b>והנה יש להבין וכו' דמלכא משיחא</b>\n<b>והנה</b> יש להבין שרש ענין הנ\"ל בענין תשובה ומע\"ט ואיך דמלכא משיחא אתא לאתבא צדיקייא בתיובתא, צדיקייא דוקא (שזהו מה שנתלבש יעקב בבגדי עשו החמודו' לקבל הברכו' דשם אלקים כו' שיתקן שרשו ע\"י שם מ\"ה דתו\"מ דוקא ושיגיע עי\"ז תוס' אור ליעקב והוא ע\"י התשובה לצדיקי' דוקא שזהו כללות עיקר ענין הנ\"ל). דהנה באמת אין זה מובן כלל דצדיקים יעשו תשובה איך שייך התשובה בצדיקי' שלא חטאו מעולם כו'. וגם יש להבין הטעם למה בע\"ת גדולי' מצ\"ג כנ\"ל, וכי בשביל שלא חטאו מעולם יוגרע ממעלת הבע\"ת ששב על חטאו כו'. וגם יש להבין מה זה שתלוי תשובת הצדיקי' בביאת משיח דוקא שהוא אתא לאתבא כו'. והנה תחלה יש להקדים בכללות ענין צדיקי' ובע\"ת שזהו בחי' מ\"ה וב\"ן, צדיקי' בבחי' מ\"ה ובע\"ת בבחי' ב\"ן ומשיח אתא כו' היינו לייחד יחוד דמ\"ה וב\"ן לשלימותו כו'.\n<b>ולהבין</b> זה הנה ביאור ענין דבחי' מ\"ה וב\"ן יובן מענין בחי' רצוא ושוב למעלה, דהנה אנו רואי' בכל הברואי' שיש בהם בחי' רו\"ש הסתלקות והתפשטות ויובן זה במלאכי' עליוני' עד הגלגלי' דעשי', דהנה המלאכים אומרי' קדוש וברוך והמה ב' הפכי', קדוש הוא בחי' העלא' להיותו קדוש ומובדל בערך מן ההשגה דלית מחשב' תפיס' בי' כלל וברוך כבוד ה' הוא בחי' המשכה וירידה למטה מטה שיורד ממקומו העליון כו', ומוכרח שמסתעף מהשגות אלה שהן ב' הפכי' ב' מיני התפעלו' שהן ב' הפכי' והיינו רצוא ושוב שמהתבוננו' דקדו\"ש יתפעל בבחי' רצוא שהוא בחי' הביטול וההזזה ממקומו ליכלל במקור חוצבו בבחי' אי\"ן ומהתבוננו' דברו\"ך כבוד כו' יתפעל בבחי' שו\"ב מפני שזהו גילוי אלקו' למטה בקרוב יתפעל בירא' ופחד אלקי' וזהו בחי' שוב, ואנו רואי' ב' עניני' אלה בכל עבודה שבלב באדם למטה בהיות ידוע שיש ב' מיני התבוננות בתפלה הא' בבחי' סובב כ\"ע שהוא בחי' קדו\"ש שמובדל ומרומם לבדו ומתנשא מימות עולם\nרפב&gt;C0&gt;\nוהיינו למעלה מהיו' בחי' מקור ושרש לחיי העולמי' להשפיע מאין ליש ונק' מלך יחיד קודם שנק' חי העולמים כו', ודבר זה נפלא מן ההשגה שבמוח היינו שלא יש לו תפיס' ממש איך הוא סובב ומקיף כו' רק שמשיג איך שאין ערוך לעולמו' הנשפעי' מאין ליש לגבי עצמות אלקו' כלל וכי לית מחשב' כו' וזהו בחי' קדוש הוי' כו', ומזה יתפעל בלב בבחי' רצוא שהוא האהבה והתשוקה הנפלאה בבחי' התכללו' לצאת מחומר גופו המחשיך כו' להיו' נפשו צרורה בצרור החיים העליונים כו' שכל התפעלו' תשוקה וביטול לאי\"ן האלקי היינו דוקא כאשר מרחוק ה' נראה לו איך שהוא קדוש ומובדל ומופלא כו', אך מהתבוננו' הב' איך שהוא ית' ממלא כ\"ע שהוא כח הפועל האלקי בנפעלי' מאין ליש וכמ\"ש שאו מרום וראו מי ברא אלה כו' כאשר יעמיק מחשבתו ודעתו איך שבכל רגע ורגע נמשך חיות העולם ממקור החיים שמחי' את הכל בפ\"מ, יתפעל ביראה ופחד אלקי' לפי שכל פחד וירא' בא מצד הקירוב כשהמלך קרוב אליו דוקא וכמו ובאו במערות צורי' מפני פחד ה' כו' והיינו כאשר ההשג' אלקי' נתפסת ונרגשת דוקא בכלי המוח ממש כפי ערכו ונרגש בחוש בהרגשת המוח בחוש הטבעי (בל\"א ער דערהערט די זאך אין מוח כו'), וכמ\"כ התפעלות הלב בא במורגש גדול בירא' ופחד כרואה מקרוב ממש וזהו בחי' שוב ששב לאחור שהוא כמו הנרתע מאיזה פחד ישוב לאחו\"ר כמ\"ש וירא העם וינועו ויעמדו מרחוק כו' שבודאי זהו שבא אל עצמו דוקא היפך ההעלא' והזזה ממקומו בהסתלקו' דבחי' הרצוא כו' (ואע\"פ שבפחד וירא' יש ביטול והזזה ממקומו יותר (בל\"א ער ווערen.ט צו רירעט פון א]רט כו') אבל הוא בתוך תוכו וכמו וארכבותי דא לדא נקשן ולא מבחו\"ץ כלל), וזהו מא' אם רץ לבך בהסתלקו' דתשוקה שבלב מצד בחי' ההפלא' באמרו קדו\"ש כו' מיד שו\"ב כו' באמרו ברו\"ך וכמ\"ש במלאכי' וחיו' הקדש והחיו' רצוא ושוב שהוא ע\"ד הנ\"ל בהתבוננו' דסובב וממלא כו', כשאו' קדו\"ש מתפעלי' ברצוא מצד העדר ההשג' בקד\"ש העליון באי' לבחי' ביטול לאין לגמרי למעלה מהתפעלות אוי\"ר במורגש כלל מאחר שנפלא ומובדל מהם אך כאשר באין לכלל השג' ותפיס' כמו השג' דבחי' ממלא הנ\"ל אומרי' ברוך מלמעלה למטה כו', ומאחר שההשג' אלקי' זאת נתפס ונרגש בכל מלאך לפי מדרגתו ע\"כ בא להתפעלו' ירא' ופחד שזהו בחי' שוב בהתפעלות מורגש\"ת דוקא לפי ערך התפעלו' השגתו במחשבה ותפיס' דוקא בגילוי אור מקרוב. וזהו שהשרפי' או' קדוש בבחי' רצוא ביטול בלתי מורגש"],[1900640037,"בהשגתם כלל והאופני' או' ברוך בהתפעלו' מורגשת בהשג' ומדות כו' לפי שהשרפי' הן בעולם הבריא' דאימ\"א עילא' מקננא בכורסייא כו' בבחי' קדו\"ש ואופני' ביצי' שהשגתם בבחי' ממלא או' ברו\"ך וברעש גדול דוקא ומתנשאי' לעומת השרפי' שאו' קדוש לפי שזהו היפוך ממש שבשרפי' ההשג' נפלא' ובאופני' בא בגילוי ובמורגש ע\"כ מתנשאי' לעומ\"ת ולנגד השרפי' ואו' ברו\"ך וד\"ל.\n<b>והנה</b> ידוע דכל מה שנראה בנבראי' יש מאין מוכרח שיש שרש ומקור לזה במקור המחי' ומהווה אותם מאין ליש לכל אופן מדרג' פרטי' שנמצא בבריא' יש מאין כו' ובפרט בענין החיות רצוא ושוב שנמצא בכללות העולמו' ובכל נברא ומלאך בפרט כנ\"ל בענין קדוש וברוך בשרפי' ואופני', כך בכל עולם בכל מלאך יש בחי' רו\"ש אוי\"ר כו' כידוע, וא\"כ ודאי שיש במקור כל חיי העולמו' שהוא בחי' מל' דאצי' שמחי' את כולם מאין ליש בחי' רצוא ושוב כזה רק שהוא בערך נבדל, והיינו בבחי' אלקות ממש שבבחי' אצי', ומבחי' הרצוא שבמל' דאצי' נמשך אור וחיו' אלקי כזה במלאכי' שיהי' בהם בחי' רצוא כמו בהשג' דקדו\"ש הנ\"ל בשרפי' ומבחי' השוב שבמל' דאצי' נמשך במלאכי' בחי' השוב כמו באופני' שאו' ברוך כו', וכך כל פרטי פרטיות עניני העבודה האלקי' בהשג' ובמדות אוי\"ר שנק' חסדי' וגבורו' כמו בחי' ומדרג' האהבה במיכאל ומחנהו וירא' ופחד בגבריאל ומחנהו כו' הכל הוא בא ונמשך מלמעלה מבחי' אור האלקי שהוא בחי' מל' דאצי' עד כל פרט ופרט שבהם כפני ארי' להימין ופני שור מהשמאל ופני נשר כו' אשר מסתעפי' לרבבו' מדרגו' לאין שיעור כו' (וכמו שאנו רואי' בעבודה שבלב בכ\"ד נש\"י שמסתעפי' לרבבו' אלפי' מדריגו' בכל דור ודור והכל נמשך מלמעלה דהיינו ממקור חוצבם האלקי שהוא בשם הוי' לכל נשמ' כפי מדרגתה כו').\n<b>ומעתה</b> יש להבין ענין רו\"ש שבאצי' עד שיתכן לומר שמבחי' רו\"ש דאצי' נמשך לעולמו' כנ\"ל (עד הגלגלי' דעשי' שגם הם בבחי' רו\"ש שמשתחוי' וחוזרי' בסבובם תמיד כו'), דהנה במ\"ש והחיות רצוא ושוב זהו כמראה הבזק שהוא כמו הלהב היוצא מן החרסית כו' שעולה ומסתלק וחוזר ונח בחרסית וחוזר ועולה וכך הוא תמיד רו\"ש כו', וכך יובן בבחי' מל' דאצי' מקור כל העולמו' דכתיב כי ה' אלקיך אש אוכלה כו' כאש הדולק בנר שמתאחז בפתילה ונמשך"],[1900640050,"אחריה וחוזר ומסתלק ועולה וחוזר ונח כו', ומה שחוזרת ונמשכת להתאחז בפתילה זהו מטבע האש שיומשך ויתאחז בדבר מה שיפול בו וגם יש בו מבחי' כליון לכלות דבר מה שמתאחז בו ואמנם עיקר מהות שלו הוא ההסתלקות למקורו לאש היסודי רק שבנוחו על דבר מה יכלהו ליכלל בו כו', וכליון זה עושה בדרך הסתלקות שעולה ומסתלק והוא ענין הדליקה שהאש דולק כו', דלשון דליקה הוא הקפיצה שקופץ ומסתלק ובזה דוקא יכלה וידלק הדבר שכל שאין דבר מה שיתאחז בו לא ידלק כלל, כי אש עצמו בלא התפשטות בדבר מה יעלה מיד כמו שלהבת פשוטה בלתי מורכבת בדבר מה כלל שלא תעמוד כלל אלא מיד תעלה ותסתלק כלפי מעלה עד שתכלה באש היסודי ואינה חוזרת עוד כו', משא\"כ אור הנר שאחוז בפתילה שתמשיכהו להדליקה וחוזרת להסתלק וחוזרת ונח וכך הוא תמיד ובסיבת עלי' וירידה שבה תאיר אור אבל בלא פתילה ושמן אינו אור המאיר כלל וד\"ל.\n<b>וכדוגמא</b> זאת יובן בנר ה' נשמת אדם, דהנה אור זרוע לצדיק עליון שהוא אור אלקי כמו שהוא למעלה בלתי מורכב בדבר מה שכלול ונדבק למעלה בצרור החיים ממש כו', וכאשר אור זה נזרע היינו שנמשך למטה בבחי' בריאה יש מאין כמו אתה בראת כו' יצרת כו' נמשך בבחי' מהות ויש דבר מה במציאו', ונר הוי' שנקראת כנר הדולק בשמן ופתילה והוא ענין התלבשות הנשמה האלקית בנפש הטבעי בשכל ומוח גשמי כו' כידוע בענין ואהבת בכל לבבך בשני יצרי\"ך כו' שאור אלקי זה שבנשמת הוי' מלובש בהשגו' מוחי' והתפעלו' מדות דנה\"ט במוח ולב הגשמי כו', וזהו כדמיון אור הנר שנאחז בשמן ופתילה כנ\"ל שבודאי טבע אור הנשמה האלקי' ליכלל למעלה במקור חוצבה ולא לעמוד כלל רק מצד בחי' התלבשותה והרכבתה למטה בנפש החיוני' הטבעי' יתאחז האור האלקי דנשמ' בכולה וידליקנה דהיינו שתפעול גם במוח ולב הגשמי דנה\"ט שתתפעל גם היא בבחי' כליון והסתלקו' לצאת מחומר הגופני במס\"נ וכענין התשובה כו' וזהו כאש האוכלת דבר שמורכב בו, אבל יש בו מבחי' ההשבה וההנחה מלמעלה למטה עכ\"פ שהרי חכמה ומדו' דנשמ' מאירי' ומתפשטי' בחכמה ומדו' ורצון דנה\"ט שפועל בחי' הכליון ג\"כ כו', וא\"כ מובן עכ\"פ שזהו בחי' רו\"ש בחי' הרצוא בעצם הוא בחי' ההסתלקו' במקורה בעצם שאינו נק' אור כלל כי אין לו במה להתאחז עדיין ובחי' הרצוא בהאחז האור בכלי כנשמ' בגוף וכאש הדולק בפתילה כנ\"ל, והב' בחי' השוב שהוא בחי' התפשטו' האור והמשכתו במה שנמשך להתאחז בדבר מה אע\"פ שחוזר ועולה כו' אבל חוזר ונח וחוזר ועולה כנ\"ל ונמצא כלול"],[1900640062,"מרו\"ש עלי' ויריד' כא' ממש וד\"ל. והנמשל מכל זה יובן למעלה בבחי' מל' דאצי' שנק' נשמת כל חי כו' שנק' בחי' ממלא כ\"ע כנשמה שממלא את הגוף כנ\"ל הנה ע\"ז א' כי א\"ש אוכל\"ה הוא כו' מפני שהוא בבחי' רו\"ש דוקא ע\"ד הנ\"ל, וזהו בחי' התפשטות אור וחיות האלקי בכל העולמות בבחי' חסדי' שיורד מגבוה לנמוך ואע\"פ שנמשל לבחי' אש אבל הוא נמשך אחר הדבר שמתאחז בו כנ\"ל והיינו בחי' השוב כנ\"ל, ובחי' הרצוא הוא בחי' עליי' המל' שעולה האור וחיו' האלקי למעלה מעלה בלתי נמשך למטה שזהו בחי' הגבורו' דאש העולה כמ\"ש עולת תמיד שעולה תמיד כו' ואמר אש תמיד תוקד כו' (וכמ\"ש בזוהר ע\"פ אלקים אל דמי לך דאלקי\"ם שהוא בחי' המל' שמחי' את כל העולמו' קארי תדיר לנהורא עילא' שהוא שם הוי' דסובב כו' כידוע, ובחי' רצוא הב' כשאינו מורכב בדבר מה כו' היינו בחי' המל' כמו שהיא למעלה באצי' טרם שנמשך להיות מקור לבי\"ע (כמ\"ש בזוהר ע\"פ שחורה אני כו' [אז] עיר' גרמה כו'. ובאמת מ\"ש הוי' אלקיך אש אוכלה הוא לא קאי על בחי' מל' דאצי' שבבי\"ע דא\"כ מהו שאמר הוי' אלקיך דוקא אלא קאי על א\"ש דהוי' דאור תו' דכתי' מימי[נו] אש ד\"ת כו' שלמעלה מבחי' הש[פ] ע האלקי' שבבי\"ע כו', ואע\"פ שא' גבי סנה שבוער באש והסנ\"ה איננו אוכל שזהו אור ואש דתורה שאינו שורף ומכלה כלל רק אור המאיר כידוע בפי' ותור\"ה או\"ר, וע\"[כ] א' הוי' א\"ש אוכל\"ה הוא היינו כאשר בא אור דשם הוי' שבתור' לברר עה\"ד טו\"ר מגבורו' קשו' שבו שצריך שריפה וכליון דוקא שאז נק' הוי' א\"ש שאוכלת א\"ש קשה דנוגה כו', אבל למשה הראהו הסנ\"ה בוע\"ר כמו שיהי' לע\"ל כו' שהן גבורו' דנוגה שנדמה לסנ\"ה שבוער באש הוי' ואיננו אוכל כלל, כי זהו לאחר הבירור והתיקון דשם מ\"ה דבחכמ' דאור התו' את[ברי] רו ולא דרך כליון כאש בפתילה [דו] לקת, וע\"כ נתפלא ביותר וא' אסורה ואראה את המראה הגדולה כו' מדוע לא יבער הסנה, וזה יהי' בימות המשיח ... צדיקי' דוקא כמשי\"ת שלהיו' יחוד עליון .. וב\"ן באופן שיהי' שם הוי' כאש בוער ולא יכלה כלל, וכידוע דסנ\"ה"],[1900640074,"זה הי' ג' עולמו' ד[בי\"ע] ... באלקי' דשם ב\"ן שמלובש בו שהוא כשם מ\"ה ממש [והס] נה איננו אוכל כו', וזהו תשלום הכונה שבמ\"ת כמ\"ש יקימנו ונחי' ל[פניו] .. en.כו' וד\"ל).\n<b>אך</b> הנה כל מה שמבואר למעלה בבחי' רו\"ש מאצי' לבי\"ע שזהו כנשמ' בגוף וכאש הדולק כנ\"ל לא יתכן כזה לומר בע\"ס דאצי' עצמן שנאצלו מעצמות המאציל כי הרי נקראו בשם אור ולא בשם אש כלל, וידוע ההפרש בין אור לאש שהאור אינו רק ענין ההארה שמאיר והאש הוא השורף ומכלה בדליקה כו', אמנם כמו שטבע האש לעלות וכולל עלי' ויריד' כא' כנ\"ל כך הוא גם באור המאיר גם שאורו מתפשט אבל יש בו עלי' והתכללו' למקורו שהוא עצם המאור, ומה שיש באור בחי' עלי' וירידה הסתלקות והתפשטות זהו בא ג\"כ מכח מקורו (כנ\"ל ברו\"ש דאצי' שממנו מקור רו\"ש דבריאה כו') שהוא עצמו' המאציל שהאציל בבחי' הסתלקו' והתפשטו', רק שההתפשטות תחלה להסתלקו' ונק' מטי ולא מטי שבתחלה נמשך ומתפשט להאיר אור ומיד חוזר ומסתלק וחוזר ומתפשט ונסתלק וזהו מול\"מ כידוע שהוא מלמעלה למטה מן המשפיע אל המקבל שמזה בא באור הנאצל כבר ג\"כ בחי' רו\"ש אך בחי' הסתלקו' והתכללו' האור במאור תחלה ואח\"כ חוזר ומאיר בהתפשטו' וכנ\"ל וד\"ל.\n<b>ותחלה</b> יש להקדים שרש בחי' ע\"ס דאצי' שנק' בשם אורות איך שאין ערוך כלל להם לגבי המאור והיינו יותר משאין ערוך לבריא' עם הבורא הנ\"ל במשל אש הדולק בנר. דהנה ידוע בפי' ענין האצי' שזהו כמו ויאצל מן הרוח על הזקני' דרוחו של משה ממש נאצל עליהם וכתי' ותנח עליהם הרוח ויתנבאו, אבל ודאי אין ערוך להרוח שנחה עליהם לגבי רוחו של משה כי זהו רק אצילו' רוח בבחי' דילוג גדול כחלק קטן נבדל מגדול ורחוק ממנו הרבה בערך כמו עד\"מ כח הפועל שהניח כח מצומצם בדבר הנפעל שמסלק ידיו הימנו שלא נשאר בו רק כח הרשימו לבד מעצם כח הפועל כו', וכך יובן ערך אור הנאצל שבא מכח עצמות המאציל שהוא רחוק ונבדל בערך לאחר שסילק כח עצמותו ונתרחק האור מעצמו' המאור כו', ואע\"פ שמאיר מעצמו' המאציל להאיר אור בנאצל זהו כמו כח הפועל בעשי' שנשאר רושם כחו לבד כנ\"ל, או כמו שמו של אדם שרחוק ומובדל"],[1900640085,"מעצם האדם כידוע, וכך ע\"ס דאצי' נק' רזא דשמי' כו' כשם ע\"ב דאור החכמ' כו' שנאצל מעצמו' המאציל והוא בבחי' דילוג המדרג' וכמו בבחי' עשי' נבדלת כנ\"ל, וא\"כ יותר אין ערוך לנאצל לגבי המאציל מערך הנברא לגבי הבורא שהבריא' יש מאין עכ\"פ כח הפועל אלקי בתוך הנפעל כנ\"ל במשל אש הדולק כו' אבל אורו' דאצי' הן אורות פשוטי' שבלתי מורכבי' שמסתלק תמיד ונכלל בעצמו' וזהו פי' ע\"ס בלי מ\"ה בלי מהו\"ת כו', אך זהו בתחלת ההארה שמאיר מעצמו' המאציל כמו שהאיר להיו' מציא' אור החכמ' דאינו רק הארה נבדלת מעצם החכמ' שבא\"ס שנק' חכים ולא בחכמ' ידיעא כו' וכך בכל הספי' לא שייך בזה בחי' רו\"ש כלל מאחר שנק' ע\"ס בלי מ\"ה בלי מהו\"ת כלל מטעם ביטולן בעצמו' כאור הבלתי מורכב כו', אבל לאחר שכבר האיר והמשיך לע\"ס דאצי' במהות ומציאות דבר מה והיינו כאשר האורו' דע\"ס מלובשי' בכלים כמו חכמ\"ה מוח\"א חסד דרועא ימינא כו' שנק' בשם תקונין אזי יתכן בזה בחי' רו\"ש, דלאחר שנאצלו מן העלם העצמו' לגילוי מהו' בפ\"ע בכלים מכלים שונים יפול בזה ענין רצוא ומיד שוב כו' היינו שעולה האור מן הכלי וחוזר ונח בכלי וחוזר ועולה כו' כדמיון האור בשמן ופתילה כנ\"ל (אבל אור בלא כלי עדיין לא יתכן בחי' רו\"ש כלל אלא תמיד בטל ונכלל כו' כנ\"ל), ורו\"ש זה בא מכח עצמו' המשפיע שמשפיע בבחי' מול\"מ והיינו מפני שמצד עצמו' המשפיע שנבדל בערך מן השפע הזאת מסלק אורו לעצמותו ומצד שחפץ חסד הוא יטיב ויאיר, ותחלה יחפוץ בחסד ויאיר וזהו בחי' מטי ומיד חוזר ומסלק את האור שנק' לא מטי ויחשך מקור אורם וחוזר ומאיר כו', ומזה יומשך בנאצל כמו שהוא בכלי בחי' רצוא להכלל בעצמו' מצד בחי' לא מטי שבא אחרון מן המשפיע, ובחי' שוב להתפשט בכלי בא מכח בחי' מטי דמשפיע (כמו חותם המתהפך דמה שבא בחותם ראשון בא בנחתם אחרון כך מה שבמשפיע ראשון בא במקבל אחרון וד\"ל).\n<b>והנה</b> לפי שאור השפע שבא בנאצלי' הוא עולה בבחי' רו\"ש עכ\"פ כנ\"ל ע\"כ גם ענין השפע דע\"ס דאצי' בבי\"ע ע\"י בחי' המל' כנ\"ל בא ג\"כ באופן שיהי' בהם בחי' רו\"ש דוקא, דהיינו מבחי' רצוא שבאור הנאצל שבא מכח בחי' הסתלקו' השפע דעצמו' המאציל שנק' לא מטי כנ\"ל הוא הנק' קד\"ש העליון באצי', ומזה נמשך בשרפי' וכה\"ג שאו' קדו\"ש בתשוקה והתכללות מצד בחי' הפלא' והעדר"],[1900640096,"ההשג' והוא בחי' ביטול והסתלקו' למעלה מצד שנבדל ומרומם דלית מחשב' תפיס' כו' כנ\"ל, ומבחי' שו\"ב שבאור הנאצל שבא מכח בחי' התפשטו' אור המאציל בנאצל שנק' בחי' מטי כנ\"ל מזה בא במלאכי' באופני' שאו' ברו\"ך כו' בהתפעלו' מורגש בהשג' והוא בבחי' ירא' ופחד אלקי' שמקרוב דוקא כנ\"ל en.באריכות וד\"ל.\n<b>ומעתה</b> יש להבין מה שענין בחי' רו\"ש הנ\"ל נק' בל' המקובלים בשם מ\"ה וב\"ן דוקא ובכל עולם ועולם לפי ערכו ובכל מלאך ונשמ' שיש בו מבחי' רו\"ש כנ\"ל היינו בחי' מ\"ה וב\"ן שבו עד בחי' פרצופי' עליוני' דאצי', כל בחי' רו\"ש דכל א' היינו בחי' מ\"ה וב\"ן שבו כו' והיינו דבחי' הרצוא שבנברא שהוא בחי' העדר ההשג' והתפיס' ע\"כ נכלל ובטל כו' הוא בחי' מ\"ה שבו וכמו מה פשפשת מ\"ה ידעת, דכאשר ההשג' האלקי' עמוק ממנו ולא יכיל לאדבקא כו' ונבדל ומופלא הימנו כמו בחי' קדו\"ש הנ\"ל עד שאור האלקי אצלו למעלה מכלי השגתו בערך נבדל כו', אזי נק' בחי' מ\"ה כלו' מ\"ה פשפשת שלא השגת כלום כו' וכמו החקר אלוה תמצא כו', וכאשר בא ונמשך אור האלקי בהשג' ממש כמו בחי' ברו\"ך דהיינו בחי' ממלא כ\"ע עד שנתפשט בכלי המוח והתפעלו' הלב במורגש כו' היינו בחי' ב\"ן, דפי' ב\"ן מלשון בינ\"ה שמבין הדבר ומשיגו והוא ענין ההתבוננ\"ו' בגדולות הבורא ית' שהוא בחי' התפשטותו להחיו' העולמות כנ\"ל (אבל מ\"ה הוא בחי' מה דחכמ' שלמעלה מהשג' דבינה כידוע שהחכמה הוא בחי' אי\"ן כו' ובינה הוא בחי' יש והיינו ענין מ\"ה וב\"ן דרך כלל), וא\"כ יובן מזה בירידת אור השפע הזאת דרו\"ש שנק' מ\"ה וב\"ן מעצמות המאציל עד הנבר\"א שלמטה זהו ג\"כ עד\"ז שמבחי' מ\"ה שבעצמו' המאציל נמשך בחי' מ\"ה בנאצלי' ומהם נמשך בנבראי' בחי' מ\"ה ומבחי' ב\"ן של עצמו' המאציל יורד בנאצלי' ומהם נמשך בחי' ב\"ן בכל נברא כו' דהיינו שבחי' מ\"ה ביטול לאי\"ן דשרפי' שאו' קדוש שרשו הראשון משם מ\"ה העליון שבעצמו' המאציל ובחי' ב\"ן דאופני' שאו' ברו\"ך שרשו en.הראשון בבחי' שם ב\"ן העליון דעצמות המאציל וד\"ל.\n<b>וביאור</b> הענין מובן מכל הנ\"ל דבחי' רו\"ש שבאצי' שמקבל מבחי' מול\"מ דמאציל היינו כאשר מאיר בנאצל מבחי' ולא מטי דעצמות המאציל שזהו בחי' הסתלקות אור המאציל אל עצמותו מזה נמשך בחי' מ\"ה גם באור הנאצל להיו' בבחי' הרצוא כנ\"ל ומשם נמשך מ\"ה זה בנברא שאו' קדו\"ש ומובדל"],[1900640107,"כו' כנ\"ל, דכמו שהנברא או' קדוש לגבי הבורא הרי יותר אין ערוך מנאצל לגבי המאציל להיו' קדו\"ש ומובדל מהנאצלי' כו' (וכידוע בענין עתיק יומין שנעתק ומובדל מיומין עילאי' דאצי' כו'), וזהו שנמשך בחי' הביטול דמ\"ה בכל הנבראי' עד שגם הגלגלי' דעשי' משתחווי' ואו' שירה כו' וד\"ל, ומבחי' השו\"ב שהוא בחי' מטי דמאציל בנאצל נמשך בחי' שוב בנאצל והוא בחי' ב\"ן שבו שמאיר ומתפשט בכלי דוקא כנ\"ל וממנו נמשך לנברא בחי' ב\"ן שבו שהוא בחי' ההשג' והתפיס' בכלי דוקא שנא' ברו\"ך כנ\"ל עד הגלגלי' שמקבלי' מהאופנים שבהן ג\"כ בחי' שו\"ב שהוא בחי' ב\"ן וד\"ל. ונמצא דבחי' מ\"ה וב\"ן שזהו בחי' רו\"ש נמשך בהשתלשלות דאבי\"ע מעצמות המאציל בכל פרטי פרטיהם עד סוף כל המדרגות בסוף עולם העשי' שהן ט' גלגלים הסובבי' כו' כנ\"ל.\n<b>אך</b> הנה הגם שבחי' מ\"ה וב\"ן שניהם באי' בהשתלשלו' דאבי\"ע כנ\"ל מ\"מ יש הפרש גדול בין בחי' מ\"ה לבחי' ב\"ן והוא בדבר א' במה שאנו רואי' דמבחי' שם מ\"ה לא יומשך שום שפע לחיצוני' כלל וכמא' אין רע יורד מלמעלה, דשם מ\"ה הוא בבחי' האי\"ן דחכמ' דשם הוי' דא\"א להיות נמשך משם אור ושפע יניק' לקליפו' כלל דלא יגורך רע כו', אבל מבחי' שם ב\"ן מקבלי' החיצוני' יניק' ושפע בריבוי ההשתלשלו' שבעה\"ד טו\"ר עד שמקבלי' מבחי' אחוריי' דאלקי' ונק' אלקי' אחרים והוא במ\"ח צרופי' האחרונים שנק' ח\"ם כו' והן הע' שרים שמקבלים משמרי האופני' שזהו מאחוריי' דב\"ן דעשי' כו'. וביאור הענין הזה ידוע הוא במה שאנו רואי' בגלגלי' הגשמיי' שיש בהם כו\"מ דשר הארץ מקבל מכוכב ומזל פרטי כידוע בענין אין מזל לישראל משום דחלק אותם לכל העמי' כו', והנה הגלגל עם"],[1900640118,"הכו\"מ שבו משתחווי' בסיבובם כלפי שכינה שבמערב כידוע, אך אין זה בחי' ביטול אמיתי לאי\"ן האלקי כצבא ה' העליונים כאופני' וחיו' הקדש, אלא עד\"מ ביטול הדוכוס לפני המלך הגדול, אע\"פ שמתבטל ממציאותו לגמרי היינו לפי שהמלך גדול ממנו הרבה אבל לא שנתבטל בעצם ממקום גדולתו אפי' כמלא נימא באופן שלא יתנשא כלל בארץ ממשלתו, כי מתנשא ומשתרר בארצו כמו שהוא בעצמו מרומם שם כמלך הגדול בארצו, א\"כ אין זה ביטול בעצם כלל דהיינו לא שמצד עצמו אינו כלום אלא שמבטל עצמו לפני הגדול ממנו ונק' ביטול העשוי לפי שעה ולא שהוא בטל בעצם רק שמבטל עצמו מפני הגדול ממנו יותר, וכן חכם גדול שמשפיע לרבים חכמ' רבה שמתבטל לפני רב הגדול ממנו, אין זה ביטול אמיתי בעצם כי במקומו עומד להשפיע ולהיות ראש לתלמידיו בלי שינוי כלל רק שלפני רב הגדול ממנו יבטל ויכניע עצמו לפי שעה וכהנ\"ל, וכן בגלגלי' שמשתחווי' בסיבובם להיות שהן בחי' משפיעי' שרש הדברים וארמ\"ע למטה הן בבחי' יש ודבר מה כשר בארצו מושל ומשתרר, והן ע' שרי' שבכו\"מ שכל כוכב ומזל יכול להיו' בבחי' יש וגסות גמור כמו שר מצרי' א' לי יאורי כו', ואע\"פ שכלפי שכינה שבמערב משתחו' בסיבוב והוא השתחוא' רוחני' שבצורה של הגלגל כידוע, מ\"מ אין זה בחי' ביטול בעצם רק שמפני השכינה שהוא כח האלקי שמשפיע לצורת הנפש שבגלגל המזלות ישתחוו' כדוכוס ושר שמשתחוה למלך ובעצמו הוא יש ודבר למשול בארצו כו', וכחכם לפני גדול הימנו כנ\"ל שעושה ביטול בנפשו לפי שעה זו כו', וכך או' שירה בשעה שמשתחוי' וכמ\"ש וצבא השמי' לך משתחוי' לך דוקא מפני ש.. ועכ\"ז [ל] א יש בהם ביטול בעצם מאחר שיוכל לומר לי יאורי כו' בבחי' נפרד לעצמו, וכמו שא' על שר אדום אם תגבי\"ה כנש\"ר שמגביהי' עצמם בגסות הרוח ו.. והיינו בזמן הגלות דרישא שכיבת כו', ואע\"פ שיודעי' את רבונם ומשתחווי' בסיבובם כו' לקבל שפע האלקי וכאוה\"ע דקרו לי' אלקא דאלקיא וכתיב מלך אל[קים] ... וכן מי לא יראך [מל] ך הגוי\"ם כו' וכן יראו מה' כל הארץ וכה\"ג, יראה זו היא כמו ביטול העשוי לפי שעה כנ\"ל. וראי' לזה שהרי מסתעף מהם קליפ' דע\"ז לעבו[ד] ... אמרו וכי בשביל ה.. שקלקלו כו' מ\"מ הרי מתפעלי' בק.. שאו' מן עבודה זאת שמקריבי' ומקטירי' להם כו' כמ\"ש במ\"א עמ\"ש ויאמר אפרים א... וזהו כמשל העומד לפני המלך ..."]]});
